//! `memhub doc` command surface: ingest external reference documents
//! into the per-repo store, RAG-searchable through the same hybrid
//! recall path as facts/decisions/tasks.
//!
//! Documents are deliberately OPT-IN to recall — `doc_chunk` is never in
//! the default source-type set. They are user-initiated reference
//! material (a design spec, an API contract), not durable project
//! knowledge and not an agent claim, so ingestion writes directly with
//! `source = 'user'` and no review gate.
//!
//! Trigger invariant: SQLite `recursive_triggers` is OFF (see
//! `db::open_project`), so a foreign-key cascade delete of `doc_chunks`
//! does NOT fire `doc_chunks_delete_embeddings` / `doc_chunks_fts_ad`.
//! Every code path that drops a document's chunks therefore deletes the
//! `doc_chunks` rows EXPLICITLY first (which fires those AFTER-DELETE
//! triggers) and only then touches the parent `documents` row. The
//! `ON DELETE CASCADE` FK stays as a row-integrity backstop.

use std::fs;
use std::path::Path;

use rusqlite::{Connection, OptionalExtension, Transaction, params};

use crate::Result;
use crate::db;
use crate::models::{DocChunk, Document};
use crate::sync_md;

/// Largest chunk body (in chars) before a section is soft-split on
/// paragraph boundaries. Generous enough that well-structured docs chunk
/// at their natural section headings; the split only guards against a
/// pathologically long heading-free section.
const MAX_CHUNK_CHARS: usize = 2000;

#[derive(Debug, PartialEq, Eq)]
pub enum IngestStatus {
    Created,
    Updated,
    Unchanged,
}

#[derive(Debug)]
pub struct DocAddOutcome {
    pub doc_id: i64,
    pub title: String,
    pub path: String,
    pub chunk_count: usize,
    pub status: IngestStatus,
    /// True when this call flipped `[retrieval] include_docs_in_default`
    /// on for the repo (first successful doc add). The CLI surfaces a
    /// one-line notice so the behavior change is visible, not silent.
    pub enabled_default_recall: bool,
    /// True only for `add_global` when this call created
    /// `~/.memhub/global.sqlite` (first global write on the machine).
    /// Always false for the repo path.
    pub store_created: bool,
}

struct PreparedDoc {
    content: String,
    path_str: String,
    byte_len: i64,
    content_hash: String,
    resolved_title: String,
}

fn prepare_doc(file: &Path, title: Option<&str>) -> Result<PreparedDoc> {
    let content = fs::read_to_string(file).map_err(|e| {
        crate::MemhubError::InvalidInput(format!("cannot read {}: {e}", file.display()))
    })?;
    let canonical = fs::canonicalize(file).unwrap_or_else(|_| file.to_path_buf());
    let path_str = canonical.to_string_lossy().into_owned();
    let byte_len = content.len() as i64;
    let content_hash = sha256_hex(&content);
    let resolved_title = title
        .map(str::to_string)
        .filter(|t| !t.trim().is_empty())
        .unwrap_or_else(|| derive_title(&content, &canonical));
    Ok(PreparedDoc {
        content,
        path_str,
        byte_len,
        content_hash,
        resolved_title,
    })
}

struct IngestResult {
    doc_id: i64,
    status: IngestStatus,
    chunk_count: usize,
    /// `documents` table was empty before this ingest (the trigger for
    /// auto-flipping default doc recall). Connection-agnostic: true in
    /// the global DB only on the first `doc add --global`.
    was_first_doc: bool,
}

/// Connection-agnostic ingest core. Operates entirely on `tx`, so the
/// caller chooses repo vs. global DB. Does NOT commit — the caller
/// commits and then applies its target-specific config flip / sync.
fn ingest_in_tx(
    tx: &Transaction<'_>,
    doc: &PreparedDoc,
    actor: &str,
    mode: crate::config::RetrievalMode,
) -> Result<IngestResult> {
    let was_first_doc: bool = tx.query_row(
        "SELECT COUNT(*) FROM documents WHERE project_id = 1",
        [],
        |r| r.get::<_, i64>(0),
    )? == 0;

    let existing: Option<(i64, String)> = tx
        .query_row(
            "SELECT id, content_hash FROM documents WHERE project_id = 1 AND path = ?1",
            params![doc.path_str],
            |r| Ok((r.get(0)?, r.get(1)?)),
        )
        .optional()?;

    let (doc_id, status) = match existing {
        Some((id, old_hash)) if old_hash == doc.content_hash => {
            let chunk_count: i64 = tx.query_row(
                "SELECT COUNT(*) FROM doc_chunks WHERE doc_id = ?1",
                params![id],
                |r| r.get(0),
            )?;
            return Ok(IngestResult {
                doc_id: id,
                status: IngestStatus::Unchanged,
                chunk_count: chunk_count.max(0) as usize,
                was_first_doc,
            });
        }
        Some((id, _)) => {
            // Explicit chunk delete first so the AFTER-DELETE triggers
            // clear embeddings + FTS (recursive_triggers is OFF).
            tx.execute("DELETE FROM doc_chunks WHERE doc_id = ?1", params![id])?;
            tx.execute(
                "UPDATE documents
                 SET title = ?1, content_hash = ?2, byte_len = ?3,
                     ingested_at = CURRENT_TIMESTAMP
                 WHERE id = ?4",
                params![doc.resolved_title, doc.content_hash, doc.byte_len, id],
            )?;
            (id, IngestStatus::Updated)
        }
        None => {
            tx.execute(
                "INSERT INTO documents(project_id, path, title, content_hash, byte_len, source)
                 VALUES (1, ?1, ?2, ?3, ?4, 'user')",
                params![
                    doc.path_str,
                    doc.resolved_title,
                    doc.content_hash,
                    doc.byte_len
                ],
            )?;
            (tx.last_insert_rowid(), IngestStatus::Created)
        }
    };

    let chunks = chunk_markdown(&doc.content);
    insert_chunks(tx, doc_id, &chunks, mode)?;

    db::log_write(
        tx,
        actor,
        "documents",
        Some(doc_id),
        if status == IngestStatus::Created {
            "insert"
        } else {
            "update"
        },
        &format!("doc add: {} ({} chunks)", doc.path_str, chunks.len()),
    )?;

    Ok(IngestResult {
        doc_id,
        status,
        chunk_count: chunks.len(),
        was_first_doc,
    })
}

/// Ingest (or re-ingest) a markdown file into this repo's store.
/// Unchanged content (same SHA-256) is a no-op. Changed content
/// replaces every chunk.
pub fn add(start: &Path, file: &Path, title: Option<&str>, actor: &str) -> Result<DocAddOutcome> {
    let doc = prepare_doc(file, title)?;

    let mut ctx = db::open_project(start)?;
    let mode = ctx.config.retrieval.mode;
    let tx = ctx.conn.transaction()?;
    let r = ingest_in_tx(&tx, &doc, actor, mode)?;
    tx.commit()?;

    let enabled_default_recall = r.was_first_doc && maybe_enable_default_doc_recall(&mut ctx)?;
    sync_md::sync_if_enabled(start)?;

    Ok(DocAddOutcome {
        doc_id: r.doc_id,
        title: doc.resolved_title,
        path: doc.path_str,
        chunk_count: r.chunk_count,
        status: r.status,
        enabled_default_recall,
        store_created: false,
    })
}

/// Ingest a markdown file into the machine-global store (M9). A
/// global doc is a broadly-applicable guide visible to every repo
/// that has opted in. Requires `memhub global enable` in this repo.
/// The first global doc add flips `[global] include_docs_in_default`
/// in this repo's config (mirrors the repo-scoped behavior).
pub fn add_global(
    start: &Path,
    file: &Path,
    title: Option<&str>,
    actor: &str,
) -> Result<DocAddOutcome> {
    let doc = prepare_doc(file, title)?;

    let mut repo = db::open_project(start)?;
    crate::commands::global::ensure_enabled(&repo.config)?;
    let mode = repo.config.retrieval.mode;
    let store_created = !db::global_store_exists()?;

    let mut g = db::open_global()?;
    let tx = g.conn.transaction()?;
    let r = ingest_in_tx(&tx, &doc, actor, mode)?;
    tx.commit()?;

    let enabled_default_recall = r.was_first_doc && {
        if repo.config.global.include_docs_in_default {
            false
        } else {
            repo.config.global.include_docs_in_default = true;
            repo.config.save(&repo.paths.config_path)?;
            true
        }
    };

    Ok(DocAddOutcome {
        doc_id: r.doc_id,
        title: doc.resolved_title,
        path: doc.path_str,
        chunk_count: r.chunk_count,
        status: r.status,
        enabled_default_recall,
        store_created,
    })
}

/// Flip `[retrieval] include_docs_in_default` on (decision 90). Only
/// called when `was_first_doc` held — i.e. the documents table was
/// empty before this ingest — so the user-pointed write that
/// establishes the very first doc also wires up retrieval, while a
/// later `false` set by the user is never silently re-flipped by a
/// re-add or a second doc. Returns whether it changed the config.
fn maybe_enable_default_doc_recall(ctx: &mut db::ProjectContext) -> Result<bool> {
    if ctx.config.retrieval.include_docs_in_default {
        return Ok(false);
    }
    ctx.config.retrieval.include_docs_in_default = true;
    ctx.config.save(&ctx.paths.config_path)?;
    Ok(true)
}

fn insert_chunks(
    tx: &Transaction<'_>,
    doc_id: i64,
    chunks: &[(String, String)],
    mode: crate::config::RetrievalMode,
) -> Result<()> {
    for (ord, (heading_path, body)) in chunks.iter().enumerate() {
        tx.execute(
            "INSERT INTO doc_chunks(project_id, doc_id, ord, heading_path, body)
             VALUES (1, ?1, ?2, ?3, ?4)",
            params![doc_id, ord as i64, heading_path, body],
        )?;
        let chunk_id = tx.last_insert_rowid();
        let embed_text = crate::retrieval::doc_chunk_embed_text(heading_path, body);
        crate::retrieval::eager_embed_in_tx(
            tx,
            mode,
            crate::retrieval::SourceType::DocChunk,
            chunk_id,
            &embed_text,
        )?;
    }
    Ok(())
}

fn list_in_conn(conn: &Connection) -> Result<Vec<Document>> {
    let mut stmt = conn.prepare(
        "SELECT d.id, d.path, d.title, d.content_hash, d.byte_len, d.source,
                d.ingested_at,
                (SELECT COUNT(*) FROM doc_chunks c WHERE c.doc_id = d.id) AS chunk_count
         FROM documents d
         ORDER BY d.ingested_at DESC, d.id DESC",
    )?;
    let rows = stmt.query_map([], |r| {
        Ok(Document {
            id: r.get(0)?,
            path: r.get(1)?,
            title: r.get(2)?,
            content_hash: r.get(3)?,
            byte_len: r.get(4)?,
            source: r.get(5)?,
            ingested_at: r.get(6)?,
            chunk_count: r.get(7)?,
        })
    })?;
    rows.collect::<std::result::Result<Vec<_>, _>>()
        .map_err(Into::into)
}

pub fn list(start: &Path) -> Result<Vec<Document>> {
    let ctx = db::open_project(start)?;
    list_in_conn(&ctx.conn)
}

/// List documents in the machine-global store (M9). Requires this repo
/// to have opted in (`memhub global enable`), mirroring the gate on
/// `doc add --global`. Returns empty when the store does not yet exist
/// — a read never creates it.
pub fn list_global(start: &Path) -> Result<Vec<Document>> {
    let repo = db::open_project(start)?;
    crate::commands::global::ensure_enabled(&repo.config)?;
    match db::open_global_if_exists()? {
        Some(g) => list_in_conn(&g.conn),
        None => Ok(Vec::new()),
    }
}

/// Resolve a document by numeric id or by exact/canonical path.
fn resolve_doc_id(tx: &Transaction<'_>, ident: &str) -> Result<Option<i64>> {
    if let Ok(id) = ident.parse::<i64>() {
        let found: Option<i64> = tx
            .query_row("SELECT id FROM documents WHERE id = ?1", params![id], |r| {
                r.get(0)
            })
            .optional()?;
        if found.is_some() {
            return Ok(found);
        }
    }
    let canonical = fs::canonicalize(ident)
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_else(|_| ident.to_string());
    let by_path: Option<i64> = tx
        .query_row(
            "SELECT id FROM documents WHERE path = ?1 OR path = ?2",
            params![ident, canonical],
            |r| r.get(0),
        )
        .optional()?;
    Ok(by_path)
}

/// Resolve + delete a document and its chunks/embeddings within `tx`.
/// Connection-agnostic so the caller picks repo vs. global DB. Returns
/// false (leaving `tx` to roll back) when nothing matched `ident`.
fn remove_in_tx(tx: &Transaction<'_>, ident: &str, actor: &str) -> Result<bool> {
    let Some(doc_id) = resolve_doc_id(tx, ident)? else {
        return Ok(false);
    };
    // Explicit chunk delete first (recursive_triggers OFF) so embeddings
    // + FTS are cleaned; then the parent row.
    tx.execute("DELETE FROM doc_chunks WHERE doc_id = ?1", params![doc_id])?;
    tx.execute("DELETE FROM documents WHERE id = ?1", params![doc_id])?;
    db::log_write(
        tx,
        actor,
        "documents",
        Some(doc_id),
        "delete",
        &format!("doc rm: {ident}"),
    )?;
    Ok(true)
}

/// Remove a document and all its chunks/embeddings. Returns false when
/// no document matched `ident`.
pub fn remove(start: &Path, ident: &str, actor: &str) -> Result<bool> {
    let mut ctx = db::open_project(start)?;
    let tx = ctx.conn.transaction()?;
    if !remove_in_tx(&tx, ident, actor)? {
        return Ok(false);
    }
    tx.commit()?;
    sync_md::sync_if_enabled(start)?;
    Ok(true)
}

/// Remove a document from the machine-global store (M9). Requires this
/// repo opted in, mirroring `doc add --global`. Returns false when the
/// store does not exist or nothing matched `ident`. No markdown sync —
/// the global store has no rendered view.
pub fn remove_global(start: &Path, ident: &str, actor: &str) -> Result<bool> {
    let repo = db::open_project(start)?;
    crate::commands::global::ensure_enabled(&repo.config)?;
    let Some(mut g) = db::open_global_if_exists()? else {
        return Ok(false);
    };
    let tx = g.conn.transaction()?;
    if !remove_in_tx(&tx, ident, actor)? {
        return Ok(false);
    }
    tx.commit()?;
    Ok(true)
}

fn show_in_conn(conn: &Connection, ident: &str) -> Result<Option<(Document, Vec<DocChunk>)>> {
    let docs = list_in_conn(conn)?;
    let parsed_id = ident.parse::<i64>().ok();
    let canonical = fs::canonicalize(ident)
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_else(|_| ident.to_string());
    let Some(doc) = docs
        .into_iter()
        .find(|d| parsed_id == Some(d.id) || d.path == ident || d.path == canonical)
    else {
        return Ok(None);
    };

    let mut stmt = conn.prepare(
        "SELECT id, doc_id, ord, heading_path, body, created_at
         FROM doc_chunks WHERE doc_id = ?1 ORDER BY ord",
    )?;
    let chunks = stmt
        .query_map(params![doc.id], |r| {
            Ok(DocChunk {
                id: r.get(0)?,
                doc_id: r.get(1)?,
                ord: r.get(2)?,
                heading_path: r.get(3)?,
                body: r.get(4)?,
                created_at: r.get(5)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(Some((doc, chunks)))
}

pub fn show(start: &Path, ident: &str) -> Result<Option<(Document, Vec<DocChunk>)>> {
    let ctx = db::open_project(start)?;
    show_in_conn(&ctx.conn, ident)
}

/// Show a document from the machine-global store (M9). Requires this
/// repo opted in, mirroring `doc add --global`. Returns None when the
/// store does not exist or nothing matched `ident`.
pub fn show_global(start: &Path, ident: &str) -> Result<Option<(Document, Vec<DocChunk>)>> {
    let repo = db::open_project(start)?;
    crate::commands::global::ensure_enabled(&repo.config)?;
    match db::open_global_if_exists()? {
        Some(g) => show_in_conn(&g.conn, ident),
        None => Ok(None),
    }
}

/// Count of ingested documents (for `status` / dashboards).
pub fn count(start: &Path) -> Result<i64> {
    let ctx = db::open_project(start)?;
    let n: i64 = ctx
        .conn
        .query_row("SELECT COUNT(*) FROM documents", [], |r| r.get(0))?;
    Ok(n)
}

fn derive_title(content: &str, path: &Path) -> String {
    for (heading_path, _) in chunk_markdown(content) {
        if !heading_path.trim().is_empty() {
            // First heading's leaf is the most document-like title.
            return heading_path
                .rsplit(" > ")
                .next()
                .unwrap_or(&heading_path)
                .to_string();
        }
    }
    path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| "untitled".to_string())
}

/// Split markdown into retrievable chunks.
///
/// One chunk per ATX heading section; the heading line is kept in the
/// body so the chunk is self-describing, and `heading_path` carries the
/// ancestor breadcrumb (e.g. `Components > Buttons`). Content before the
/// first heading (including YAML front matter) becomes a leading chunk
/// with an empty `heading_path`. Fenced code blocks (``` or ~~~) are
/// never split: a `#` inside a fence is body text, not a heading, and a
/// soft-split for over-long sections only breaks on blank lines outside
/// a fence.
///
/// Returns `(heading_path, body)` pairs in document order.
pub fn chunk_markdown(content: &str) -> Vec<(String, String)> {
    let mut sections: Vec<(String, Vec<String>)> = Vec::new();
    let mut stack: Vec<(usize, String)> = Vec::new();
    let mut current_path = String::new();
    let mut current_body: Vec<String> = Vec::new();
    let mut fence: Option<String> = None;

    let flush = |path: &str, body: &Vec<String>, out: &mut Vec<(String, Vec<String>)>| {
        if body.iter().any(|l| !l.trim().is_empty()) {
            out.push((path.to_string(), body.clone()));
        }
    };

    for line in content.lines() {
        let trimmed = line.trim_start();
        if let Some(open) = fence.clone() {
            current_body.push(line.to_string());
            if is_fence_token(trimmed, Some(&open)) {
                fence = None;
            }
            continue;
        }
        if is_fence_token(trimmed, None) {
            fence = Some(fence_marker(trimmed));
            current_body.push(line.to_string());
            continue;
        }
        if let Some((level, text)) = parse_heading(trimmed) {
            flush(&current_path, &current_body, &mut sections);
            current_body = vec![line.to_string()];
            while stack.last().is_some_and(|(l, _)| *l >= level) {
                stack.pop();
            }
            stack.push((level, text));
            current_path = stack
                .iter()
                .map(|(_, t)| t.as_str())
                .collect::<Vec<_>>()
                .join(" > ");
        } else {
            current_body.push(line.to_string());
        }
    }
    flush(&current_path, &current_body, &mut sections);

    let mut out = Vec::new();
    for (path, body_lines) in sections {
        let body = body_lines.join("\n");
        let trimmed_body = body.trim();
        if trimmed_body.is_empty() {
            continue;
        }
        if body.chars().count() <= MAX_CHUNK_CHARS {
            out.push((path, trimmed_body.to_string()));
        } else {
            for piece in soft_split(&body) {
                out.push((path.clone(), piece));
            }
        }
    }
    out
}

/// Greedily pack paragraphs (blank-line separated, never breaking inside
/// a fence) into pieces of at most `MAX_CHUNK_CHARS`.
fn soft_split(body: &str) -> Vec<String> {
    let mut blocks: Vec<String> = Vec::new();
    let mut cur: Vec<String> = Vec::new();
    let mut fence: Option<String> = None;
    for line in body.lines() {
        let trimmed = line.trim_start();
        if let Some(open) = fence.clone() {
            cur.push(line.to_string());
            if is_fence_token(trimmed, Some(&open)) {
                fence = None;
            }
            continue;
        }
        if is_fence_token(trimmed, None) {
            fence = Some(fence_marker(trimmed));
            cur.push(line.to_string());
            continue;
        }
        if line.trim().is_empty() {
            if !cur.is_empty() {
                blocks.push(std::mem::take(&mut cur).join("\n"));
            }
        } else {
            cur.push(line.to_string());
        }
    }
    if !cur.is_empty() {
        blocks.push(cur.join("\n"));
    }

    let mut pieces: Vec<String> = Vec::new();
    let mut acc = String::new();
    for block in blocks {
        let candidate_len = acc.chars().count() + block.chars().count() + 2;
        if !acc.is_empty() && candidate_len > MAX_CHUNK_CHARS {
            pieces.push(std::mem::take(&mut acc));
        }
        if !acc.is_empty() {
            acc.push_str("\n\n");
        }
        acc.push_str(&block);
    }
    if !acc.trim().is_empty() {
        pieces.push(acc);
    }
    pieces
}

fn parse_heading(trimmed: &str) -> Option<(usize, String)> {
    if !trimmed.starts_with('#') {
        return None;
    }
    let level = trimmed.chars().take_while(|c| *c == '#').count();
    if level == 0 || level > 6 {
        return None;
    }
    let rest = &trimmed[level..];
    // ATX requires a space after the hashes ("#foo" is not a heading).
    if !rest.starts_with(char::is_whitespace) {
        return None;
    }
    let text = rest.trim().trim_end_matches('#').trim();
    if text.is_empty() {
        return None;
    }
    Some((level, text.to_string()))
}

/// A fence token is 3+ backticks or 3+ tildes at the start of a
/// (trimmed) line. When `open` is set, only the matching marker family
/// closes the fence.
fn is_fence_token(trimmed: &str, open: Option<&str>) -> bool {
    let matches = |ch: char| trimmed.chars().take_while(|c| *c == ch).count() >= 3;
    match open {
        Some(marker) => {
            let ch = marker.chars().next().unwrap_or('`');
            matches(ch)
        }
        None => matches('`') || matches('~'),
    }
}

fn fence_marker(trimmed: &str) -> String {
    if trimmed.starts_with('~') {
        "~~~"
    } else {
        "```"
    }
    .to_string()
}

fn sha256_hex(text: &str) -> String {
    use sha2::{Digest, Sha256};
    let mut hasher = Sha256::new();
    hasher.update(text.as_bytes());
    let digest = hasher.finalize();
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(digest.len() * 2);
    for b in digest {
        out.push(HEX[(b >> 4) as usize] as char);
        out.push(HEX[(b & 0x0f) as usize] as char);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::commands::init;
    use tempfile::tempdir;

    #[test]
    fn chunker_splits_on_headings_with_breadcrumb() {
        let md =
            "# Top\n\nintro\n\n## Alpha\n\nbody a\n\n### Nested\n\ndeep\n\n## Beta\n\nbody b\n";
        let chunks = chunk_markdown(md);
        let paths: Vec<&str> = chunks.iter().map(|(p, _)| p.as_str()).collect();
        assert_eq!(
            paths,
            vec!["Top", "Top > Alpha", "Top > Alpha > Nested", "Top > Beta"]
        );
        assert!(chunks[1].1.contains("body a"));
    }

    #[test]
    fn chunker_does_not_split_inside_fences() {
        let md = "## Code\n\n```yaml\n# this is not a heading\nkey: value\n```\n\nafter\n";
        let chunks = chunk_markdown(md);
        assert_eq!(chunks.len(), 1, "fenced # must not start a new chunk");
        assert!(chunks[0].1.contains("# this is not a heading"));
        assert!(chunks[0].1.contains("after"));
    }

    #[test]
    fn chunker_keeps_preamble_as_leading_chunk() {
        let md = "---\nname: spec\n---\n\nlead prose\n\n# First\n\nbody\n";
        let chunks = chunk_markdown(md);
        assert_eq!(chunks[0].0, "", "preamble has empty heading_path");
        assert!(chunks[0].1.contains("name: spec"));
        assert_eq!(chunks[1].0, "First");
    }

    #[test]
    fn add_then_show_roundtrips_and_reingest_is_noop() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let doc = temp.path().join("spec.md");
        fs::write(&doc, "# Title\n\n## A\n\nalpha\n\n## B\n\nbeta\n").expect("write");

        let first = add(temp.path(), &doc, None, "cli:user").expect("add");
        assert_eq!(first.status, IngestStatus::Created);
        assert!(first.chunk_count >= 3);

        let again = add(temp.path(), &doc, None, "cli:user").expect("re-add");
        assert_eq!(again.status, IngestStatus::Unchanged);
        assert_eq!(again.doc_id, first.doc_id);

        fs::write(&doc, "# Title\n\n## A\n\nalpha edited\n").expect("rewrite");
        let updated = add(temp.path(), &doc, None, "cli:user").expect("update");
        assert_eq!(updated.status, IngestStatus::Updated);

        let (meta, chunks) = show(temp.path(), &first.doc_id.to_string())
            .expect("show")
            .expect("present");
        assert_eq!(meta.id, first.doc_id);
        assert!(chunks.iter().any(|c| c.body.contains("alpha edited")));
        assert!(
            !chunks.iter().any(|c| c.body.contains("beta")),
            "stale chunk from prior ingest must be gone"
        );
    }

    #[test]
    fn hybrid_reingest_and_remove_leave_no_orphan_embeddings() {
        // The load-bearing invariant: recursive_triggers is OFF, so a
        // doc's chunks (and their embeddings + FTS rows) only get
        // cleaned because the writer deletes doc_chunks EXPLICITLY
        // before the parent. This must hold in hybrid mode, where
        // eager_embed_in_tx actually writes embedding rows. FTS-mode
        // tests can't catch a regression here.
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let cfg_path = temp.path().join(".memhub/config.toml");
        let mut cfg = crate::config::ProjectConfig::load(&cfg_path).expect("load cfg");
        cfg.retrieval.mode = crate::config::RetrievalMode::Hybrid;
        cfg.save(&cfg_path).expect("save cfg");

        let counts = |label: &str| -> (i64, i64) {
            let ctx = db::open_project(temp.path()).expect("open");
            let chunks: i64 = ctx
                .conn
                .query_row("SELECT COUNT(*) FROM doc_chunks", [], |r| r.get(0))
                .expect(label);
            let embs: i64 = ctx
                .conn
                .query_row(
                    "SELECT COUNT(*) FROM embeddings WHERE source_type = 'doc_chunk'",
                    [],
                    |r| r.get(0),
                )
                .expect(label);
            (chunks, embs)
        };

        let doc = temp.path().join("spec.md");
        fs::write(
            &doc,
            "# Spec\n\n## A\n\nalpha\n\n## B\n\nbeta\n\n## C\n\ngamma\n",
        )
        .expect("write");
        let first = add(temp.path(), &doc, None, "cli:user").expect("add");
        let (c1, e1) = counts("after add");
        assert!(c1 >= 3);
        assert_eq!(c1, e1, "every chunk must have exactly one embedding");
        assert_eq!(e1 as usize, first.chunk_count);

        // Edit + re-ingest: stale chunks AND their embeddings must go.
        fs::write(&doc, "# Spec\n\n## A\n\nalpha edited\n").expect("rewrite");
        let updated = add(temp.path(), &doc, None, "cli:user").expect("re-add");
        assert_eq!(updated.status, IngestStatus::Updated);
        let (c2, e2) = counts("after re-add");
        assert_eq!(c2, e2, "no orphan embeddings after re-ingest");
        assert_eq!(e2 as usize, updated.chunk_count);
        assert!(c2 < c1, "shrunk doc has fewer chunks");

        // Remove: everything for the doc is gone.
        assert!(remove(temp.path(), &first.doc_id.to_string(), "cli:user").expect("rm"));
        let (c3, e3) = counts("after rm");
        assert_eq!((c3, e3), (0, 0), "remove clears chunks and embeddings");
    }

    #[test]
    fn remove_clears_document_and_chunks() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let doc = temp.path().join("d.md");
        fs::write(&doc, "# T\n\n## S\n\nbody\n").expect("write");
        let added = add(temp.path(), &doc, None, "cli:user").expect("add");

        assert!(remove(temp.path(), &added.doc_id.to_string(), "cli:user").expect("rm"));
        assert!(list(temp.path()).expect("list").is_empty());
        assert!(
            !remove(temp.path(), &added.doc_id.to_string(), "cli:user").expect("rm again"),
            "second remove finds nothing"
        );
    }
}

//! `memhub eval retrieval` — Recall@K harness for the M8 retrieval surface (PR6).
//!
//! Loads a golden-query JSON file, runs each query through the same
//! `retrieval::recall` engine the CLI and MCP tools use, and reports
//! how many `match` queries placed the expected row in the top K and
//! how many `empty` queries kept their result bundle empty.
//!
//! Read-only: never mutates durable state or `writes_log`.

use std::fs;
use std::path::{Path, PathBuf};
use std::time::Instant;

use serde::{Deserialize, Serialize};

use crate::code_index::locate::{self, LocateHit, LocateOptions, LocateResponse};
use crate::config::RetrievalMode;
use crate::retrieval::{self, RecallHit, RecallOptions, RecallResponse};
use crate::{MemhubError, Result};

pub const DEFAULT_GOLDEN_PATH: &str = "tests/retrieval_golden.json";
pub const DEFAULT_CODE_GOLDEN_PATH: &str = "tests/code_locate_golden.json";
pub const DEFAULT_K: usize = 3;

#[derive(Debug, Deserialize, Serialize)]
pub struct GoldenFile {
    pub version: u32,
    #[serde(default)]
    pub description: String,
    pub queries: Vec<GoldenQuery>,
}

#[derive(Debug, Deserialize, Serialize, Clone)]
pub struct GoldenQuery {
    pub id: String,
    pub query: String,
    pub kind: GoldenKind,
    #[serde(default)]
    pub source_type: Option<String>,
    #[serde(default)]
    pub title_contains: Vec<String>,
    #[serde(default)]
    pub body_contains: Vec<String>,
    #[serde(default)]
    pub notes: String,
}

#[derive(Debug, Deserialize, Serialize, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum GoldenKind {
    Match,
    Empty,
}

#[derive(Debug, Clone)]
pub struct EvalOptions {
    pub golden_path: PathBuf,
    pub k: usize,
    pub mode: Option<RetrievalMode>,
    /// Optional override of `[retrieval] use_reranker`. None = use project
    /// config; Some(false) forces the re-ranker off for the run; Some(true)
    /// forces it on regardless of config. Used for A/B harness runs.
    pub use_reranker: Option<bool>,
    /// Optional override of `[retrieval.scoring] min_rerank_score`. None
    /// = use project config. Ignored when mode resolves to fts or when
    /// the re-ranker is disabled. Used for cross-encoder floor
    /// calibration sweeps (decisions 70, 71).
    pub min_rerank_score: Option<f32>,
}

#[derive(Debug, Clone)]
pub struct QueryOutcome {
    pub id: String,
    pub query: String,
    pub kind: GoldenKind,
    pub passed: bool,
    /// 1-indexed rank of the matching hit (Some) or None when no hit qualified.
    pub matched_rank: Option<usize>,
    /// Score of the matched hit, if any.
    pub matched_score: Option<f64>,
    /// Total returned by recall for this query.
    pub returned_count: usize,
    /// Optional reason string for failed outcomes (debug aid in markdown output).
    pub failure_reason: Option<String>,
}

#[derive(Debug, Clone)]
pub struct EvalSummary {
    pub golden_path: PathBuf,
    pub mode: RetrievalMode,
    pub k: usize,
    pub total_queries: usize,
    pub match_queries: usize,
    pub empty_queries: usize,
    pub match_passes: usize,
    pub empty_passes: usize,
    pub recall_at_k: f64,
    pub safety_failures: usize,
    pub outcomes: Vec<QueryOutcome>,
    pub elapsed_ms: u128,
}

pub fn run_retrieval(start: &Path, opts: EvalOptions) -> Result<EvalSummary> {
    if opts.k == 0 {
        return Err(MemhubError::InvalidInput(
            "--k must be greater than zero".to_string(),
        ));
    }
    let golden = load_golden(&opts.golden_path)?;
    let started = Instant::now();
    let mut outcomes = Vec::with_capacity(golden.queries.len());
    let mut resolved_mode = opts.mode;

    for query in &golden.queries {
        let recall_opts = RecallOptions {
            query: query.query.clone(),
            mode: opts.mode,
            max_results: opts.k,
            source_types: Vec::new(),
            include_stale: None,
            accepted_only: None,
            use_reranker: opts.use_reranker,
            min_rerank_score: opts.min_rerank_score,
            // Calibration sweeps are not "real usage" — keep them out
            // of recall_metrics so the dashboard's numbers reflect
            // actual agent + user activity.
            log_metrics: false,
        };
        let response = retrieval::recall(start, recall_opts)?;
        if resolved_mode.is_none() {
            resolved_mode = Some(response.mode);
        }
        outcomes.push(evaluate_query(query, &response, opts.k));
    }

    let mode = resolved_mode.unwrap_or(RetrievalMode::Fts);
    let summary = summarize(
        &golden,
        opts.k,
        mode,
        opts.golden_path.clone(),
        outcomes,
        started,
    );
    Ok(summary)
}

pub fn load_golden(path: &Path) -> Result<GoldenFile> {
    let bytes = fs::read(path).map_err(|err| match err.kind() {
        std::io::ErrorKind::NotFound => MemhubError::InvalidInput(format!(
            "golden file not found at {} — pass --golden <path> or create one",
            path.display()
        )),
        _ => MemhubError::from(err),
    })?;
    let parsed: GoldenFile = serde_json::from_slice(&bytes)?;
    if parsed.version != 1 {
        return Err(MemhubError::InvalidInput(format!(
            "unsupported golden file version {} in {}; expected 1",
            parsed.version,
            path.display(),
        )));
    }
    if parsed.queries.is_empty() {
        return Err(MemhubError::InvalidInput(format!(
            "golden file {} has zero queries",
            path.display(),
        )));
    }
    for q in &parsed.queries {
        validate_query(q)?;
    }
    Ok(parsed)
}

fn validate_query(q: &GoldenQuery) -> Result<()> {
    if q.id.trim().is_empty() {
        return Err(MemhubError::InvalidInput(
            "golden query missing `id`".to_string(),
        ));
    }
    if q.query.trim().is_empty() {
        return Err(MemhubError::InvalidInput(format!(
            "golden query `{}` has empty `query`",
            q.id
        )));
    }
    if let Some(st) = q.source_type.as_deref() {
        match st {
            "fact" | "decision" | "task" => {}
            other => {
                return Err(MemhubError::InvalidInput(format!(
                    "golden query `{}` has unknown source_type `{}` (expected fact|decision|task)",
                    q.id, other
                )));
            }
        }
    }
    if q.kind == GoldenKind::Match
        && q.title_contains.is_empty()
        && q.body_contains.is_empty()
        && q.source_type.is_none()
    {
        return Err(MemhubError::InvalidInput(format!(
            "golden query `{}` is kind=match but has no matchers; every match query needs at least one of source_type / title_contains / body_contains",
            q.id
        )));
    }
    Ok(())
}

pub fn evaluate_query(query: &GoldenQuery, response: &RecallResponse, k: usize) -> QueryOutcome {
    let returned_count = response.results.len();
    match query.kind {
        GoldenKind::Empty => {
            if returned_count == 0 {
                QueryOutcome {
                    id: query.id.clone(),
                    query: query.query.clone(),
                    kind: GoldenKind::Empty,
                    passed: true,
                    matched_rank: None,
                    matched_score: None,
                    returned_count,
                    failure_reason: None,
                }
            } else {
                let leaked: Vec<String> = response
                    .results
                    .iter()
                    .take(k.min(3))
                    .map(|hit| format!("{}#{}", hit.source_type, hit.source_id))
                    .collect();
                QueryOutcome {
                    id: query.id.clone(),
                    query: query.query.clone(),
                    kind: GoldenKind::Empty,
                    passed: false,
                    matched_rank: None,
                    matched_score: None,
                    returned_count,
                    failure_reason: Some(format!(
                        "expected empty bundle but recall returned {} hit(s): {}",
                        returned_count,
                        leaked.join(", "),
                    )),
                }
            }
        }
        GoldenKind::Match => {
            let limit = k.min(response.results.len());
            for hit in response.results.iter().take(limit) {
                if hit_matches(query, hit) {
                    return QueryOutcome {
                        id: query.id.clone(),
                        query: query.query.clone(),
                        kind: GoldenKind::Match,
                        passed: true,
                        matched_rank: Some(hit.rank),
                        matched_score: Some(hit.score),
                        returned_count,
                        failure_reason: None,
                    };
                }
            }
            let reason = if returned_count == 0 {
                "recall returned no results".to_string()
            } else {
                let top: Vec<String> = response
                    .results
                    .iter()
                    .take(limit)
                    .map(|hit| {
                        format!(
                            "{}#{}:{}",
                            hit.source_type,
                            hit.source_id,
                            truncate(&hit.title, 40)
                        )
                    })
                    .collect();
                format!(
                    "no top-{} hit matched (returned {}): {}",
                    k,
                    returned_count,
                    top.join(" | "),
                )
            };
            QueryOutcome {
                id: query.id.clone(),
                query: query.query.clone(),
                kind: GoldenKind::Match,
                passed: false,
                matched_rank: None,
                matched_score: None,
                returned_count,
                failure_reason: Some(reason),
            }
        }
    }
}

fn hit_matches(query: &GoldenQuery, hit: &RecallHit) -> bool {
    if let Some(expected) = query.source_type.as_deref()
        && hit.source_type != expected
    {
        return false;
    }
    let title_lower = hit.title.to_lowercase();
    for needle in &query.title_contains {
        if !title_lower.contains(&needle.to_lowercase()) {
            return false;
        }
    }
    let body_lower = hit.body.to_lowercase();
    for needle in &query.body_contains {
        if !body_lower.contains(&needle.to_lowercase()) {
            return false;
        }
    }
    true
}

fn truncate(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        let mut out: String = s.chars().take(max).collect();
        out.push('…');
        out
    }
}

fn summarize(
    golden: &GoldenFile,
    k: usize,
    mode: RetrievalMode,
    golden_path: PathBuf,
    outcomes: Vec<QueryOutcome>,
    started: Instant,
) -> EvalSummary {
    let total_queries = golden.queries.len();
    let mut match_queries = 0usize;
    let mut empty_queries = 0usize;
    let mut match_passes = 0usize;
    let mut empty_passes = 0usize;
    let mut safety_failures = 0usize;
    for outcome in &outcomes {
        match outcome.kind {
            GoldenKind::Match => {
                match_queries += 1;
                if outcome.passed {
                    match_passes += 1;
                }
            }
            GoldenKind::Empty => {
                empty_queries += 1;
                if outcome.passed {
                    empty_passes += 1;
                } else {
                    safety_failures += 1;
                }
            }
        }
    }
    let recall_at_k = if match_queries == 0 {
        0.0
    } else {
        match_passes as f64 / match_queries as f64
    };
    EvalSummary {
        golden_path,
        mode,
        k,
        total_queries,
        match_queries,
        empty_queries,
        match_passes,
        empty_passes,
        recall_at_k,
        safety_failures,
        outcomes,
        elapsed_ms: started.elapsed().as_millis(),
    }
}

// ---------------------------------------------------------------------------
// `memhub eval locate` — code-locator Recall@K harness (M11 PR5, task 65).
//
// Mirrors the retrieval harness above but over the sibling code index: each
// query runs through the same `code_index::locate::locate` the CLI/MCP
// surfaces use, and a hit "matches" when its repo-relative `path` (and
// optional `symbol`) contains the golden substrings. The bar is decision
// 107's deliberately-lossy one — the expected FILE in the top K, precision
// recovered by the agent's real Read — so this reports both Recall@1 and
// Recall@K.
//
// The cross-encoder floor is applied HARNESS-SIDE: `min_rerank_score` filters
// the returned hits by their `rerank_score` before scoring, so a floor can be
// A/B-swept without touching the `locate` runtime (which has no floor by
// design, decision 107). A floor is only meaningful with `--rerank` on; it is
// ignored otherwise, mirroring the retrieval harness's reranker-gated rule.
// ---------------------------------------------------------------------------

#[derive(Debug, Deserialize, Serialize)]
pub struct LocateGoldenFile {
    pub version: u32,
    #[serde(default)]
    pub description: String,
    pub queries: Vec<LocateGoldenQuery>,
}

#[derive(Debug, Deserialize, Serialize, Clone)]
pub struct LocateGoldenQuery {
    pub id: String,
    pub query: String,
    pub kind: GoldenKind,
    /// Substrings that must all appear (case-insensitive) in the hit's
    /// repo-relative, forward-slashed path.
    #[serde(default)]
    pub path_contains: Vec<String>,
    /// Optional substring the hit's symbol must contain. `None` keeps the
    /// bar at file granularity (decision 107's right-file-in-top-K rule).
    #[serde(default)]
    pub symbol_contains: Option<String>,
    #[serde(default)]
    pub notes: String,
}

#[derive(Debug, Clone)]
pub struct LocateEvalOptions {
    pub golden_path: PathBuf,
    pub k: usize,
    /// Run the bundled cross-encoder over the candidate pool. Off by default
    /// (mirrors `memhub locate`); flip on for the A/B against fusion-only.
    pub use_reranker: bool,
    /// Harness-side cross-encoder floor: drop returned hits whose rerank
    /// logit is below this before scoring. Ignored when the reranker is off.
    pub min_rerank_score: Option<f32>,
}

#[derive(Debug, Clone)]
pub struct LocateQueryOutcome {
    pub id: String,
    pub query: String,
    pub kind: GoldenKind,
    /// Passed at Recall@K (top-K contains the expected file).
    pub passed: bool,
    /// Passed at Recall@1 (the very first surviving hit is the expected file).
    pub passed_at_1: bool,
    /// 1-indexed position (within the post-floor list) of the matching hit.
    pub matched_rank: Option<usize>,
    /// Fusion score of the matched hit.
    pub matched_score: Option<f64>,
    /// Cross-encoder logit of the matched hit, when reranking ran.
    pub matched_rerank: Option<f32>,
    /// Hits surviving the floor for this query.
    pub returned_count: usize,
    pub failure_reason: Option<String>,
}

#[derive(Debug, Clone)]
pub struct LocateEvalSummary {
    pub golden_path: PathBuf,
    pub mode: RetrievalMode,
    pub k: usize,
    pub reranked: bool,
    pub min_rerank_score: Option<f32>,
    pub total_queries: usize,
    pub match_queries: usize,
    pub empty_queries: usize,
    pub match_passes_at_1: usize,
    pub match_passes_at_k: usize,
    pub empty_passes: usize,
    pub recall_at_1: f64,
    pub recall_at_k: f64,
    pub safety_failures: usize,
    pub outcomes: Vec<LocateQueryOutcome>,
    pub elapsed_ms: u128,
}

pub fn run_locate(start: &Path, opts: LocateEvalOptions) -> Result<LocateEvalSummary> {
    if opts.k == 0 {
        return Err(MemhubError::InvalidInput(
            "--k must be greater than zero".to_string(),
        ));
    }
    let golden = load_locate_golden(&opts.golden_path)?;
    let started = Instant::now();
    let mut outcomes = Vec::with_capacity(golden.queries.len());
    let mut resolved_mode: Option<RetrievalMode> = None;

    for query in &golden.queries {
        let locate_opts = LocateOptions {
            query: query.query.clone(),
            limit: opts.k,
            use_reranker: opts.use_reranker,
        };
        let response = locate::locate(start, locate_opts)?;
        if resolved_mode.is_none() {
            resolved_mode = Some(response.mode);
        }
        outcomes.push(evaluate_locate_query(
            query,
            &response,
            opts.k,
            opts.use_reranker,
            opts.min_rerank_score,
        ));
    }

    let mode = resolved_mode.unwrap_or(RetrievalMode::Hybrid);
    Ok(summarize_locate(&golden, mode, opts, outcomes, started))
}

pub fn load_locate_golden(path: &Path) -> Result<LocateGoldenFile> {
    let bytes = fs::read(path).map_err(|err| match err.kind() {
        std::io::ErrorKind::NotFound => MemhubError::InvalidInput(format!(
            "code golden file not found at {} — pass --golden <path> or create one",
            path.display()
        )),
        _ => MemhubError::from(err),
    })?;
    let parsed: LocateGoldenFile = serde_json::from_slice(&bytes)?;
    if parsed.version != 1 {
        return Err(MemhubError::InvalidInput(format!(
            "unsupported code golden file version {} in {}; expected 1",
            parsed.version,
            path.display(),
        )));
    }
    if parsed.queries.is_empty() {
        return Err(MemhubError::InvalidInput(format!(
            "code golden file {} has zero queries",
            path.display(),
        )));
    }
    for q in &parsed.queries {
        validate_locate_query(q)?;
    }
    Ok(parsed)
}

fn validate_locate_query(q: &LocateGoldenQuery) -> Result<()> {
    if q.id.trim().is_empty() {
        return Err(MemhubError::InvalidInput(
            "code golden query missing `id`".to_string(),
        ));
    }
    if q.query.trim().is_empty() {
        return Err(MemhubError::InvalidInput(format!(
            "code golden query `{}` has empty `query`",
            q.id
        )));
    }
    if q.kind == GoldenKind::Match
        && q.path_contains.iter().all(|s| s.trim().is_empty())
        && q.symbol_contains.as_deref().is_none_or(str::is_empty)
    {
        return Err(MemhubError::InvalidInput(format!(
            "code golden query `{}` is kind=match but has no matchers; every match query needs at least one of path_contains / symbol_contains",
            q.id
        )));
    }
    Ok(())
}

/// Filter a locate response's hits by the harness-side rerank floor, then
/// score the survivors. The floor only applies when the reranker actually
/// ran (so the hits carry logits) and a threshold was given.
pub fn evaluate_locate_query(
    query: &LocateGoldenQuery,
    response: &LocateResponse,
    k: usize,
    reranker_on: bool,
    min_rerank_score: Option<f32>,
) -> LocateQueryOutcome {
    let floor = if reranker_on { min_rerank_score } else { None };
    let survivors: Vec<&LocateHit> = response
        .results
        .iter()
        .filter(|hit| match floor {
            Some(threshold) => hit.rerank_score.is_some_and(|s| s >= threshold),
            None => true,
        })
        .collect();
    let returned_count = survivors.len();

    match query.kind {
        GoldenKind::Empty => {
            if returned_count == 0 {
                empty_outcome(query, true, returned_count, None)
            } else {
                let leaked: Vec<String> = survivors
                    .iter()
                    .take(k.min(3))
                    .map(|hit| format!("{}:{}", hit.path, hit.start_line))
                    .collect();
                empty_outcome(
                    query,
                    false,
                    returned_count,
                    Some(format!(
                        "expected empty bundle but locate returned {} hit(s): {}",
                        returned_count,
                        leaked.join(", "),
                    )),
                )
            }
        }
        GoldenKind::Match => {
            let limit = k.min(survivors.len());
            for (idx, hit) in survivors.iter().take(limit).enumerate() {
                if locate_hit_matches(query, hit) {
                    let rank = idx + 1;
                    return LocateQueryOutcome {
                        id: query.id.clone(),
                        query: query.query.clone(),
                        kind: GoldenKind::Match,
                        passed: true,
                        passed_at_1: rank == 1,
                        matched_rank: Some(rank),
                        matched_score: Some(hit.score),
                        matched_rerank: hit.rerank_score,
                        returned_count,
                        failure_reason: None,
                    };
                }
            }
            let reason = if returned_count == 0 {
                "locate returned no results".to_string()
            } else {
                let top: Vec<String> = survivors
                    .iter()
                    .take(limit)
                    .map(|hit| {
                        format!(
                            "{}:{}{}",
                            hit.path,
                            hit.start_line,
                            hit.symbol
                                .as_deref()
                                .map(|s| format!(" [{s}]"))
                                .unwrap_or_default(),
                        )
                    })
                    .collect();
                format!(
                    "no top-{} hit matched (returned {}): {}",
                    k,
                    returned_count,
                    top.join(" | "),
                )
            };
            LocateQueryOutcome {
                id: query.id.clone(),
                query: query.query.clone(),
                kind: GoldenKind::Match,
                passed: false,
                passed_at_1: false,
                matched_rank: None,
                matched_score: None,
                matched_rerank: None,
                returned_count,
                failure_reason: Some(reason),
            }
        }
    }
}

fn empty_outcome(
    query: &LocateGoldenQuery,
    passed: bool,
    returned_count: usize,
    failure_reason: Option<String>,
) -> LocateQueryOutcome {
    LocateQueryOutcome {
        id: query.id.clone(),
        query: query.query.clone(),
        kind: GoldenKind::Empty,
        passed,
        passed_at_1: passed,
        matched_rank: None,
        matched_score: None,
        matched_rerank: None,
        returned_count,
        failure_reason,
    }
}

fn locate_hit_matches(query: &LocateGoldenQuery, hit: &LocateHit) -> bool {
    let path_lower = hit.path.to_lowercase();
    for needle in &query.path_contains {
        if !path_lower.contains(&needle.to_lowercase()) {
            return false;
        }
    }
    if let Some(sym_needle) = query.symbol_contains.as_deref().filter(|s| !s.is_empty()) {
        match hit.symbol.as_deref() {
            Some(symbol) if symbol.to_lowercase().contains(&sym_needle.to_lowercase()) => {}
            _ => return false,
        }
    }
    true
}

fn summarize_locate(
    golden: &LocateGoldenFile,
    mode: RetrievalMode,
    opts: LocateEvalOptions,
    outcomes: Vec<LocateQueryOutcome>,
    started: Instant,
) -> LocateEvalSummary {
    let total_queries = golden.queries.len();
    let mut match_queries = 0usize;
    let mut empty_queries = 0usize;
    let mut match_passes_at_1 = 0usize;
    let mut match_passes_at_k = 0usize;
    let mut empty_passes = 0usize;
    let mut safety_failures = 0usize;
    for outcome in &outcomes {
        match outcome.kind {
            GoldenKind::Match => {
                match_queries += 1;
                if outcome.passed {
                    match_passes_at_k += 1;
                }
                if outcome.passed_at_1 {
                    match_passes_at_1 += 1;
                }
            }
            GoldenKind::Empty => {
                empty_queries += 1;
                if outcome.passed {
                    empty_passes += 1;
                } else {
                    safety_failures += 1;
                }
            }
        }
    }
    let recall_at_1 = ratio(match_passes_at_1, match_queries);
    let recall_at_k = ratio(match_passes_at_k, match_queries);
    LocateEvalSummary {
        golden_path: opts.golden_path,
        mode,
        k: opts.k,
        reranked: opts.use_reranker,
        min_rerank_score: opts.min_rerank_score,
        total_queries,
        match_queries,
        empty_queries,
        match_passes_at_1,
        match_passes_at_k,
        empty_passes,
        recall_at_1,
        recall_at_k,
        safety_failures,
        outcomes,
        elapsed_ms: started.elapsed().as_millis(),
    }
}

fn ratio(passes: usize, total: usize) -> f64 {
    if total == 0 {
        0.0
    } else {
        passes as f64 / total as f64
    }
}

