use std::path::Path;

use rusqlite::{OptionalExtension, Transaction, params};

use crate::Result;
use crate::db;
use crate::models::{FACT_STALE_AFTER_DAYS, Fact};
use crate::sync_md;

pub fn add(start: &Path, key: &str, value: &str, source: &str, actor: &str) -> Result<(i64, bool)> {
    let mut ctx = db::open_project(start)?;
    let mode = ctx.config.retrieval.mode;
    let tx = ctx.conn.transaction()?;
    let outcome = add_in_tx(&tx, key, value, source, actor, mode)?;
    tx.commit()?;
    sync_md::sync_if_enabled(start)?;
    Ok(outcome)
}

pub fn add_in_tx(
    tx: &Transaction<'_>,
    key: &str,
    value: &str,
    source: &str,
    actor: &str,
    mode: crate::config::RetrievalMode,
) -> Result<(i64, bool)> {
    crate::commands::validate_source(source)?;

    let existing_id: Option<i64> = tx
        .query_row(
            "SELECT id FROM facts WHERE project_id = 1 AND key = ?1",
            [key],
            |row| row.get(0),
        )
        .optional()?;

    let (row_id, created) = if let Some(id) = existing_id {
        tx.execute(
            "UPDATE facts
             SET value = ?1, source = ?2, confidence = 1.0, verified_at = CURRENT_TIMESTAMP
             WHERE id = ?3",
            params![value, source, id],
        )?;
        (id, false)
    } else {
        tx.execute(
            "INSERT INTO facts(project_id, key, value, confidence, source, verified_at)
             VALUES (1, ?1, ?2, 1.0, ?3, CURRENT_TIMESTAMP)",
            params![key, value, source],
        )?;
        (tx.last_insert_rowid(), true)
    };

    db::log_write(
        tx,
        actor,
        "facts",
        Some(row_id),
        if created { "insert" } else { "update" },
        "fact add",
    )?;

    let embed_text = crate::retrieval::fact_embed_text(key, value);
    crate::retrieval::eager_embed_in_tx(
        tx,
        mode,
        crate::retrieval::SourceType::Fact,
        row_id,
        &embed_text,
    )?;

    Ok((row_id, created))
}

#[derive(Debug)]
pub struct GlobalFactOutcome {
    pub id: i64,
    pub created: bool,
    /// True when this call created `~/.memhub/global.sqlite`.
    pub store_created: bool,
}

/// Born-global fact write (M9). Requires `memhub global enable` in
/// this repo. Embeds using the *repo's* retrieval mode so global rows
/// stay consistent with how this machine recalls.
pub fn add_global(
    start: &Path,
    key: &str,
    value: &str,
    source: &str,
    actor: &str,
) -> Result<GlobalFactOutcome> {
    let mut gw = crate::commands::global::begin_write(start)?;
    let tx = gw.ctx.conn.transaction()?;
    let (id, created) = add_in_tx(&tx, key, value, source, actor, gw.mode)?;
    tx.commit()?;
    Ok(GlobalFactOutcome {
        id,
        created,
        store_created: gw.store_created,
    })
}

/// Copy an existing repo fact into the machine-global store (copy,
/// not move — the repo row stays and still wins locally). Fact keys
/// are UNIQUE per DB, so re-promoting a key updates the global fact.
pub fn promote(start: &Path, id: i64, actor: &str) -> Result<GlobalFactOutcome> {
    let repo = db::open_project(start)?;
    crate::commands::global::ensure_enabled(&repo.config)?;
    let mode = repo.config.retrieval.mode;

    let (key, value, source): (String, String, String) = repo
        .conn
        .query_row(
            "SELECT key, value, source FROM facts WHERE id = ?1 AND project_id = 1",
            params![id],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
        )
        .map_err(|err| match err {
            rusqlite::Error::QueryReturnedNoRows => {
                crate::MemhubError::InvalidInput(format!("no fact with id {id}"))
            }
            other => crate::MemhubError::from(other),
        })?;

    let repo_root = repo.paths.repo_root.display().to_string();
    let store_created = !db::global_store_exists()?;

    let mut g = db::open_global()?;
    let tx = g.conn.transaction()?;
    let (gid, created) = add_in_tx(&tx, &key, &value, &source, actor, mode)?;
    db::log_write(
        &tx,
        actor,
        "facts",
        Some(gid),
        "promote",
        &format!("promote from {repo_root}"),
    )?;
    tx.commit()?;

    Ok(GlobalFactOutcome {
        id: gid,
        created,
        store_created,
    })
}

pub fn list(start: &Path) -> Result<Vec<Fact>> {
    let ctx = db::open_project(start)?;
    let mut stmt = ctx.conn.prepare(
        "SELECT id, key, value, confidence, source, verified_at, created_at,
                CASE
                    WHEN verified_at IS NULL THEN 1
                    WHEN (julianday('now') - julianday(verified_at)) > ?1 THEN 1
                    ELSE 0
                END AS is_stale
         FROM facts
         ORDER BY key ASC",
    )?;

    let rows = stmt.query_map(params![FACT_STALE_AFTER_DAYS], |row| {
        let is_stale_int: i64 = row.get(7)?;
        Ok(Fact {
            id: row.get(0)?,
            key: row.get(1)?,
            value: row.get(2)?,
            confidence: row.get(3)?,
            source: row.get(4)?,
            verified_at: row.get(5)?,
            created_at: row.get(6)?,
            is_stale: is_stale_int != 0,
        })
    })?;

    rows.collect::<std::result::Result<Vec<_>, _>>()
        .map_err(Into::into)
}

pub fn count_stale(start: &Path) -> Result<i64> {
    let ctx = db::open_project(start)?;
    let count: i64 = ctx.conn.query_row(
        "SELECT COUNT(*)
         FROM facts
         WHERE verified_at IS NULL
            OR (julianday('now') - julianday(verified_at)) > ?1",
        params![FACT_STALE_AFTER_DAYS],
        |row| row.get(0),
    )?;
    Ok(count)
}

//! `memhub gc` — reclaim disk by deleting superseded build artifacts in
//! this repo's `target/` directory.
//!
//! Cargo's `target/<profile>/deps/` is append-only: every rebuild writes
//! a new hash-suffixed artifact and never deletes the old one. For a
//! crate like memhub that bundles ONNX models via `include_bytes!`, each
//! `libmemhub-<hash>.rlib` is ~1 GB and each integration-test binary is
//! ~1 GB, so a few weeks of `cargo test` accumulates 100+ GB of dead
//! weight Cargo will never reclaim on its own.
//!
//! This GC is deliberately conservative so "keep only the newest build
//! set" can never corrupt a working tree:
//!
//! * It only ever touches **memhub-owned** artifact stems — `memhub`,
//!   `libmemhub`, and any stem matching a top-level `tests/*.rs`,
//!   `benches/*.rs`, or `examples/*.rs` file. Third-party dependency
//!   rlibs (`libserde-*`, `libtokio-*`, …) carry a single hash, never
//!   balloon, and are structurally never considered.
//! * For each owned stem it keeps every file of the newest-mtime hash
//!   and deletes the older hashes plus their `.fingerprint/<stem>-<hash>`
//!   dirs. Worst case of deleting a superseded hash is that a stale test
//!   binary is rebuilt on the next `cargo test` — Cargo recovers; no
//!   state is corrupted because the current (newest) set is untouched.
//! * Only `target/<profile>/deps/` and `target/<profile>/.fingerprint/`
//!   are in scope. The `incremental/` cache is left alone (deleting it
//!   only slows the next build for no comparable disk win).
//!
//! Pure `std::fs` — OS-agnostic by construction (macOS + Windows).

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::SystemTime;

use crate::{MemhubError, Result};

/// Cargo profiles whose `deps/` accumulate stale hashes.
const PROFILES: &[&str] = &["debug", "release"];

/// A cargo metadata hash is lowercase hex; historically 16 chars but be
/// lenient on the low end so older artifacts still match.
const MIN_HASH_LEN: usize = 8;

#[derive(Debug, serde::Serialize)]
pub struct GcOutcome {
    pub root: PathBuf,
    pub dry_run: bool,
    pub removed_files: u64,
    pub removed_dirs: u64,
    pub bytes_freed: u64,
    /// Number of (profile, stem) groups that had at least one stale hash
    /// removed.
    pub groups_pruned: u64,
    /// Human-readable breadcrumbs, one per pruned group plus any
    /// best-effort warnings.
    pub details: Vec<String>,
}

impl GcOutcome {
    /// One-line summary for the `memhub upgrade` table and the CLI.
    pub fn summary(&self) -> String {
        if self.groups_pruned == 0 {
            return "nothing to reclaim (already at newest build set)".to_string();
        }
        let verb = if self.dry_run { "would free" } else { "freed" };
        format!(
            "{} stale artifact group(s): {} {} ({} files, {} dirs)",
            self.groups_pruned,
            verb,
            human_bytes(self.bytes_freed),
            self.removed_files,
            self.removed_dirs,
        )
    }
}

/// Walk up from `start` to the nearest ancestor containing `Cargo.toml`.
fn find_repo_root(start: &Path) -> Result<PathBuf> {
    let mut cur = Some(start);
    while let Some(dir) = cur {
        if dir.join("Cargo.toml").is_file() {
            return Ok(dir.to_path_buf());
        }
        cur = dir.parent();
    }
    Err(MemhubError::InvalidInput(format!(
        "no Cargo.toml found at or above {}; `memhub gc` only applies to \
         a Rust project's target/ directory",
        start.display()
    )))
}

/// The set of artifact stems memhub owns and is safe to prune.
fn owned_stems(root: &Path) -> std::collections::BTreeSet<String> {
    let mut set = std::collections::BTreeSet::new();
    set.insert("memhub".to_string());
    set.insert("libmemhub".to_string());
    for sub in ["tests", "benches", "examples"] {
        let dir = root.join(sub);
        let Ok(rd) = fs::read_dir(&dir) else {
            continue;
        };
        for entry in rd.flatten() {
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) == Some("rs") {
                if let Some(stem) = path.file_stem().and_then(|s| s.to_str()) {
                    set.insert(stem.to_string());
                }
            }
        }
    }
    set
}

/// Split a `deps/` entry name into `(stem, hash)`. The only `-` in a
/// memhub-owned artifact name is the separator before the cargo hash
/// (stems use `_`), so split on the last `-` and validate the tail is a
/// hex hash. Returns `None` for anything that is not a hash-suffixed
/// artifact (e.g. `.cargo-lock`, an un-hashed final binary).
fn parse_artifact(name: &str) -> Option<(String, String)> {
    let dash = name.rfind('-')?;
    let stem = &name[..dash];
    let rest = &name[dash + 1..];
    let hash = match rest.find('.') {
        Some(dot) => &rest[..dot],
        None => rest,
    };
    if stem.is_empty() || hash.len() < MIN_HASH_LEN || !hash.bytes().all(|b| b.is_ascii_hexdigit())
    {
        return None;
    }
    Some((stem.to_string(), hash.to_string()))
}

fn dir_size(path: &Path) -> u64 {
    let Ok(rd) = fs::read_dir(path) else {
        return 0;
    };
    let mut total = 0;
    for entry in rd.flatten() {
        let p = entry.path();
        match entry.file_type() {
            Ok(ft) if ft.is_dir() => total += dir_size(&p),
            _ => {
                if let Ok(md) = fs::symlink_metadata(&p) {
                    total += md.len();
                }
            }
        }
    }
    total
}

fn human_bytes(n: u64) -> String {
    const UNITS: &[&str] = &["B", "KiB", "MiB", "GiB", "TiB"];
    let mut v = n as f64;
    let mut u = 0;
    while v >= 1024.0 && u < UNITS.len() - 1 {
        v /= 1024.0;
        u += 1;
    }
    if u == 0 {
        format!("{n} B")
    } else {
        format!("{v:.1} {}", UNITS[u])
    }
}

struct Artifact {
    path: PathBuf,
    is_dir: bool,
    size: u64,
    mtime: SystemTime,
}

/// Prune one `deps/` + `.fingerprint/` pair for one profile, mutating
/// the running totals on `out`.
fn prune_profile(
    profile: &str,
    deps: &Path,
    fingerprint: &Path,
    owned: &std::collections::BTreeSet<String>,
    dry_run: bool,
    out: &mut GcOutcome,
) {
    // stem -> hash -> [artifacts]
    let mut groups: BTreeMap<String, BTreeMap<String, Vec<Artifact>>> = BTreeMap::new();

    let Ok(rd) = fs::read_dir(deps) else {
        return;
    };
    for entry in rd.flatten() {
        let path = entry.path();
        let Some(name) = path.file_name().and_then(|n| n.to_str()) else {
            continue;
        };
        let Some((stem, hash)) = parse_artifact(name) else {
            continue;
        };
        if !owned.contains(&stem) {
            continue;
        }
        let md = match fs::symlink_metadata(&path) {
            Ok(m) => m,
            Err(_) => continue,
        };
        let is_dir = md.is_dir();
        let size = if is_dir { dir_size(&path) } else { md.len() };
        let mtime = md.modified().unwrap_or(SystemTime::UNIX_EPOCH);
        groups
            .entry(stem)
            .or_default()
            .entry(hash)
            .or_default()
            .push(Artifact {
                path,
                is_dir,
                size,
                mtime,
            });
    }

    for (stem, by_hash) in groups {
        if by_hash.len() < 2 {
            continue; // only one hash for this stem — nothing superseded
        }
        // Newest hash = the one whose newest file mtime is greatest.
        let keep = by_hash
            .iter()
            .max_by_key(|(_, arts)| {
                arts.iter()
                    .map(|a| a.mtime)
                    .max()
                    .unwrap_or(SystemTime::UNIX_EPOCH)
            })
            .map(|(h, _)| h.clone())
            .unwrap_or_default();

        let mut group_bytes = 0u64;
        let mut group_files = 0u64;
        let mut group_dirs = 0u64;

        for (hash, arts) in &by_hash {
            if *hash == keep {
                continue;
            }
            for a in arts {
                group_bytes += a.size;
                if a.is_dir {
                    group_dirs += 1;
                } else {
                    group_files += 1;
                }
                if !dry_run {
                    let res = if a.is_dir {
                        fs::remove_dir_all(&a.path)
                    } else {
                        fs::remove_file(&a.path)
                    };
                    if let Err(e) = res {
                        out.details
                            .push(format!("warn: could not remove {}: {e}", a.path.display()));
                    }
                }
            }
            // The matching .fingerprint/<stem>-<hash> dir, if present.
            let fp = fingerprint.join(format!("{stem}-{hash}"));
            if fp.is_dir() {
                group_bytes += dir_size(&fp);
                group_dirs += 1;
                if !dry_run {
                    if let Err(e) = fs::remove_dir_all(&fp) {
                        out.details
                            .push(format!("warn: could not remove {}: {e}", fp.display()));
                    }
                }
            }
        }

        out.bytes_freed += group_bytes;
        out.removed_files += group_files;
        out.removed_dirs += group_dirs;
        out.groups_pruned += 1;
        out.details.push(format!(
            "{profile}/{stem}: kept {keep}, {} {} stale hash(es) ({})",
            if dry_run { "would remove" } else { "removed" },
            by_hash.len() - 1,
            human_bytes(group_bytes),
        ));
    }
}

/// Reclaim superseded build artifacts under `<repo>/target`. When
/// `dry_run` is set nothing is deleted; the outcome reports what would
/// be freed.
pub fn run(start: &Path, dry_run: bool) -> Result<GcOutcome> {
    let root = find_repo_root(start)?;
    let owned = owned_stems(&root);
    let mut out = GcOutcome {
        root: root.clone(),
        dry_run,
        removed_files: 0,
        removed_dirs: 0,
        bytes_freed: 0,
        groups_pruned: 0,
        details: Vec::new(),
    };

    let target = root.join("target");
    for profile in PROFILES {
        let deps = target.join(profile).join("deps");
        if !deps.is_dir() {
            continue;
        }
        let fingerprint = target.join(profile).join(".fingerprint");
        prune_profile(profile, &deps, &fingerprint, &owned, dry_run, &mut out);
    }

    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs::{self, File};
    use std::io::Write;
    use std::thread::sleep;
    use std::time::Duration;

    fn touch(path: &Path, bytes: usize) {
        if let Some(p) = path.parent() {
            fs::create_dir_all(p).unwrap();
        }
        let mut f = File::create(path).unwrap();
        f.write_all(&vec![b'x'; bytes]).unwrap();
    }

    fn scaffold() -> tempfile::TempDir {
        let td = tempfile::tempdir().unwrap();
        let root = td.path();
        File::create(root.join("Cargo.toml")).unwrap();
        fs::create_dir_all(root.join("tests")).unwrap();
        File::create(root.join("tests/foundation.rs")).unwrap();
        td
    }

    #[test]
    fn parse_artifact_accepts_hash_and_rejects_junk() {
        assert_eq!(
            parse_artifact("libmemhub-9596fa5f217857ee.rlib"),
            Some(("libmemhub".to_string(), "9596fa5f217857ee".to_string()))
        );
        // bare test binary, no extension
        assert_eq!(
            parse_artifact("foundation-1f3e35d67f85104d"),
            Some(("foundation".to_string(), "1f3e35d67f85104d".to_string()))
        );
        assert_eq!(parse_artifact(".cargo-lock"), None);
        assert_eq!(parse_artifact("memhub"), None);
        assert_eq!(parse_artifact("libserde-xyz.rlib"), None); // not hex
    }

    #[test]
    fn keeps_newest_hash_and_prunes_older_for_owned_stems() {
        let td = scaffold();
        let root = td.path();
        let deps = root.join("target/debug/deps");
        let fp = root.join("target/debug/.fingerprint");

        // Two libmemhub hashes; the "new" one is written second so its
        // mtime is later.
        touch(&deps.join("libmemhub-aaaaaaaaaaaaaaaa.rlib"), 1000);
        touch(&deps.join("libmemhub-aaaaaaaaaaaaaaaa.rmeta"), 500);
        fs::create_dir_all(fp.join("libmemhub-aaaaaaaaaaaaaaaa")).unwrap();
        touch(&fp.join("libmemhub-aaaaaaaaaaaaaaaa/dep-lib"), 10);
        // A third-party dep with a single hash — must never be touched.
        touch(&deps.join("libserde-cccccccccccccccc.rlib"), 2000);

        sleep(Duration::from_millis(20));
        touch(&deps.join("libmemhub-bbbbbbbbbbbbbbbb.rlib"), 1000);

        let out = run(root, false).unwrap();

        assert!(deps.join("libmemhub-bbbbbbbbbbbbbbbb.rlib").exists());
        assert!(!deps.join("libmemhub-aaaaaaaaaaaaaaaa.rlib").exists());
        assert!(!deps.join("libmemhub-aaaaaaaaaaaaaaaa.rmeta").exists());
        assert!(!fp.join("libmemhub-aaaaaaaaaaaaaaaa").exists());
        // third-party untouched
        assert!(deps.join("libserde-cccccccccccccccc.rlib").exists());
        assert_eq!(out.groups_pruned, 1);
        assert!(out.removed_files >= 2);
        assert!(out.bytes_freed >= 1500);
    }

    #[test]
    fn dry_run_changes_nothing() {
        let td = scaffold();
        let root = td.path();
        let deps = root.join("target/debug/deps");
        touch(&deps.join("libmemhub-aaaaaaaaaaaaaaaa.rlib"), 1000);
        sleep(Duration::from_millis(20));
        touch(&deps.join("libmemhub-bbbbbbbbbbbbbbbb.rlib"), 1000);

        let out = run(root, true).unwrap();

        assert!(deps.join("libmemhub-aaaaaaaaaaaaaaaa.rlib").exists());
        assert!(deps.join("libmemhub-bbbbbbbbbbbbbbbb.rlib").exists());
        assert_eq!(out.groups_pruned, 1);
        assert!(out.bytes_freed >= 1000);
    }

    #[test]
    fn single_hash_is_noop() {
        let td = scaffold();
        let root = td.path();
        let deps = root.join("target/debug/deps");
        touch(&deps.join("libmemhub-aaaaaaaaaaaaaaaa.rlib"), 1000);

        let out = run(root, false).unwrap();
        assert_eq!(out.groups_pruned, 0);
        assert!(deps.join("libmemhub-aaaaaaaaaaaaaaaa.rlib").exists());
    }

    #[test]
    fn no_cargo_toml_is_clear_error() {
        let td = tempfile::tempdir().unwrap();
        let err = run(td.path(), false).unwrap_err();
        assert!(matches!(err, MemhubError::InvalidInput(_)));
    }
}

//! Machine-global memory store (M9).
//!
//! The global store is one optional SQLite per machine at
//! `~/.memhub/global.sqlite`, structurally identical to a repo DB.
//! Enablement is *per-repo*: a repo opts into reading from / writing
//! to the global store via `memhub global enable`. Recall behavior of
//! global hits is governed by the active repo's `[retrieval]` config —
//! the global store has no config of its own.

use std::path::{Path, PathBuf};

use crate::Result;
use crate::config::RetrievalMode;
use crate::db::{self, ProjectContext};

const GLOBAL_ACTOR: &str = "cli:user";

/// Error a global write hits when the active repo has not opted in.
fn disabled_err() -> crate::MemhubError {
    crate::MemhubError::InvalidInput(
        "machine-global memory is disabled for this repo; run `memhub global enable` first"
            .to_string(),
    )
}

/// Gate every global write on the active repo having opted in.
pub fn ensure_enabled(cfg: &crate::config::ProjectConfig) -> Result<()> {
    if cfg.global.enabled {
        Ok(())
    } else {
        Err(disabled_err())
    }
}

/// Scaffolding shared by every born-global / promote write: verify the
/// repo opted in, capture whether this call will create the store
/// (for the one-time disclosure), open the global DB, and surface the
/// *repo's* retrieval mode so global rows embed consistently with how
/// this machine's repos recall.
pub struct GlobalWrite {
    pub ctx: ProjectContext,
    pub store_created: bool,
    pub mode: RetrievalMode,
}

pub fn begin_write(start: &Path) -> Result<GlobalWrite> {
    let repo = db::open_project(start)?;
    ensure_enabled(&repo.config)?;
    let store_created = !db::global_store_exists()?;
    let ctx = db::open_global()?;
    Ok(GlobalWrite {
        ctx,
        store_created,
        mode: repo.config.retrieval.mode,
    })
}

#[derive(Debug)]
pub struct EnableResult {
    pub already_enabled: bool,
    pub store_created: bool,
    pub path: PathBuf,
}

/// Opt this repo into machine-global memory and ensure the store
/// exists (created + migrated on first enable anywhere on the
/// machine).
pub fn enable(start: &Path) -> Result<EnableResult> {
    let repo = db::open_project(start)?;
    let already_enabled = repo.config.global.enabled;

    let store_created = !db::global_store_exists()?;
    // Touch the store so `enable` is also "create if absent".
    let _ = db::open_global()?;

    let mut new_config = repo.config.clone();
    new_config.global.enabled = true;
    new_config.save(&repo.paths.config_path)?;

    db::log_write(
        &repo.conn,
        GLOBAL_ACTOR,
        "config",
        None,
        "update",
        "global enable",
    )?;

    Ok(EnableResult {
        already_enabled,
        store_created,
        path: db::global_db_path()?,
    })
}

/// Opt this repo back out. Non-destructive: the store and its rows
/// remain on disk; recall simply stops merging the global corpus and
/// global writes refuse again.
pub fn disable(start: &Path) -> Result<()> {
    let repo = db::open_project(start)?;
    let mut new_config = repo.config.clone();
    new_config.global.enabled = false;
    new_config.save(&repo.paths.config_path)?;

    db::log_write(
        &repo.conn,
        GLOBAL_ACTOR,
        "config",
        None,
        "update",
        "global disable",
    )?;
    Ok(())
}

#[derive(Debug)]
pub struct GlobalStatus {
    pub enabled: bool,
    pub path: PathBuf,
    pub exists: bool,
    pub schema_version: Option<String>,
    pub fact_count: i64,
    pub decision_count: i64,
    pub doc_chunk_count: i64,
}

pub fn status(start: &Path) -> Result<GlobalStatus> {
    let repo = db::open_project(start)?;
    let path = db::global_db_path()?;
    let exists = db::global_store_exists()?;

    let (schema_version, fact_count, decision_count, doc_chunk_count) = if exists {
        let g = db::open_global()?;
        let schema_version: Option<String> = g
            .conn
            .query_row(
                "SELECT schema_version FROM projects WHERE id = 1",
                [],
                |r| r.get(0),
            )
            .ok();
        let count = |table: &str| -> i64 {
            g.conn
                .query_row(&format!("SELECT COUNT(*) FROM {table}"), [], |r| r.get(0))
                .unwrap_or(0)
        };
        (
            schema_version,
            count("facts"),
            count("decisions"),
            count("doc_chunks"),
        )
    } else {
        (None, 0, 0, 0)
    };

    Ok(GlobalStatus {
        enabled: repo.config.global.enabled,
        path,
        exists,
        schema_version,
        fact_count,
        decision_count,
        doc_chunk_count,
    })
}

use std::fs;
use std::path::{Path, PathBuf};

use rusqlite::{Transaction, params};

use crate::commands::search;
use crate::db;
use crate::export::{EXPORT_VERSION, Export, v1};
use crate::sync_md;
use crate::{MemhubError, Result};

pub struct ImportSummary {
    pub source: PathBuf,
    pub target_root: PathBuf,
    pub forced: bool,
    pub facts: usize,
    pub decisions: usize,
    pub tasks: usize,
    pub commands: usize,
    pub pending_writes: usize,
    pub writes_log: usize,
    pub session_notes: usize,
    pub project_state: usize,
    pub project_arch: usize,
}

pub fn run(start: &Path, source: &Path, force: bool) -> Result<ImportSummary> {
    let raw = fs::read_to_string(source)?;
    let payload: Export = serde_json::from_str(&raw)?;

    if payload.memhub_export_version != EXPORT_VERSION {
        return Err(MemhubError::InvalidInput(format!(
            "unsupported memhub_export_version: {} (this build supports {})",
            payload.memhub_export_version, EXPORT_VERSION
        )));
    }

    let mut ctx = db::open_project(start)?;

    if !force {
        let total = count_durable_rows(&ctx.conn)?;
        if total > 0 {
            return Err(MemhubError::InvalidInput(format!(
                "target memhub project at {} has {} durable row(s); pass --force to overwrite",
                ctx.paths.repo_root.display(),
                total
            )));
        }
    }

    let summary_counts = (
        payload.facts.len(),
        payload.decisions.len(),
        payload.tasks.len(),
        payload.commands.len(),
        payload.pending_writes.len(),
        payload.writes_log.len(),
        payload.session_notes.len(),
        payload.project_state.len(),
        payload.project_arch.len(),
    );

    let tx = ctx.conn.transaction()?;
    tx.execute_batch("PRAGMA defer_foreign_keys = ON")?;

    wipe_durable_tables(&tx)?;
    insert_facts(&tx, &payload.facts)?;
    insert_decisions(&tx, &payload.decisions)?;
    insert_tasks(&tx, &payload.tasks)?;
    insert_commands(&tx, &payload.commands)?;
    insert_pending_writes(&tx, &payload.pending_writes)?;
    insert_writes_log(&tx, &payload.writes_log)?;
    insert_session_notes(&tx, &payload.session_notes)?;
    insert_narrative(&tx, "project_state", &payload.project_state)?;
    insert_narrative(&tx, "project_arch", &payload.project_arch)?;

    search::sync_decision_chunks(&tx)?;

    let reason = if force {
        format!("imported from {} (forced)", source.display())
    } else {
        format!("imported from {}", source.display())
    };
    db::log_write(&tx, "cli:user", "import", None, "import", &reason)?;

    tx.commit()?;

    sync_md::sync_project(&ctx.paths.repo_root)?;

    Ok(ImportSummary {
        source: source.to_path_buf(),
        target_root: ctx.paths.repo_root.clone(),
        forced: force,
        facts: summary_counts.0,
        decisions: summary_counts.1,
        tasks: summary_counts.2,
        commands: summary_counts.3,
        pending_writes: summary_counts.4,
        writes_log: summary_counts.5,
        session_notes: summary_counts.6,
        project_state: summary_counts.7,
        project_arch: summary_counts.8,
    })
}

fn count_durable_rows(conn: &rusqlite::Connection) -> Result<i64> {
    let mut total: i64 = 0;
    for table in [
        "facts",
        "decisions",
        "tasks",
        "commands",
        "pending_writes",
        "session_notes",
        "project_state",
        "project_arch",
    ] {
        let count: i64 = conn.query_row(
            &format!("SELECT COUNT(*) FROM {table} WHERE project_id = 1"),
            [],
            |row| row.get(0),
        )?;
        total += count;
    }
    Ok(total)
}

fn wipe_durable_tables(tx: &Transaction<'_>) -> Result<()> {
    tx.execute(
        "DELETE FROM chunks WHERE project_id = 1 AND source_type = 'decision'",
        [],
    )?;
    for table in [
        "writes_log",
        "pending_writes",
        "commands",
        "tasks",
        "facts",
        "session_notes",
        "project_state",
        "project_arch",
    ] {
        tx.execute(&format!("DELETE FROM {table} WHERE project_id = 1"), [])?;
    }
    tx.execute("DELETE FROM decisions WHERE project_id = 1", [])?;
    Ok(())
}

fn insert_facts(tx: &Transaction<'_>, rows: &[v1::Fact]) -> Result<()> {
    let mut stmt = tx.prepare(
        "INSERT INTO facts(id, project_id, key, value, confidence, source, verified_at, created_at)
         VALUES (?1, 1, ?2, ?3, ?4, ?5, ?6, ?7)",
    )?;
    for fact in rows {
        stmt.execute(params![
            fact.id,
            fact.key,
            fact.value,
            fact.confidence,
            fact.source,
            fact.verified_at,
            fact.created_at,
        ])?;
    }
    Ok(())
}

fn insert_decisions(tx: &Transaction<'_>, rows: &[v1::Decision]) -> Result<()> {
    let mut stmt = tx.prepare(
        "INSERT INTO decisions(id, project_id, title, rationale, status, decided_at, superseded_by, source, summary)
         VALUES (?1, 1, ?2, ?3, ?4, ?5, ?6, ?7, ?8)",
    )?;
    for decision in rows {
        stmt.execute(params![
            decision.id,
            decision.title,
            decision.rationale,
            decision.status,
            decision.decided_at,
            decision.superseded_by,
            decision.source,
            decision.summary,
        ])?;
    }
    Ok(())
}

fn insert_tasks(tx: &Transaction<'_>, rows: &[v1::Task]) -> Result<()> {
