fn insert_pending_writes(tx: &Transaction<'_>, rows: &[v1::PendingWrite]) -> Result<()> {
    let mut stmt = tx.prepare(
        "INSERT INTO pending_writes(
             id, project_id, kind, payload_json, rationale, status,
