fn insert_writes_log(tx: &Transaction<'_>, rows: &[v1::WriteLogEntry]) -> Result<()> {
    let mut stmt = tx.prepare(
        "INSERT INTO writes_log(id, project_id, actor, table_name, row_id, action, reason, at)
         VALUES (?1, 1, ?2, ?3, ?4, ?5, ?6, ?7)",
