}

fn embedding_matches(
    conn: &Connection,
    source_type: SourceType,
    source_id: i64,
    text: &str,
) -> Result<bool> {
    let expected = sha256_hex(text);
    let existing: Option<String> = conn
        .query_row(
            "SELECT content_hash FROM embeddings
             WHERE source_type = ?1
               AND source_id = ?2
               AND model_name = ?3
               AND dimension = ?4",
            params![
                source_type.as_str(),
                source_id,
                EMBEDDING_MODEL_NAME,
                EMBEDDING_DIMENSION as i64,
            ],
            |row| row.get(0),
        )
        .optional()?;
    Ok(existing.as_deref() == Some(expected.as_str()))
}

fn current_source_hash(
    tx: &rusqlite::Transaction<'_>,
    source_type: SourceType,
    source_id: i64,
) -> Result<Option<String>> {
    let text = match source_type {
        SourceType::Fact => tx
            .query_row(
                "SELECT key, value FROM facts WHERE id = ?1",
                params![source_id],
                |row| {
                    let key: String = row.get(0)?;
                    let value: String = row.get(1)?;
                    Ok(fact_embed_text(&key, &value))
                },
            )
            .optional()?,
        SourceType::Decision => tx
            .query_row(
                "SELECT title, rationale, summary FROM decisions WHERE id = ?1",
                params![source_id],
                |row| {
                    let title: String = row.get(0)?;
                    let rationale: String = row.get(1)?;
                    let summary: Option<String> = row.get(2)?;
                    Ok(decision_embed_text(&title, &rationale, summary.as_deref()))
                },
            )
            .optional()?,
        SourceType::Task => tx
            .query_row(
                "SELECT title, notes FROM tasks WHERE id = ?1",
                params![source_id],
                |row| {
                    let title: String = row.get(0)?;
                    let notes: Option<String> = row.get(1)?;
                    Ok(task_embed_text(&title, notes.as_deref()))
                },
            )
            .optional()?,
        SourceType::DocChunk => tx
            .query_row(
                "SELECT heading_path, body FROM doc_chunks WHERE id = ?1",
                params![source_id],
                |row| {
                    let heading_path: String = row.get(0)?;
                    let body: String = row.get(1)?;
                    Ok(doc_chunk_embed_text(&heading_path, &body))
                },
            )
            .optional()?,
    };
    Ok(text.map(|value| sha256_hex(&value)))
}

fn vector_to_le_bytes(v: &[f32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(v.len() * 4);
    for f in v {
        out.extend_from_slice(&f.to_le_bytes());
    }
    out
}

fn sha256_hex(text: &str) -> String {
    use sha2::{Digest, Sha256};
    let mut hasher = Sha256::new();
    hasher.update(text.as_bytes());
    let digest = hasher.finalize();
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(digest.len() * 2);
    for b in digest {
        out.push(HEX[(b >> 4) as usize] as char);
        out.push(HEX[(b & 0x0f) as usize] as char);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::commands::{decision, fact, init, task};
    use crate::config::{ProjectConfig, RetrievalMode};
    use rusqlite::params;
    use tempfile::tempdir;

    #[test]
    fn status_reports_zero_coverage_under_fts_mode() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        fact::add(
            temp.path(),
            "build-command",
            "cargo build",
            "user",
            "cli:user",
        )
        .expect("fact");
        decision::add(
            temp.path(),
            "Stage agent writes",
            "Require human review for durable rows.",
            "user",
            "cli:user",
        )
        .expect("decision");
        task::add(temp.path(), "Ship M8", Some("PR5 in flight"), "cli:user").expect("task");

        let summary = status(temp.path()).expect("status");
        assert_eq!(summary.facts_total, 1);
        assert_eq!(summary.decisions_total, 1);
        assert_eq!(summary.tasks_total, 1);
        assert_eq!(summary.facts_embedded, 0);
        assert_eq!(summary.decisions_embedded, 0);
        assert_eq!(summary.tasks_embedded, 0);
        assert_eq!(summary.missing_count, 3);
        assert!((summary.stale_ratio - 1.0).abs() < 1e-9);
    }

    #[test]
    fn rebuild_populates_embeddings_for_existing_rows() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        fact::add(
            temp.path(),
            "build-command",
            "cargo build",
            "user",
            "cli:user",
        )
        .expect("fact");
        decision::add(
            temp.path(),
            "Adopt hybrid recall",
            "Blend FTS and vector scoring.",
            "user",
            "cli:user",
        )
        .expect("decision");
        task::add(temp.path(), "Ship recall", None, "cli:user").expect("task");

        let summary = rebuild(temp.path(), "cli:user").expect("rebuild");
        assert_eq!(summary.facts, 1);
        assert_eq!(summary.decisions, 1);
        assert_eq!(summary.tasks, 1);

        let after = status(temp.path()).expect("status");
        assert_eq!(after.facts_embedded, 1);
        assert_eq!(after.decisions_embedded, 1);
        assert_eq!(after.tasks_embedded, 1);
        assert_eq!(after.missing_count, 0);
    }

    #[test]
    fn rebuild_logs_one_writes_log_entry() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        fact::add(temp.path(), "k", "v", "user", "cli:user").expect("seed");

        rebuild(temp.path(), "claude-code:reindex").expect("rebuild");

        let ctx = db::open_project(temp.path()).expect("open");
        let (actor, reason): (String, String) = ctx
            .conn
            .query_row(
                "SELECT actor, reason FROM writes_log
                 WHERE table_name = 'embeddings'
                 ORDER BY id DESC LIMIT 1",
                params![],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .expect("writes_log row");
        assert_eq!(actor, "claude-code:reindex");
        assert!(reason.contains("rebuild"));
    }

    #[test]
    fn rebuild_replaces_stale_embeddings_after_source_drift() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        fact::add(temp.path(), "k", "value-one", "user", "cli:user").expect("seed");
        rebuild(temp.path(), "cli:user").expect("first");

        let before_hash: String = {
            let ctx = db::open_project(temp.path()).expect("open");
            ctx.conn
                .query_row(
                    "SELECT content_hash FROM embeddings WHERE source_type = 'fact'",
                    params![],
                    |r| r.get(0),
                )
                .expect("hash")
        };

        // Mutate the row out-of-band (simulating model upgrade or direct edit)
        // so that the embedding hash no longer matches current text.
        {
            let ctx = db::open_project(temp.path()).expect("open");
            ctx.conn
                .execute(
                    "UPDATE facts SET value = 'value-two' WHERE key = 'k'",
                    params![],
                )
                .expect("mutate");
        }

        rebuild(temp.path(), "cli:user").expect("second");
        let after_hash: String = {
            let ctx = db::open_project(temp.path()).expect("open");
            ctx.conn
                .query_row(
                    "SELECT content_hash FROM embeddings WHERE source_type = 'fact'",
                    params![],
                    |r| r.get(0),
                )
                .expect("hash")
        };
        assert_ne!(before_hash, after_hash);
    }

    #[test]
    fn status_treats_content_hash_drift_as_missing_coverage() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        fact::add(temp.path(), "k", "value-one", "user", "cli:user").expect("seed");
        rebuild(temp.path(), "cli:user").expect("rebuild");

        {
            let ctx = db::open_project(temp.path()).expect("open");
            ctx.conn
                .execute(
                    "UPDATE facts SET value = 'value-two' WHERE key = 'k'",
                    params![],
                )
                .expect("drift source");
        }

        let summary = status(temp.path()).expect("status");
        assert_eq!(summary.facts_total, 1);
        assert_eq!(summary.facts_embedded, 0);
        assert_eq!(summary.missing_count, 1);
        assert!((summary.stale_ratio - 1.0).abs() < 1e-9);
    }

    #[test]
    fn rebuild_snapshot_upsert_does_not_overwrite_newer_eager_embedding() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let cfg_path = temp.path().join(".memhub/config.toml");
        let mut cfg = ProjectConfig::load(&cfg_path).expect("load config");
        cfg.retrieval.mode = RetrievalMode::Hybrid;
        cfg.save(&cfg_path).expect("save config");

        let fact_id = fact::add(temp.path(), "k", "value-one", "user", "cli:user")
            .expect("seed")
            .0;

        let snapshot_rows = {
            let ctx = db::open_project(temp.path()).expect("open");
            collect_source_rows(&ctx.conn).expect("collect")
        };
        let texts: Vec<String> = snapshot_rows
            .facts
            .iter()
            .map(|(_, key, value)| fact_embed_text(key, value))
            .collect();
        let vectors = embed_batch(&texts).expect("embed snapshot");
        let stale_vectors: Vec<(i64, Vec<f32>, String)> = snapshot_rows
            .facts
            .iter()
            .zip(texts.into_iter().zip(vectors))
            .map(|((id, _, _), (text, vector))| (*id, vector, text))
            .collect();

        fact::add(temp.path(), "k", "value-two", "user", "cli:user").expect("update");
        let fresh_hash: String = {
            let ctx = db::open_project(temp.path()).expect("open");
            ctx.conn
                .query_row(
                    "SELECT content_hash FROM embeddings
                     WHERE source_type = 'fact' AND source_id = ?1",
                    params![fact_id],
                    |r| r.get(0),
                )
                .expect("fresh hash")
        };

        let written = {
            let mut ctx = db::open_project(temp.path()).expect("open");
            let tx = ctx.conn.transaction().expect("tx");
            let written =
                upsert_batch(&tx, SourceType::Fact, &stale_vectors).expect("conditional upsert");
            tx.commit().expect("commit");
            written
        };

        let after_hash: String = {
            let ctx = db::open_project(temp.path()).expect("open");
            ctx.conn
                .query_row(
                    "SELECT content_hash FROM embeddings
                     WHERE source_type = 'fact' AND source_id = ?1",
                    params![fact_id],
                    |r| r.get(0),
                )
                .expect("after hash")
        };

        assert_eq!(written, 0);
        assert_eq!(after_hash, fresh_hash);
    }
}

use std::collections::HashSet;
use std::path::Path;
use std::process::Command;

use rusqlite::params;

use crate::Result;
use crate::config::PathMatcher;
use crate::db;
use crate::errors::MemhubError;
use crate::models::GitIngestSummary;

#[derive(Debug)]
struct GitCommit {
    sha: String,
    author: String,
    committed_at: String,
    message: String,
    files: Vec<GitFileChange>,
}

#[derive(Debug)]
struct GitFileChange {
    change_type: String,
    path: String,
}

pub fn run(start: &Path, since: Option<&str>) -> Result<GitIngestSummary> {
    let mut ctx = db::open_project(start)?;
    let matcher = PathMatcher::from_patterns(&ctx.config.deny_list.patterns)?;
    let commits = load_git_history(&ctx.paths.repo_root, since)?;

    let mut unique_files = HashSet::new();
    let mut commit_file_links_seen = 0usize;
    let mut denied_files_skipped = 0usize;

    let tx = ctx.conn.transaction()?;
    for commit in &commits {
        tx.execute(
            "INSERT INTO commits(sha, project_id, author, committed_at, message)
             VALUES (?1, 1, ?2, ?3, ?4)
             ON CONFLICT(sha) DO UPDATE SET
                 author = excluded.author,
                 committed_at = excluded.committed_at,
                 message = excluded.message",
            params![
                commit.sha.as_str(),
                commit.author.as_str(),
                commit.committed_at.as_str(),
                commit.message.as_str()
            ],
        )?;

        for file in &commit.files {
            if matcher.is_denied(&file.path) {
                denied_files_skipped += 1;
                continue;
            }
            tx.execute(
                "INSERT INTO files(project_id, path, last_seen_commit, language)
                 VALUES (1, ?1, ?2, ?3)
                 ON CONFLICT(project_id, path) DO UPDATE SET
                     last_seen_commit = CASE
                         WHEN files.last_seen_commit IS NULL THEN excluded.last_seen_commit
                         WHEN (
                             SELECT committed_at FROM commits WHERE sha = excluded.last_seen_commit
                         ) >= COALESCE((
                             SELECT committed_at FROM commits WHERE sha = files.last_seen_commit
                         ), '')
                         THEN excluded.last_seen_commit
                         ELSE files.last_seen_commit
                     END,
                     language = COALESCE(files.language, excluded.language)",
                params![
                    file.path.as_str(),
                    commit.sha.as_str(),
                    infer_language(&file.path)
                ],
            )?;

            let file_id: i64 = tx.query_row(
                "SELECT id FROM files WHERE project_id = 1 AND path = ?1",
                [file.path.as_str()],
                |row| row.get(0),
            )?;

            tx.execute(
                "INSERT INTO commit_files(commit_sha, file_id, change_type)
                 VALUES (?1, ?2, ?3)
                 ON CONFLICT(commit_sha, file_id) DO UPDATE SET
                     change_type = excluded.change_type",
                params![commit.sha.as_str(), file_id, file.change_type.as_str()],
            )?;

            unique_files.insert(file.path.clone());
            commit_file_links_seen += 1;
        }
    }

    db::log_write(&tx, "cli:user", "commits", None, "ingest", "ingest-git")?;

    tx.commit()?;

    Ok(GitIngestSummary {
        since: since.map(str::to_string),
        commits_seen: commits.len(),
        unique_files_seen: unique_files.len(),
        commit_file_links_seen,
        denied_files_skipped,
    })
}

fn load_git_history(repo_root: &Path, since: Option<&str>) -> Result<Vec<GitCommit>> {
    let mut command = Command::new("git");
    command
        .arg("-C")
        .arg(repo_root)
        .arg("log")
        .arg("--date=iso-strict")
        .arg("--pretty=format:commit\x1f%H\x1f%an\x1f%aI\x1f%s")
        .arg("--name-status")
        .arg("--find-renames");

    if let Some(since) = since.map(str::trim).filter(|value| !value.is_empty()) {
        command.arg(format!("{since}..HEAD"));
    }

    let output = command.output()?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
        return Err(MemhubError::ExternalCommand {
            command: format!("git -C {} log", repo_root.display()),
            stderr: if stderr.is_empty() {
                "unknown git error".to_string()
            } else {
                stderr
            },
        });
    }

    parse_git_log(&String::from_utf8_lossy(&output.stdout))
}

fn parse_git_log(output: &str) -> Result<Vec<GitCommit>> {
    let mut commits = Vec::new();
    let mut current: Option<GitCommit> = None;

    for line in output.lines() {
        if line.is_empty() {
            continue;
        }

        if let Some(rest) = line.strip_prefix("commit\x1f") {
            if let Some(commit) = current.take() {
                commits.push(commit);
            }

            let parts: Vec<_> = rest.split('\x1f').collect();
            if parts.len() != 4 {
                return Err(MemhubError::InvalidInput(format!(
                    "unexpected git log header: {line}"
                )));
            }

            current = Some(GitCommit {
                sha: parts[0].to_string(),
                author: parts[1].to_string(),
                committed_at: parts[2].to_string(),
                message: parts[3].to_string(),
                files: Vec::new(),
            });
            continue;
        }

        let commit = current.as_mut().ok_or_else(|| {
            MemhubError::InvalidInput("git log output contained file rows before a commit".into())
        })?;
        if let Some(change) = parse_file_change(line) {
            commit.files.push(change);
        }
    }

    if let Some(commit) = current.take() {
        commits.push(commit);
    }

    Ok(commits)
}

fn parse_file_change(line: &str) -> Option<GitFileChange> {
    let mut parts = line.split('\t');
    let status = parts.next()?.trim();
    let primary = status.chars().next()?;
    let change_type = primary.to_string();

    let path = match primary {
        'R' | 'C' => {
            parts.next()?;
            parts.next()?
        }
        _ => parts.next()?,
    };

    Some(GitFileChange {
        change_type,
        path: path.replace('\\', "/"),
    })
}

fn infer_language(path: &str) -> Option<&'static str> {
    let extension = path.rsplit('.').next()?;
    match extension.to_ascii_lowercase().as_str() {
        "rs" => Some("rust"),
        "toml" => Some("toml"),
        "md" => Some("markdown"),
        "json" => Some("json"),
        "yaml" | "yml" => Some("yaml"),
        "ts" | "tsx" => Some("typescript"),
        "js" | "jsx" => Some("javascript"),
        "py" => Some("python"),
        "sql" => Some("sql"),
        _ => None,
    }
}

use std::path::Path;

use crate::commands::import::{self, ImportSummary};
use crate::commands::integrations;
use crate::db;
use crate::models::InitResult;
use crate::sync_md;
use crate::{MemhubError, Result};

pub fn run(repo_root: &Path) -> Result<InitResult> {
    let (ctx, result) = db::init_project(repo_root)?;
    if result.config_created {
        let mut config = ctx.config.clone();
        if integrations::apply_k9_detection_on_init(repo_root, &mut config) {
            config.save(&ctx.paths.config_path)?;
        }
    }
    drop(ctx);
    let _ = sync_md::sync_project(repo_root)?;
    Ok(result)
}

pub fn run_with_backup(repo_root: &Path, backup: &Path) -> Result<(InitResult, ImportSummary)> {
    let paths = db::ProjectPaths::for_repo_root(repo_root);
    if paths.db_path.exists() {
        return Err(MemhubError::InvalidInput(format!(
            "memhub database already exists at {}; use `memhub import --force <path>` to overwrite it",
            paths.db_path.display()
        )));
    }

    let (ctx, init_result) = db::init_project_for_recovery(repo_root)?;
    if init_result.config_created {
        let mut config = ctx.config.clone();
        if integrations::apply_k9_detection_on_init(repo_root, &mut config) {
            config.save(&ctx.paths.config_path)?;
        }
    }
    drop(ctx);
    let import_summary = import::run(repo_root, backup, false)?;
    Ok((init_result, import_summary))
}

use std::path::Path;

use crate::config::{
    DEFAULT_AGENT_DOCS_PATH, IntegrationsConfig, K9Config, ProjectConfig, detect_k9,
};
use crate::db;
use crate::{MemhubError, Result};

#[derive(Debug)]
pub struct K9IntegrationState {
    pub detected: bool,
    pub enabled: bool,
    pub agent_docs_path: String,
    pub drift: Option<String>,
}

#[derive(Debug)]
pub struct IntegrationsStatus {
    pub k9: K9IntegrationState,
}

pub fn status(start: &Path) -> Result<IntegrationsStatus> {
    let ctx = db::open_project(start)?;
    Ok(IntegrationsStatus {
        k9: k9_state(&ctx.paths.repo_root, &ctx.config.integrations),
    })
}

pub fn enable_k9(start: &Path, agent_docs_path: Option<&str>, force: bool) -> Result<()> {
    let ctx = db::open_project(start)?;
    let resolved_path = agent_docs_path
        .map(|p| p.to_string())
        .or_else(|| {
            ctx.config
                .integrations
                .k9
                .as_ref()
                .map(|cfg| cfg.agent_docs_path.clone())
        })
        .unwrap_or_else(|| DEFAULT_AGENT_DOCS_PATH.to_string());

    let detected = detect_k9(&ctx.paths.repo_root, &resolved_path);
    if !detected && !force {
        return Err(MemhubError::InvalidInput(format!(
            "K9 not detected at {}/project_state.md; pass --force to enable anyway",
            resolved_path
        )));
    }

    let mut config = ctx.config.clone();
    config.integrations.k9 = Some(K9Config {
        enabled: true,
        agent_docs_path: resolved_path,
    });
    config.save(&ctx.paths.config_path)?;

    db::log_write(
        &ctx.conn,
        "cli:user",
        "config",
        None,
        "update",
        "integrations enable k9",
    )?;
    Ok(())
}

pub fn disable_k9(start: &Path) -> Result<()> {
    let ctx = db::open_project(start)?;
    let Some(existing) = ctx.config.integrations.k9.clone() else {
        return Err(MemhubError::InvalidInput(
            "K9 integration is not configured for this project".to_string(),
        ));
    };

    let mut config = ctx.config.clone();
    config.integrations.k9 = Some(K9Config {
        enabled: false,
        agent_docs_path: existing.agent_docs_path,
    });
    config.save(&ctx.paths.config_path)?;

    db::log_write(
        &ctx.conn,
        "cli:user",
        "config",
        None,
        "update",
        "integrations disable k9",
    )?;
    Ok(())
}

pub(crate) fn k9_state(repo_root: &Path, integrations: &IntegrationsConfig) -> K9IntegrationState {
    let agent_docs_path = integrations
        .k9
        .as_ref()
        .map(|cfg| cfg.agent_docs_path.clone())
        .unwrap_or_else(|| DEFAULT_AGENT_DOCS_PATH.to_string());
    let detected = detect_k9(repo_root, &agent_docs_path);
    let enabled = integrations
        .k9
        .as_ref()
        .map(|cfg| cfg.enabled)
        .unwrap_or(false);

    let drift = match (enabled, detected, integrations.k9.is_some()) {
        (true, false, _) => Some(format!(
            "K9 enabled in config but {}/project_state.md is missing",
            agent_docs_path
        )),
        (false, true, false) => {
            Some("K9 detected; run `memhub integrations enable k9` to enable".to_string())
        }
        _ => None,
    };

    K9IntegrationState {
        detected,
        enabled,
        agent_docs_path,
        drift,
    }
}

pub fn check_k9(start: &Path) -> bool {
    let Ok(ctx) = db::open_project(start) else {
        return false;
    };
    ctx.config
        .integrations
        .k9
        .as_ref()
        .map(|cfg| cfg.enabled)
        .unwrap_or(false)
}

pub fn apply_k9_detection_on_init(repo_root: &Path, config: &mut ProjectConfig) -> bool {
    let path = config
        .integrations
        .k9
        .as_ref()
        .map(|cfg| cfg.agent_docs_path.clone())
        .unwrap_or_else(|| DEFAULT_AGENT_DOCS_PATH.to_string());
    if detect_k9(repo_root, &path) {
        config.integrations.k9 = Some(K9Config {
            enabled: true,
            agent_docs_path: path,
        });
        true
    } else {
        false
    }
}

//! `memhub metrics` subcommand handlers (task #31).
//!
//! Provides the user-facing surface for the token-accounting subsystem
//! (decision 74): status, enable, disable, rescan, and prune.
//!
//! The subsystem is off by default; all reads and writes are gated on
//! `MetricsConfig.enabled`. Config mutations are written back to the
//! machine-local `config.toml` via `ProjectConfig::save` so each
//! invocation inherits the updated state, exactly as the integrations
//! commands do.
//!
//! `db::open_project` already runs `scrape_if_enabled` and
//! `maintenance::run_if_enabled` opportunistically on every `memhub`
//! invocation (task #30), so by the time any `metrics` handler runs the
//! DB is current. The explicit maintenance calls here (`rescan`,
//! `prune`) are idempotent but surface their return values to the user,
//! which the background path does not.

use std::path::Path;

use rusqlite::{OptionalExtension, params};

use crate::config::MetricsConfig;
use crate::db;
use crate::metrics::formatter::{self, PeriodTotals, SessionSummary};
use crate::metrics::maintenance;
use crate::metrics::session_scraper;
use crate::{MemhubError, Result};

const METRICS_ACTOR: &str = "cli:user";

/// All data the `memhub.metrics` MCP tool needs. Built by `query_tool_data`.
#[derive(Debug)]
pub struct MetricsToolData {
    pub enabled: bool,
    pub recall_proxy: bool,
    pub session_accounting: bool,
    pub claude_transcripts_dir: Option<String>,
    /// MAX(ended_at) from session_metrics — the last timestamp the scraper advanced.
    pub last_scrape_ts: Option<String>,
    pub totals_7d: PeriodTotals,
    pub totals_30d: PeriodTotals,
    /// Up to 10 most recent sessions, newest first.
    pub last_sessions: Vec<SessionSummary>,
    /// Pre-rendered text panel for the /metrics skill.
    pub rendered_panel: String,
}

/// Query all token-accounting data for the MCP tool. Returns immediately
/// when `enabled = false` with only the flag set; no DB aggregation runs
/// so no stale rows from a prior-enabled stretch can leak through.
pub fn query_tool_data(start: &Path) -> Result<MetricsToolData> {
    let ctx = db::open_project(start)?;
    let cfg = &ctx.config.metrics;

    if !cfg.enabled {
        return Ok(MetricsToolData {
            enabled: false,
            recall_proxy: cfg.recall_proxy,
            session_accounting: cfg.session_accounting,
            claude_transcripts_dir: None,
            last_scrape_ts: None,
            totals_7d: PeriodTotals::default(),
            totals_30d: PeriodTotals::default(),
            last_sessions: Vec::new(),
            rendered_panel: String::new(),
        });
    }

    let transcripts_dir = if cfg.claude_transcripts_dir.is_empty() {
        None
    } else {
        Some(cfg.claude_transcripts_dir.clone())
    };

    // MAX(ended_at) across all scraped sessions — most recent scrape advance.
    let last_scrape_ts: Option<String> = ctx
        .conn
        .query_row("SELECT MAX(ended_at) FROM session_metrics", [], |r| {
            r.get(0)
        })
        .unwrap_or(None);

    let totals_7d = query_period_totals(&ctx.conn, 7)?;
    let totals_30d = query_period_totals(&ctx.conn, 30)?;

    let last_sessions = query_last_sessions(&ctx.conn, 10)?;

    let rendered_panel =
        if totals_7d.is_empty() && totals_30d.is_empty() && last_sessions.is_empty() {
            formatter::render_panel_no_data().to_string()
        } else {
            formatter::render_panel(&totals_7d, &totals_30d, &last_sessions)
        };

    Ok(MetricsToolData {
        enabled: true,
        recall_proxy: cfg.recall_proxy,
        session_accounting: cfg.session_accounting,
        claude_transcripts_dir: transcripts_dir,
        last_scrape_ts,
        totals_7d,
        totals_30d,
        last_sessions,
        rendered_panel,
    })
}

/// Median of a pre-sorted ascending slice. Even-length sets average the two
/// middle values (integer division — a token estimate, not exact arithmetic).
/// `None` on an empty slice.
fn median_i64(sorted: &[i64]) -> Option<i64> {
    let n = sorted.len();
    if n == 0 {
        return None;
    }
    if n % 2 == 1 {
        Some(sorted[n / 2])
    } else {
        Some((sorted[n / 2 - 1] + sorted[n / 2]) / 2)
    }
}

pub(crate) fn query_period_totals(conn: &rusqlite::Connection, days: u32) -> Result<PeriodTotals> {
    let modifier = format!("-{days} days");

    // Total recall count (all calls, including empty-bundle ones).
    let recalls: i64 = conn
        .query_row(
            "SELECT COALESCE(COUNT(*), 0) FROM recall_metrics \
             WHERE datetime(ts) >= datetime('now', ?1)",
            params![modifier],
            |r| r.get(0),
        )
        .unwrap_or(0);

    // Sum of non-empty bundle_tokens. Empty recalls (bundle_tokens == 0)
    // are not savings events and are excluded.
    let bundle_tokens: i64 = conn
        .query_row(
            "SELECT COALESCE(SUM(CASE WHEN bundle_tokens > 0 THEN bundle_tokens ELSE 0 END), 0) \
             FROM recall_metrics WHERE datetime(ts) >= datetime('now', ?1)",
            params![modifier],
            |r| r.get(0),
        )
        .unwrap_or(0);

    // Session-scoped ledger baseline: charge one ledger load (the minimum
    // observed across all recalls in that session, as a proxy for session
    // start) per session that had at least one non-empty recall. Sessions
    // where every recall returned an empty bundle contribute 0.
    let ledger_tokens: i64 = conn
        .query_row(
            "SELECT COALESCE(SUM(min_ledger), 0) FROM ( \
                 SELECT MIN(ledger_tokens) AS min_ledger \
                 FROM recall_metrics \
                 WHERE datetime(ts) >= datetime('now', ?1) \
                   AND session_id IS NOT NULL \
                 GROUP BY session_id \
                 HAVING SUM(CASE WHEN bundle_tokens > 0 THEN 1 ELSE 0 END) > 0 \
             )",
            params![modifier],
            |r| r.get(0),
        )
        .unwrap_or(0);

    // session_metrics: count + token sums for sessions starting in the window.
    let (sessions, input_tokens, output_tokens, cache_read_tokens, cache_creation_tokens): (
        i64,
        i64,
        i64,
        i64,
        i64,
    ) = conn
        .query_row(
            "SELECT \
               COALESCE(COUNT(*), 0), \
               COALESCE(SUM(input_tokens), 0), \
               COALESCE(SUM(output_tokens), 0), \
               COALESCE(SUM(cache_read_tokens), 0), \
               COALESCE(SUM(cache_creation_tokens), 0) \
             FROM session_metrics \
             WHERE datetime(started_at) >= datetime('now', ?1)",
            params![modifier],
            |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?, r.get(4)?)),
        )
        .unwrap_or((0, 0, 0, 0, 0));

    // Per-session mean churn: each in-window session's own
    // cache_creation/(cache_read+cache_creation), averaged with equal
    // weight so one large session can't dominate. Sessions with no cache
    // activity are excluded from the denominator; AVG over zero qualifying
    // rows yields SQL NULL → None.
    let mean_session_churn_pct: Option<f64> = conn
        .query_row(
            "SELECT AVG( \
                 cache_creation_tokens * 1.0 \
                 / (cache_read_tokens + cache_creation_tokens) \
             ) * 100.0 \
             FROM session_metrics \
             WHERE datetime(started_at) >= datetime('now', ?1) \
               AND (cache_read_tokens + cache_creation_tokens) > 0",
            params![modifier],
            |r| r.get(0),
        )
        .unwrap_or(None);

    // Distinct sessions in the window that had ≥1 non-empty recall — the
    // sessions the empirical counterfactual is charged against (task 64).
    // Same grouping/HAVING as the ledger baseline above, counted.
    let recall_sessions: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM ( \
                 SELECT session_id FROM recall_metrics \
                 WHERE datetime(ts) >= datetime('now', ?1) \
                   AND session_id IS NOT NULL \
                 GROUP BY session_id \
                 HAVING SUM(CASE WHEN bundle_tokens > 0 THEN 1 ELSE 0 END) > 0 \
             )",
            params![modifier],
            |r| r.get(0),
        )
        .unwrap_or(0);

    // Empirical counterfactual baseline (task 64): the MEDIAN first-turn
    // startup cost across the window's NO-recall sessions. SQLite has no
    // median aggregate, so pull the (small) set of values and compute it in
    // Rust. recall_calls is owned by the reconciler; a session that never
    // recalled stays at 0.
    let baselines: Vec<i64> = {
        let mut stmt = conn.prepare(
            "SELECT baseline_input_tokens FROM session_metrics \
             WHERE datetime(started_at) >= datetime('now', ?1) \
               AND recall_calls = 0 \
               AND baseline_input_tokens IS NOT NULL \
             ORDER BY baseline_input_tokens",
        )?;
        stmt.query_map(params![modifier], |r| r.get(0))?
            .filter_map(|x| x.ok())
            .collect()
    };
    let empirical_baseline = median_i64(&baselines);

    Ok(PeriodTotals {
        recalls,
        bundle_tokens,
        ledger_tokens,
        sessions,
        input_tokens,
        output_tokens,
        cache_read_tokens,
        cache_creation_tokens,
        mean_session_churn_pct,
        recall_sessions,
        empirical_baseline,
    })
}

fn query_last_sessions(conn: &rusqlite::Connection, limit: i64) -> Result<Vec<SessionSummary>> {
    let mut stmt = conn.prepare(
        "SELECT \
           session_id, \
           agent, \
           datetime(started_at, 'localtime') AS started_local, \
           datetime(ended_at, 'localtime') AS ended_local, \
           input_tokens, \
           output_tokens, \
           recall_calls \
         FROM session_metrics \
         ORDER BY started_at DESC \
         LIMIT ?1",
    )?;
    let rows = stmt
        .query_map(params![limit], |row| {
            Ok(SessionSummary {
                session_id: row.get(0)?,
                agent: row.get(1)?,
                started_at: row.get::<_, Option<String>>(2)?.unwrap_or_default(),
                ended_at: row.get(3)?,
                input_tokens: row.get(4)?,
                output_tokens: row.get(5)?,
                recall_calls: row.get(6)?,
            })
        })?
        .filter_map(|r| r.ok())
        .collect();
    Ok(rows)
}

/// Chart range for the dashboard burn-up. `Session` is the latest
/// session rendered turn-by-turn (per-turn granularity, migration
/// 0013); the windowed variants render one cumulative point per
/// session.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SeriesWindow {
    Session,
    Days(u32),
    All,
}

impl SeriesWindow {
    /// Parse the `window` query param. Unknown values fall back to 7d
    /// rather than erroring — the dashboard is a read-only inspector
    /// and a bad param should degrade, not 500.
    pub fn parse(raw: &str) -> Self {
        match raw {
            "session" | "current" => SeriesWindow::Session,
            "30d" => SeriesWindow::Days(30),
            "all" => SeriesWindow::All,
            _ => SeriesWindow::Days(7),
        }
    }

    fn label(&self) -> String {
        match self {
            SeriesWindow::Session => "session".to_string(),
            SeriesWindow::Days(n) => format!("{n}d"),
            SeriesWindow::All => "all".to_string(),
        }
    }

    fn granularity(&self) -> &'static str {
        match self {
            SeriesWindow::Session => "turn",
            _ => "session",
        }
    }
}

/// One plotted point. `actual` is the cumulative real token spend up
/// to and including this point; `counterfactual` is that same
/// cumulative plus the session-scoped ledger offset — what the context
/// *would* have cost if each session with at least one successful recall
/// had instead loaded the full `PROJECT_LEDGER.md` once at session start.
/// Empty-bundle recalls (bundle_tokens == 0) are excluded from the savings
/// calculation: a failed retrieval is not a savings event. Per the proxy
/// contract this is a labelled estimate ("context offset vs full-ledger
/// baseline"), never "tokens saved", and the tiktoken cl100k count is
/// ±10% of Anthropic's real tokenizer.
#[derive(Debug, Clone)]
pub struct SeriesPoint {
    /// Unix seconds (UTC). Synthetic monotonic fallback when the
    /// source timestamp is missing/unparseable so uPlot still gets a
    /// strictly increasing x.
    pub x: i64,
    pub label: String,
    pub actual: i64,
    pub counterfactual: i64,
    /// This point's own input+output spend (not cumulative).
    pub delta: i64,
    /// Cumulative session-scoped ledger offset up to here: for each session
    /// that had ≥1 non-empty recall, max(0, min(ledger) − Σ non-empty bundles).
    pub recall_offset: i64,
    /// Cumulative recall calls counted up to here (includes empty recalls).
    pub recalls: i64,
}

#[derive(Debug)]
pub struct SeriesData {
    pub window: String,
    pub granularity: String,
    /// The session the `session` window resolved to, if any.
    pub session_id: Option<String>,
    pub points: Vec<SeriesPoint>,
    /// True when at least one recall offset was counted; drives the
    /// "estimate only where recall logging exists" UI note.
    pub has_recall_signal: bool,
    pub enabled: bool,
}

impl SeriesData {
    fn disabled(window: SeriesWindow, enabled: bool) -> Self {
        SeriesData {
            window: window.label(),
            granularity: window.granularity().to_string(),
            session_id: None,
            points: Vec::new(),
            has_recall_signal: false,
            enabled,
        }
    }
}

/// Time-ordered cumulative burn-up for the dashboard chart, with the
/// counterfactual "without memhub" overlay. Returns immediately with
/// empty points when metrics are disabled (same contract as
/// `query_tool_data`). open_project has already run the scraper +
/// reconciler this pass, so recall→session attribution is fresh.
pub fn query_series(start: &Path, window: SeriesWindow) -> Result<SeriesData> {
    let ctx = db::open_project(start)?;
    if !ctx.config.metrics.enabled {
        return Ok(SeriesData::disabled(window, false));
    }
    let conn = &ctx.conn;

    let raw = match window {
        SeriesWindow::Session => fetch_session_turn_rows(conn)?,
        SeriesWindow::Days(n) => fetch_session_window_rows(conn, Some(n))?,
        SeriesWindow::All => fetch_session_window_rows(conn, None)?,
    };

    let session_id = match window {
        SeriesWindow::Session => raw.session_id.clone(),
        _ => None,
    };

    let mut points = Vec::with_capacity(raw.rows.len());
    let mut cum_actual: i64 = 0;
    let mut cum_offset: i64 = 0;
    let mut cum_recalls: i64 = 0;
    let mut last_x: i64 = i64::MIN;
    for r in raw.rows {
        cum_actual += r.delta.max(0);
        cum_offset += r.offset.max(0);
        cum_recalls += r.recalls.max(0);
        // uPlot requires strictly increasing x. Same-second points
        // (common for fast turns) get nudged forward a second.
        let mut x = r.x.unwrap_or(last_x.saturating_add(1));
        if x <= last_x {
            x = last_x.saturating_add(1);
        }
        last_x = x;
        points.push(SeriesPoint {
            x,
            label: r.label,
            actual: cum_actual,
            counterfactual: cum_actual + cum_offset,
            delta: r.delta,
            recall_offset: cum_offset,
            recalls: cum_recalls,
        });
    }

    Ok(SeriesData {
        window: window.label(),
        granularity: window.granularity().to_string(),
        session_id,
        has_recall_signal: cum_offset > 0,
        points,
        enabled: true,
    })
}

/// One pre-cumulative source row: this point's own spend, its own
/// recall offset, its own recall count, and an optional epoch x.
struct RawRow {
    x: Option<i64>,
    label: String,
    delta: i64,
    offset: i64,
    recalls: i64,
}

struct RawRows {
    rows: Vec<RawRow>,
    session_id: Option<String>,
}

/// Per-turn rows for the most-recently-started session. The
/// counterfactual offset is spread across turns by recall timestamp:
/// each turn carries the recall offset for this session's recalls
/// whose `ts` falls at/under that turn's `ts` and after the prior
/// turn's. Turns with an unparseable ts still appear (synthetic x);
/// any not-yet-placed offset lands on the final turn so the session
/// total always reconciles.
fn fetch_session_turn_rows(conn: &rusqlite::Connection) -> Result<RawRows> {
    let session_id: Option<String> = conn
        .query_row(
            "SELECT session_id FROM session_metrics \
             ORDER BY started_at DESC LIMIT 1",
            [],
            |r| r.get(0),
        )
        .optional()?;

    let Some(sid) = session_id else {
        return Ok(RawRows {
            rows: Vec::new(),
            session_id: None,
        });
    };

    // Turns in transcript (append) order.
    let mut stmt = conn.prepare(
        "SELECT CAST(strftime('%s', ts) AS INTEGER) AS x, \
                ts, input_tokens + output_tokens AS delta \
         FROM session_turn_metrics \
         WHERE session_id = ?1 \
         ORDER BY id",
    )?;
    struct Turn {
        x: Option<i64>,
        ts_raw: Option<String>,
        delta: i64,
    }
    let turns: Vec<Turn> = stmt
        .query_map(params![sid], |row| {
            Ok(Turn {
                x: row.get(0)?,
                ts_raw: row.get::<_, Option<String>>(1)?,
                delta: row.get(2)?,
            })
        })?
        .filter_map(|r| r.ok())
        .collect();

    // Fetch raw bundle/ledger per recall. Session-scoped offset is computed
    // in Rust below rather than in SQL so the one-load-per-session semantics
    // are easy to read and test.
    struct RawRecall {
        rx: Option<i64>,
        bundle: i64,
        ledger: i64,
    }
    let mut rstmt = conn.prepare(
        "SELECT CAST(strftime('%s', ts) AS INTEGER) AS rx, \
                bundle_tokens, ledger_tokens \
         FROM recall_metrics \
         WHERE session_id = ?1 \
         ORDER BY datetime(ts)",
    )?;
    let raw_recalls: Vec<RawRecall> = rstmt
        .query_map(params![sid], |row| {
            Ok(RawRecall {
                rx: row.get(0)?,
                bundle: row.get(1)?,
                ledger: row.get(2)?,
            })
        })?
        .filter_map(|r| r.ok())
        .collect();

    // Session-scoped offset: charge the ledger once (minimum observed
    // ledger_tokens as a proxy for session-start size) for sessions that had
    // at least one successful (non-empty) recall. Empty-bundle recalls are not
    // savings events and contribute nothing. The full offset lands on the turn
    // of the first non-empty recall; all other recall slots get 0.
    let session_baseline = raw_recalls.iter().map(|r| r.ledger).min().unwrap_or(0);
    let non_empty_bundle: i64 = raw_recalls
        .iter()
        .filter(|r| r.bundle > 0)
        .map(|r| r.bundle)
        .sum();
    let has_non_empty = raw_recalls.iter().any(|r| r.bundle > 0);
    let session_offset = if has_non_empty {
        (session_baseline - non_empty_bundle).max(0)
    } else {
        0
    };

    let mut first_non_empty_done = false;
    let recalls: Vec<(Option<i64>, i64)> = raw_recalls
        .into_iter()
        .map(|r| {
            let extra = if r.bundle > 0 && !first_non_empty_done {
                first_non_empty_done = true;
                session_offset
            } else {
                0
            };
            (r.rx, extra)
        })
        .collect();

    let total_recalls = recalls.len() as i64;
    let mut rows = Vec::with_capacity(turns.len());
    let mut recall_idx = 0usize;
    let n_turns = turns.len();
    for (i, t) in turns.into_iter().enumerate() {
        // Attach every recall whose epoch is <= this turn's epoch.
        // Recalls with no epoch, or all remaining on the last turn,
        // are flushed so the per-session total always lands.
        let mut offset = 0i64;
        let mut counted = 0i64;
        let is_last = i + 1 == n_turns;
        while recall_idx < recalls.len() {
            let (rx, extra) = recalls[recall_idx];
            let due = match (rx, t.x) {
                (Some(r), Some(tx)) => r <= tx,
                _ => false,
            };
            if due || is_last {
                offset += extra;
                counted += 1;
                recall_idx += 1;
            } else {
                break;
            }
        }
        rows.push(RawRow {
            x: t.x,
            label: t
                .ts_raw
                .clone()
                .unwrap_or_else(|| format!("turn {}", i + 1)),
            delta: t.delta,
            offset,
            recalls: counted,
        });
    }
    // Defensive: if there were no turns but recalls exist, surface a
    // single synthetic point so the offset isn't silently dropped.
    if rows.is_empty() && total_recalls > 0 {
        let offset: i64 = recalls.iter().map(|(_, e)| *e).sum();
        rows.push(RawRow {
            x: None,
            label: "session".to_string(),
            delta: 0,
            offset,
            recalls: total_recalls,
        });
    }

    Ok(RawRows {
        rows,
        session_id: Some(sid),
    })
}

/// One cumulative point per session within the window (no 10-row cap),
/// oldest first. Each session carries its own attributed recall
/// offset and recall count.
fn fetch_session_window_rows(conn: &rusqlite::Connection, days: Option<u32>) -> Result<RawRows> {
    let (sql, modifier): (String, Option<String>) = match days {
        Some(n) => (
            "SELECT s.session_id, \
                    CAST(strftime('%s', s.started_at) AS INTEGER) AS x, \
                    datetime(s.started_at, 'localtime') AS started_local, \
                    s.input_tokens + s.output_tokens AS delta, \
                    COALESCE(( \
                        SELECT CASE \
                            WHEN SUM(CASE WHEN r.bundle_tokens > 0 THEN 1 ELSE 0 END) > 0 \
                            THEN MAX(0, MIN(r.ledger_tokens) \
                                 - SUM(CASE WHEN r.bundle_tokens > 0 THEN r.bundle_tokens ELSE 0 END)) \
                            ELSE 0 \
                        END \
                        FROM recall_metrics r WHERE r.session_id = s.session_id \
                    ), 0) AS offset, \
                    COALESCE(( \
                        SELECT COUNT(*) FROM recall_metrics r \
                        WHERE r.session_id = s.session_id \
                    ), 0) AS recalls \
             FROM session_metrics s \
             WHERE datetime(s.started_at) >= datetime('now', ?1) \
             ORDER BY datetime(s.started_at) ASC, s.id ASC"
                .to_string(),
            Some(format!("-{n} days")),
        ),
        None => (
            "SELECT s.session_id, \
                    CAST(strftime('%s', s.started_at) AS INTEGER) AS x, \
                    datetime(s.started_at, 'localtime') AS started_local, \
                    s.input_tokens + s.output_tokens AS delta, \
                    COALESCE(( \
                        SELECT CASE \
                            WHEN SUM(CASE WHEN r.bundle_tokens > 0 THEN 1 ELSE 0 END) > 0 \
                            THEN MAX(0, MIN(r.ledger_tokens) \
                                 - SUM(CASE WHEN r.bundle_tokens > 0 THEN r.bundle_tokens ELSE 0 END)) \
                            ELSE 0 \
                        END \
                        FROM recall_metrics r WHERE r.session_id = s.session_id \
                    ), 0) AS offset, \
                    COALESCE(( \
                        SELECT COUNT(*) FROM recall_metrics r \
                        WHERE r.session_id = s.session_id \
                    ), 0) AS recalls \
             FROM session_metrics s \
             ORDER BY datetime(s.started_at) ASC, s.id ASC"
                .to_string(),
            None,
        ),
    };

    let mut stmt = conn.prepare(&sql)?;
    let map = |row: &rusqlite::Row| -> rusqlite::Result<RawRow> {
        let sid: String = row.get(0)?;
        Ok(RawRow {
            x: row.get(1)?,
            label: row
                .get::<_, Option<String>>(2)?
                .unwrap_or_else(|| sid.chars().take(8).collect()),
            delta: row.get(3)?,
            offset: row.get(4)?,
            recalls: row.get(5)?,
        })
    };
    let rows: Vec<RawRow> = match modifier {
        Some(m) => stmt
            .query_map(params![m], map)?
            .filter_map(|r| r.ok())
            .collect(),
        None => stmt.query_map([], map)?.filter_map(|r| r.ok()).collect(),
    };
    Ok(RawRows {
        rows,
        session_id: None,
    })
}

