        fs::write(dir.join(K9_DETECTION_FILENAME), "# state").expect("write file");

        assert!(!detect_k9(temp.path(), DEFAULT_AGENT_DOCS_PATH));
        assert!(detect_k9(temp.path(), "docs/k9"));
    }

