        write(
            &file,
            &[
                r#"{"type":"assistant","timestamp":"2026-05-15T13:00:00.000Z","message":{"usage":{"input_tokens":9,"output_tokens":1}}}"#,
            ],
        );
        scrape_claude_file(conn, &file).expect("scrape 2");

        let (count, sum_in): (i64, i64) = conn
            .query_row(
                "SELECT COUNT(*), COALESCE(SUM(input_tokens),0) \
                 FROM session_turn_metrics WHERE session_id = 'sess-C'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .expect("turn query");
        assert_eq!(count, 1, "old turn rows must be cleared on shrink");
        assert_eq!(sum_in, 9, "only the rewritten content counts");
    }
}

//! cl100k_base token counting for the metrics subsystem (decision 74).
//!
//! Backed by `tiktoken-rs`, which embeds the cl100k_base BPE table
//! into the binary at compile time — no runtime network call, no
//! filesystem dependency. The first call lazily builds the singleton
//! `CoreBPE` (~10 ms on a modern laptop); subsequent calls reuse it.
//!
//! **This is an estimate, not ground truth.** Anthropic's real
//! tokenizer is not public; cl100k_base is OpenAI's GPT-3.5/GPT-4
//! tokenizer and drifts roughly ±10% from Anthropic's counts on
//! typical English prose. We use it symmetrically across both sides
//! of every comparison (e.g. "bundle tokens vs full-ledger tokens"),
//! so the ratio stays sound even though the absolute number is
//! rounded. Do not display these numbers as if they were authoritative
//! per-request token counts.
//!
//! ## Calibration (task 63, decision 109)
//!
//! The ±10% bias above is a fixed multiplier, not noise, so it can be
//! corrected once. `memhub metrics calibrate` measures the
//! cl100k→Anthropic ratio against the real `count_tokens` API (the
//! single network touch in all of memhub, explicitly user-invoked —
//! see `metrics::calibrate`) and stores it as `[metrics]
//! calibration_factor`. The metrics entry points then call
//! [`set_calibration_factor`] so [`tokens_of`] scales every count by it.
//! Default `1.0` is an exact passthrough, so an uncalibrated install —
//! and every unit test that calls `tokens_of` directly — is
//! byte-identical to a pre-calibration build. Use [`raw_token_count`]
//! when you need the unscaled cl100k count (the calibrator does, to
//! compute the ratio without applying it to itself).

use std::sync::OnceLock;
use std::sync::atomic::{AtomicU64, Ordering};

use tiktoken_rs::{CoreBPE, cl100k_base};

static BPE: OnceLock<CoreBPE> = OnceLock::new();

/// Calibration multiplier as raw f64 bits. `0` is a sentinel for
/// "unset" and reads back as `1.0`, so the static needs no lazy init
/// and the uncalibrated path is a plain atomic load.
static CALIBRATION_BITS: AtomicU64 = AtomicU64::new(0);

fn bpe() -> &'static CoreBPE {
    BPE.get_or_init(|| {
        cl100k_base().expect("cl100k_base BPE is bundled at compile time and must initialize")
    })
}

/// Set the process-wide calibration multiplier applied by [`tokens_of`].
/// Called from the metrics entry points with `[metrics]
/// calibration_factor`. Non-finite or non-positive values are rejected
/// (reset to the `1.0` passthrough) so a corrupt config can never zero
/// out or NaN every token count.
pub fn set_calibration_factor(factor: f64) {
    let safe = if factor.is_finite() && factor > 0.0 {
        factor
    } else {
        1.0
    };
    CALIBRATION_BITS.store(safe.to_bits(), Ordering::Relaxed);
}

/// Current calibration multiplier; `1.0` when unset.
pub fn calibration_factor() -> f64 {
    let bits = CALIBRATION_BITS.load(Ordering::Relaxed);
    if bits == 0 { 1.0 } else { f64::from_bits(bits) }
}

/// Raw cl100k_base token count for `s`, with no calibration applied.
///
/// Uses `encode_ordinary` (no special-token handling) — appropriate
/// because the metrics subsystem counts user-visible text, not chat
/// transcripts with special tokens already injected by the agent.
pub fn raw_token_count(s: &str) -> usize {
    bpe().encode_ordinary(s).len()
}

/// Estimate the Anthropic-equivalent token count for `s`: the raw
/// cl100k count scaled by the calibration multiplier and rounded. When
/// uncalibrated (`factor == 1.0`) this is exactly [`raw_token_count`].
pub fn tokens_of(s: &str) -> usize {
    let raw = raw_token_count(s);
    let factor = calibration_factor();
    if factor == 1.0 {
        return raw;
    }
    (raw as f64 * factor).round() as usize
}

#[cfg(test)]
mod tests {
    use super::*;

    // The calibration multiplier is process-global state; these tests
    // mutate it, so they must not run concurrently with assumptions
    // about its value. Each test sets the factor it needs and resets to
    // 1.0 at the end. They share one #[test] to keep ordering explicit.
    #[test]
    fn calibration_scales_and_rounds_then_resets() {
        let sample = "the quick brown fox jumps over the lazy dog";
        let raw = raw_token_count(sample);
        assert!(raw > 0);

        // Uncalibrated passthrough.
        set_calibration_factor(1.0);
        assert_eq!(tokens_of(sample), raw);

        // A clean 2x scales and stays integral.
        set_calibration_factor(2.0);
        assert_eq!(calibration_factor(), 2.0);
        assert_eq!(tokens_of(sample), raw * 2);

        // A fractional factor rounds to nearest.
        set_calibration_factor(1.1);
        assert_eq!(tokens_of(sample), (raw as f64 * 1.1).round() as usize);

        // raw_token_count never reflects the factor.
        assert_eq!(raw_token_count(sample), raw);

        // Garbage factors are rejected back to 1.0.
        set_calibration_factor(0.0);
        assert_eq!(calibration_factor(), 1.0);
        set_calibration_factor(-3.0);
        assert_eq!(calibration_factor(), 1.0);
        set_calibration_factor(f64::NAN);
        assert_eq!(calibration_factor(), 1.0);
        set_calibration_factor(f64::INFINITY);
        assert_eq!(calibration_factor(), 1.0);

        // Leave the global as the default for any later test.
        set_calibration_factor(1.0);
        assert_eq!(tokens_of(sample), raw);
    }
}

use std::fs;
use std::path::{Path, PathBuf};

use rusqlite::{Connection, OptionalExtension, params};

use crate::Result;
use crate::commands::metrics::query_period_totals;
use crate::db;
use crate::metrics::formatter::render_period_block;
use crate::models::{
    Decision, FACT_STALE_AFTER_DAYS, Fact, NarrativeEntry, RenderResult, SessionNote, Task,
};
use crate::sync_md;

const PROJECT_FILENAME: &str = "PROJECT.md";
const LEDGER_FILENAME: &str = "PROJECT_LEDGER.md";
const SESSION_NOTE_RENDER_LIMIT: usize = 10;
const RECENT_WRITE_RENDER_LIMIT: usize = 50;
const RECENT_WRITE_WINDOW_DAYS: i64 = 30;

#[derive(Debug)]
struct RecentWrite {
    at: String,
    actor: String,
    table_name: String,
    action: String,
    reason: String,
}

#[derive(Debug)]
struct RenderSnapshot {
    project_name: String,
    generated_at: String,
    memhub_version: &'static str,
    state: Option<NarrativeEntry>,
    arch: Option<NarrativeEntry>,
    decisions: Vec<Decision>,
    tasks: Vec<Task>,
    facts: Vec<Fact>,
    stale_fact_count: i64,
    open_task_count: i64,
    recent_session_notes: Vec<SessionNote>,
    recent_writes: Vec<RecentWrite>,
    token_accounting_section: Option<String>,
}

pub fn render_project(start: &Path, actor: &str) -> Result<RenderResult> {
    let ctx = db::open_project(start)?;

    let snapshot = build_snapshot(
        &ctx.conn,
        &ctx.config.project_name,
        ctx.config.metrics.enabled,
    )?;
    let project_md = format_project_md(&snapshot);
    let ledger_md = format_ledger_md(&snapshot);

    let output_dir = ctx.paths.repo_root.join(&ctx.config.render.output_dir);
    fs::create_dir_all(&output_dir)?;

    let backup_dir = ctx.paths.memhub_dir.join("backups").join("rendered");

    let project_path = output_dir.join(PROJECT_FILENAME);
    let ledger_path = output_dir.join(LEDGER_FILENAME);

    // Phase 1 — prepare all files. Backups and temp writes happen up front so
    // any failure here leaves the existing rendered outputs untouched. Either
    // both staged files exist or neither destination is at risk.
    let staged = [
        stage_rendered_file(&project_path, &project_md, &backup_dir)?,
        stage_rendered_file(&ledger_path, &ledger_md, &backup_dir)?,
    ];

    // Phase 2 — commit each temp into place. `fs::rename` is an atomic replace
    // on both Unix and Windows, so the per-file swap has no missing-file
    // window. The irreducible inconsistency window is between the two renames,
    // and the prior content of each file remains recoverable from `backup_dir`.
    let mut written = Vec::new();
    let mut backups = Vec::new();
    for (index, item) in staged.iter().enumerate() {
        if let Err(err) = fs::rename(&item.temp_path, &item.dest_path) {
            // Best-effort cleanup of unrenamed temps from this render.
            let _ = fs::remove_file(&item.temp_path);
            for later in &staged[index + 1..] {
                let _ = fs::remove_file(&later.temp_path);
            }
            return Err(err.into());
        }
        written.push(item.dest_path.clone());
        if let Some(backup) = item.backup_path.clone() {
            backups.push(backup);
        }
    }

    db::log_write(&ctx.conn, actor, "render", None, "render", "memhub render")?;

    Ok(RenderResult {
        output_dir,
        project_md_path: project_path,
        ledger_md_path: ledger_path,
        written_files: written,
        backup_files: backups,
    })
}

struct StagedFile {
    dest_path: PathBuf,
    temp_path: PathBuf,
    backup_path: Option<PathBuf>,
}

fn stage_rendered_file(path: &Path, content: &str, backup_dir: &Path) -> Result<StagedFile> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }

    let backup_path = if path.exists() {
        Some(sync_md::create_backup(path, backup_dir)?)
    } else {
        None
    };

    let temp_path = sync_md::temp_path_for(path)?;
    fs::write(&temp_path, content)?;

    Ok(StagedFile {
        dest_path: path.to_path_buf(),
        temp_path,
        backup_path,
    })
}

fn build_snapshot(
    conn: &Connection,
    project_name: &str,
    metrics_enabled: bool,
) -> Result<RenderSnapshot> {
    let generated_at: String =
        conn.query_row("SELECT strftime('%Y-%m-%dT%H:%M:%SZ', 'now')", [], |row| {
            row.get(0)
        })?;

    Ok(RenderSnapshot {
        project_name: project_name.to_string(),
        generated_at,
        memhub_version: env!("CARGO_PKG_VERSION"),
        state: load_latest_narrative(conn, "project_state")?,
        arch: load_latest_narrative(conn, "project_arch")?,
        decisions: load_decisions(conn)?,
        tasks: load_tasks(conn)?,
        facts: load_facts(conn)?,
        stale_fact_count: count_stale_facts(conn)?,
        open_task_count: count_open_tasks(conn)?,
        recent_session_notes: load_recent_session_notes(conn)?,
        recent_writes: load_recent_writes(conn)?,
        token_accounting_section: if metrics_enabled {
            load_token_accounting_section(conn)?
        } else {
            None
        },
    })
}

fn load_latest_narrative(conn: &Connection, table: &str) -> Result<Option<NarrativeEntry>> {
    let sql = format!(
        "SELECT id, body, actor, actor_raw, created_at
         FROM {table}
         WHERE project_id = 1
         ORDER BY created_at DESC, id DESC
         LIMIT 1"
    );
    let entry = conn
        .query_row(&sql, [], |row| {
            Ok(NarrativeEntry {
                id: row.get(0)?,
                body: row.get(1)?,
                actor: row.get(2)?,
                actor_raw: row.get(3)?,
                created_at: row.get(4)?,
            })
        })
        .optional()?;
    Ok(entry)
}

fn load_decisions(conn: &Connection) -> Result<Vec<Decision>> {
    let mut stmt = conn.prepare(
        "SELECT id, title, rationale, status, decided_at, source, summary
         FROM decisions
         WHERE project_id = 1
         ORDER BY decided_at DESC, id DESC",
    )?;
    let rows = stmt
        .query_map([], |row| {
            Ok(Decision {
                id: row.get(0)?,
                title: row.get(1)?,
                rationale: row.get(2)?,
                status: row.get(3)?,
                decided_at: row.get(4)?,
                source: row.get(5)?,
                summary: row.get(6)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

fn load_tasks(conn: &Connection) -> Result<Vec<Task>> {
    let mut stmt = conn.prepare(
        "SELECT id, title, status, notes, created_at, updated_at
         FROM tasks
         WHERE project_id = 1
         ORDER BY
             CASE status
                 WHEN 'open' THEN 0
                 WHEN 'blocked' THEN 1
                 WHEN 'done' THEN 2
                 ELSE 3
             END,
             updated_at DESC,
             id DESC",
    )?;
    let rows = stmt
        .query_map([], |row| {
            Ok(Task {
                id: row.get(0)?,
                title: row.get(1)?,
                status: row.get(2)?,
                notes: row.get(3)?,
                created_at: row.get(4)?,
                updated_at: row.get(5)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

fn load_facts(conn: &Connection) -> Result<Vec<Fact>> {
    let mut stmt = conn.prepare(
        "SELECT id, key, value, confidence, source, verified_at, created_at,
                CASE
                    WHEN verified_at IS NULL THEN 1
                    WHEN (julianday('now') - julianday(verified_at)) > ?1 THEN 1
                    ELSE 0
                END AS is_stale
         FROM facts
         WHERE project_id = 1
         ORDER BY key ASC",
    )?;
    let rows = stmt
        .query_map(params![FACT_STALE_AFTER_DAYS], |row| {
            let is_stale_int: i64 = row.get(7)?;
            Ok(Fact {
                id: row.get(0)?,
                key: row.get(1)?,
                value: row.get(2)?,
                confidence: row.get(3)?,
                source: row.get(4)?,
                verified_at: row.get(5)?,
                created_at: row.get(6)?,
                is_stale: is_stale_int != 0,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

fn count_stale_facts(conn: &Connection) -> Result<i64> {
    let count: i64 = conn.query_row(
        "SELECT COUNT(*) FROM facts
         WHERE project_id = 1
           AND (verified_at IS NULL
                OR (julianday('now') - julianday(verified_at)) > ?1)",
        params![FACT_STALE_AFTER_DAYS],
        |row| row.get(0),
    )?;
    Ok(count)
}

fn count_open_tasks(conn: &Connection) -> Result<i64> {
    let count: i64 = conn.query_row(
        "SELECT COUNT(*) FROM tasks
         WHERE project_id = 1 AND status = 'open'",
        [],
        |row| row.get(0),
    )?;
    Ok(count)
}

fn load_recent_session_notes(conn: &Connection) -> Result<Vec<SessionNote>> {
    let mut stmt = conn.prepare(
        "SELECT id, actor, actor_raw, text, created_at
         FROM session_notes
         WHERE project_id = 1
         ORDER BY created_at DESC, id DESC
         LIMIT ?1",
    )?;
    let rows = stmt
        .query_map(params![SESSION_NOTE_RENDER_LIMIT as i64], |row| {
            Ok(SessionNote {
                id: row.get(0)?,
                actor: row.get(1)?,
                actor_raw: row.get(2)?,
                text: row.get(3)?,
                created_at: row.get(4)?,
            })
        })?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

fn load_token_accounting_section(conn: &Connection) -> Result<Option<String>> {
    let totals = query_period_totals(conn, 7)?;
    if totals.is_empty() {
        return Ok(None);
    }
    Ok(Some(render_period_block("Last 7 days", &totals)))
}

fn load_recent_writes(conn: &Connection) -> Result<Vec<RecentWrite>> {
    let mut stmt = conn.prepare(
        "SELECT at, actor, table_name, action, reason
         FROM writes_log
         WHERE project_id = 1
           AND at >= datetime('now', '-' || ?1 || ' days')
         ORDER BY at DESC, id DESC
         LIMIT ?2",
    )?;
    let rows = stmt
        .query_map(
            params![RECENT_WRITE_WINDOW_DAYS, RECENT_WRITE_RENDER_LIMIT as i64],
            |row| {
                Ok(RecentWrite {
                    at: row.get(0)?,
                    actor: row.get(1)?,
                    table_name: row.get(2)?,
                    action: row.get(3)?,
                    reason: row.get(4)?,
                })
            },
        )?
        .collect::<std::result::Result<Vec<_>, _>>()?;
    Ok(rows)
}

fn format_project_md(s: &RenderSnapshot) -> String {
    let mut out = String::new();
    out.push_str(&render_header(s));
    out.push('\n');
    out.push_str(&format!("# {}\n\n", s.project_name));

    out.push_str("## Currently building\n\n");
    match &s.state {
        Some(entry) => {
            out.push_str(strip_leading_heading(&entry.body, "## Currently building").trim_end());
            out.push('\n');
            out.push('\n');
            out.push_str(&format!(
                "_Last updated {} by {}._\n\n",
                entry.created_at, entry.actor
            ));
        }
        None => {
            out.push_str(
                "_No project_state recorded. Use `memhub state set <body>` to populate._\n\n",
            );
        }
    }

    out.push_str("## Architecture\n\n");
    match &s.arch {
        Some(entry) => {
            out.push_str(strip_leading_heading(&entry.body, "## Architecture").trim_end());
            out.push('\n');
            out.push('\n');
            out.push_str(&format!(
                "_Last updated {} by {}._\n\n",
                entry.created_at, entry.actor
            ));
        }
        None => {
            out.push_str(
                "_No project_arch recorded. Use `memhub arch set <body>` to populate._\n\n",
            );
        }
    }

    out.push_str("## Recent session notes\n\n");
    if s.recent_session_notes.is_empty() {
        out.push_str("_No session notes recorded._\n");
    } else {
        for note in &s.recent_session_notes {
            out.push_str(&format!(
                "- **{}** ({}) — {}\n",
                note.created_at,
                note.actor,
                collapse_inline(&note.text)
            ));
        }
    }

    if let Some(section) = &s.token_accounting_section {
        out.push('\n');
        out.push_str("## Token Accounting (last 7 days)\n\n");
        out.push_str(section);
        out.push('\n');
    }

    out
}

fn format_ledger_md(s: &RenderSnapshot) -> String {
    let mut out = String::new();
    out.push_str(&render_header(s));
    out.push('\n');
    out.push_str(&format!("# {} — Ledger\n\n", s.project_name));

    out.push_str("## Decisions\n\n");
    if s.decisions.is_empty() {
        out.push_str("_No decisions recorded._\n\n");
    } else {
        out.push_str(&format!(
            "_{} decision(s). Most recent first._\n\n",
            s.decisions.len()
        ));
        for d in &s.decisions {
            out.push_str(&format!("### D{} — {}\n\n", d.id, d.title));
            out.push_str(&format!(
                "**Status:** {} • **Decided:** {} • **Source:** {}\n\n",
                d.status, d.decided_at, d.source
            ));
            if d.rationale.trim().is_empty() {
                out.push_str("_No rationale recorded._\n\n");
            } else {
                out.push_str(d.rationale.trim_end());
                out.push_str("\n\n");
            }
            out.push_str("---\n\n");
        }
    }

    out.push_str("## Backlog\n\n");
    if s.tasks.is_empty() {
        out.push_str("_No tasks recorded._\n\n");
    } else {
        out.push_str(&format!(
            "_{} task(s), {} open. Open first, then by recency._\n\n",
            s.tasks.len(),
            s.open_task_count
        ));
        for t in &s.tasks {
            out.push_str(&format!("### T{} — {}\n\n", t.id, t.title));
            out.push_str(&format!(
                "**Status:** {} • **Updated:** {}\n\n",
                t.status, t.updated_at
            ));
            match t.notes.as_deref() {
                Some(notes) if !notes.trim().is_empty() => {
                    out.push_str(notes.trim_end());
                    out.push_str("\n\n");
                }
                _ => out.push_str("_No notes._\n\n"),
            }
            out.push_str("---\n\n");
        }
    }

    out.push_str("## Facts\n\n");
    if s.facts.is_empty() {
        out.push_str("_No facts recorded._\n\n");
    } else {
        out.push_str(&format!(
            "_{} fact(s), {} stale._\n\n",
            s.facts.len(),
            s.stale_fact_count
        ));
        out.push_str("| Key | Value | Source | Confidence | Verified | Stale |\n");
        out.push_str("|-----|-------|--------|-----------|----------|-------|\n");
        for f in &s.facts {
            out.push_str(&format!(
                "| {} | {} | {} | {:.2} | {} | {} |\n",
                escape_table_cell(&f.key),
                escape_table_cell(&f.value),
                escape_table_cell(&f.source),
                f.confidence,
                escape_table_cell(f.verified_at.as_deref().unwrap_or("never")),
                if f.is_stale { "yes" } else { "no" }
            ));
        }
        out.push('\n');
    }

    out.push_str(&format!(
        "## Recent activity (last {} days)\n\n",
        RECENT_WRITE_WINDOW_DAYS
    ));
    if s.recent_writes.is_empty() {
        out.push_str("_No write activity in window._\n");
    } else {
        out.push_str("| When | Actor | Table | Action | Reason |\n");
        out.push_str("|------|-------|-------|--------|--------|\n");
        for w in &s.recent_writes {
            out.push_str(&format!(
                "| {} | {} | {} | {} | {} |\n",
                escape_table_cell(&w.at),
                escape_table_cell(&w.actor),
                escape_table_cell(&w.table_name),
                escape_table_cell(&w.action),
                escape_table_cell(&w.reason),
            ));
        }
    }

    out
}

fn render_header(s: &RenderSnapshot) -> String {
    format!(
        "<!-- memhub:rendered -->\n\
         <!-- DO NOT EDIT. Generated from .memhub/project.sqlite. -->\n\
         <!-- To change content, use memhub CLI; then re-run `memhub render`. -->\n\
         <!-- Generated at: {} by memhub {} -->\n",
        s.generated_at, s.memhub_version
    )
}

fn collapse_inline(text: &str) -> String {
    text.replace(['\n', '\r'], " ")
}

/// Wrap-up convention is to draft narrative bodies as standalone mini-docs
/// that lead with the section heading they belong under. Render adds its own
/// fixed section wrapper, so if the body also starts with that heading the
/// output ends up with two identical headings back-to-back. Strip a leading
/// matching heading (case-sensitive) so either body style renders cleanly.
fn strip_leading_heading<'a>(body: &'a str, heading: &str) -> &'a str {
    let trimmed = body.trim_start_matches(['\n', '\r']);
    let Some(rest) = trimmed.strip_prefix(heading) else {
        return body;
    };
    // Require end-of-string or a line break after the heading so we don't
    // truncate paragraphs that merely begin with the same text.
    if rest.is_empty() || rest.starts_with('\n') || rest.starts_with("\r\n") {
        rest.trim_start_matches(['\n', '\r'])
    } else {
        body
    }
}

fn escape_table_cell(text: &str) -> String {
    text.replace('|', "\\|").replace(['\n', '\r'], " ")
}

#[cfg(test)]
mod tests {
    use super::strip_leading_heading;

    #[test]
    fn strips_matching_leading_heading() {
        let body = "## Currently building\n\nM8 details here.\n";
        assert_eq!(
