//! BGE-small-en-v1.5 embedding wrapper.
//!
//! The ONNX model and tokenizer files are bundled into the memhub binary at
//! build time by `build.rs`. The first call to [`embed_one`] or
//! [`embed_batch`] constructs the fastembed [`TextEmbedding`] handle; all
//! subsequent calls reuse it.

use std::sync::{Mutex, OnceLock};

use fastembed::{
    InitOptionsUserDefined, Pooling, TextEmbedding, TokenizerFiles, UserDefinedEmbeddingModel,
};

use crate::{MemhubError, Result};

pub const EMBEDDING_MODEL_NAME: &str = "bge-small-en-v1.5";
pub const EMBEDDING_DIMENSION: usize = 384;

const MODEL_ONNX: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/bge-small-en-v1.5/model.onnx"));
const TOKENIZER_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/bge-small-en-v1.5/tokenizer.json"
));
const CONFIG_JSON: &[u8] =
    include_bytes!(concat!(env!("OUT_DIR"), "/bge-small-en-v1.5/config.json"));
const SPECIAL_TOKENS_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/bge-small-en-v1.5/special_tokens_map.json"
));
const TOKENIZER_CONFIG_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/bge-small-en-v1.5/tokenizer_config.json"
));

static MODEL: OnceLock<Mutex<TextEmbedding>> = OnceLock::new();

fn shared() -> Result<&'static Mutex<TextEmbedding>> {
    if let Some(m) = MODEL.get() {
        return Ok(m);
    }
    let tokenizer_files = TokenizerFiles {
        tokenizer_file: TOKENIZER_JSON.to_vec(),
        config_file: CONFIG_JSON.to_vec(),
        special_tokens_map_file: SPECIAL_TOKENS_JSON.to_vec(),
        tokenizer_config_file: TOKENIZER_CONFIG_JSON.to_vec(),
    };
    let user_model = UserDefinedEmbeddingModel::new(MODEL_ONNX.to_vec(), tokenizer_files)
        .with_pooling(Pooling::Cls);
    let model = TextEmbedding::try_new_from_user_defined(user_model, InitOptionsUserDefined::new())
        .map_err(|e| {
            MemhubError::Embedding(format!("failed to load {EMBEDDING_MODEL_NAME}: {e}"))
        })?;
    // If another thread won the race, drop ours and return the winner.
    Ok(MODEL.get_or_init(|| Mutex::new(model)))
}

/// Embed a single text into a 384-dim vector.
pub fn embed_one(text: &str) -> Result<Vec<f32>> {
    let mut out = embed_batch(&[text])?;
    out.pop()
        .ok_or_else(|| MemhubError::Embedding("empty embedding output".to_string()))
}

/// Embed a batch of texts. Each output is a 384-dim vector in the same order.
pub fn embed_batch<S: AsRef<str> + Send + Sync>(texts: &[S]) -> Result<Vec<Vec<f32>>> {
    if texts.is_empty() {
        return Ok(Vec::new());
    }
    let cell = shared()?;
    let mut model = cell
        .lock()
        .map_err(|e| MemhubError::Embedding(format!("model mutex poisoned: {e}")))?;
    let documents: Vec<&str> = texts.iter().map(AsRef::as_ref).collect();
    model
        .embed(documents, None)
        .map_err(|e| MemhubError::Embedding(format!("embed failed: {e}")))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn smoke_embed_dimension_and_finite() {
        let v = embed_one("memhub local-first project memory").expect("embed_one");
        assert_eq!(v.len(), EMBEDDING_DIMENSION, "expected 384-dim vector");
        assert!(
            v.iter().all(|f| f.is_finite()),
            "embedding contained non-finite values"
        );
        let norm: f32 = v.iter().map(|f| f * f).sum::<f32>().sqrt();
        // BGE outputs are L2-normalized by fastembed; allow some float slack.
        assert!(
            (0.5..=1.5).contains(&norm),
            "embedding norm {norm} is unexpectedly far from 1.0"
        );
    }

    #[test]
    fn smoke_embed_batch_preserves_order_and_length() {
        let texts = vec!["alpha", "beta", "gamma"];
        let vecs = embed_batch(&texts).expect("embed_batch");
        assert_eq!(vecs.len(), 3);
        assert!(vecs.iter().all(|v| v.len() == EMBEDDING_DIMENSION));
        // alpha and beta should not be identical vectors.
        assert!(vecs[0] != vecs[1]);
    }
}

//! Retrieval layer for memhub M8 (SQL+RAG hybrid recall).
//!
//! Owns the bundled embedding model and (as of task #21) the bundled
//! cross-encoder re-ranker. The hybrid scoring path lives in `recall`;
//! `rerank` is the optional post-blend reordering step gated by
//! `[retrieval] use_reranker` in project config.

pub mod embeddings;
pub mod persist;
pub mod recall;
pub mod rerank;

pub use embeddings::{EMBEDDING_DIMENSION, EMBEDDING_MODEL_NAME, embed_batch, embed_one};
pub use persist::{
    SourceType, decision_embed_text, doc_chunk_embed_text, eager_embed_in_tx, fact_embed_text,
    task_embed_text,
};
pub use recall::{RecallHit, RecallOptions, RecallResponse, RecallWarning, recall};
pub use rerank::RERANKER_MODEL_NAME;

//! Eager-embed write path for retrieval (M8 PR3).
//!
//! Fact/decision/task writers call into this module inside the same DB
//! transaction as the source-row write. Per addendum §5 the flow is:
//!   1. Compute a stable content_hash over the embed text.
//!   2. Look up the existing embedding row for (source_type, source_id,
//!      active model).
//!   3. If the hash matches, no-op (the embedding is already current).
//!   4. Otherwise run the embedding model and UPSERT the row inside the
//!      same transaction.
//!
//! When [`RetrievalMode::Fts`] is configured the whole path is a no-op:
//! the embedding model never loads and the embeddings table stays empty.
//! Switching to [`RetrievalMode::Hybrid`] on an existing repo will need
//! a one-shot backfill (`memhub index rebuild` — not yet shipped) before
//! the embeddings table is fully populated.

use rusqlite::{OptionalExtension, Transaction, params};
use sha2::{Digest, Sha256};

use crate::config::RetrievalMode;
use crate::retrieval::embeddings::{EMBEDDING_DIMENSION, EMBEDDING_MODEL_NAME, embed_one};
use crate::{MemhubError, Result};

/// Source row kind that an embedding refers back to.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum SourceType {
    Fact,
    Decision,
    Task,
    DocChunk,
}

impl SourceType {
    pub fn as_str(self) -> &'static str {
        match self {
            SourceType::Fact => "fact",
            SourceType::Decision => "decision",
            SourceType::Task => "task",
            SourceType::DocChunk => "doc_chunk",
        }
    }
}

/// Build the embed text for a fact. Embeds key + value so the model sees
/// the label and the body in one short sentence-like string.
pub fn fact_embed_text(key: &str, value: &str) -> String {
    format!("{key}: {value}")
}

/// Build the embed text for a decision. When `summary` is present and
/// non-empty, it is prepended so the bi-encoder picks up the natural-
/// language framing in addition to the (often jargon-heavy) title. Title
/// and rationale are separated by a blank line so the tokenizer sees
/// them as distinct segments. See decision 72 / task #23.
pub fn decision_embed_text(title: &str, rationale: &str, summary: Option<&str>) -> String {
    match summary {
        Some(s) if !s.trim().is_empty() => format!("{s}\n\n{title}\n\n{rationale}"),
        _ => format!("{title}\n\n{rationale}"),
    }
}

/// Build the embed text for a task. Notes are optional; when present they
/// follow the title separated by a blank line.
pub fn task_embed_text(title: &str, notes: Option<&str>) -> String {
    match notes {
        Some(n) if !n.is_empty() => format!("{title}\n\n{n}"),
        _ => title.to_string(),
    }
}

/// Build the embed text for a doc chunk. The heading-path breadcrumb
/// (e.g. `Components > Buttons`) acts as the title-analog so the
/// bi-encoder and cross-encoder both see the section context, not just
/// the prose body. Mirrors the `title\n\nbody` shape used for tasks.
pub fn doc_chunk_embed_text(heading_path: &str, body: &str) -> String {
    if heading_path.trim().is_empty() {
        body.to_string()
    } else {
        format!("{heading_path}\n\n{body}")
    }
}

/// Eager-embed entry point. No-op when mode != Hybrid.
pub fn eager_embed_in_tx(
    tx: &Transaction<'_>,
    mode: RetrievalMode,
    source_type: SourceType,
    source_id: i64,
    embed_text: &str,
) -> Result<()> {
    if mode != RetrievalMode::Hybrid {
        return Ok(());
    }

    let content_hash = sha256_hex(embed_text);
    let source_type_str = source_type.as_str();

    let existing_hash: Option<String> = tx
        .query_row(
            "SELECT content_hash FROM embeddings
             WHERE source_type = ?1 AND source_id = ?2 AND model_name = ?3",
            params![source_type_str, source_id, EMBEDDING_MODEL_NAME],
            |row| row.get(0),
        )
        .optional()?;

    if existing_hash.as_deref() == Some(content_hash.as_str()) {
        return Ok(());
    }

    let vector = embed_one(embed_text)?;
    if vector.len() != EMBEDDING_DIMENSION {
        return Err(MemhubError::Embedding(format!(
            "expected {EMBEDDING_DIMENSION}-dim vector, got {}",
            vector.len()
        )));
    }
    let blob = vector_to_le_bytes(&vector);

    tx.execute(
        "DELETE FROM embeddings
         WHERE source_type = ?1 AND source_id = ?2 AND model_name = ?3",
        params![source_type_str, source_id, EMBEDDING_MODEL_NAME],
    )?;
    tx.execute(
        "INSERT INTO embeddings(
            project_id, source_type, source_id, model_name,
            dimension, vector, content_hash
        ) VALUES (1, ?1, ?2, ?3, ?4, ?5, ?6)",
        params![
            source_type_str,
            source_id,
            EMBEDDING_MODEL_NAME,
            EMBEDDING_DIMENSION as i64,
            blob,
            content_hash,
        ],
    )?;

    Ok(())
}

fn sha256_hex(text: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(text.as_bytes());
    let digest = hasher.finalize();
    const HEX: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(digest.len() * 2);
    for b in digest {
        out.push(HEX[(b >> 4) as usize] as char);
        out.push(HEX[(b & 0x0f) as usize] as char);
    }
    out
}

fn vector_to_le_bytes(v: &[f32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(v.len() * 4);
    for f in v {
        out.extend_from_slice(&f.to_le_bytes());
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decision_embed_text_without_summary_matches_legacy_format() {
        let out = decision_embed_text("Title", "Rationale body", None);
        assert_eq!(out, "Title\n\nRationale body");
    }

    #[test]
    fn decision_embed_text_with_summary_prepends_it() {
        let out = decision_embed_text(
            "content_hash drift detection per embedding",
            "Store a hash of source body alongside each vector.",
            Some("How does memhub know when an embedding has gone stale?"),
        );
        assert_eq!(
            out,
            "How does memhub know when an embedding has gone stale?\n\n\
