    #[test]
    fn docs_are_opt_in_and_signal_availability() {
        // `doc add` auto-enables include_docs_in_default, but in FTS
        // mode the cross-encoder never runs, so the safety rule must
        // still keep unvetted docs out of the default bundle while
        // `available_docs` advertises the un-surfaced chunks. Explicit
        // doc scope returns the chunk and zeroes the signal.
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        fact::add(
            temp.path(),
            "build-command",
            "cargo build",
            "user",
            "cli:user",
        )
        .expect("fact");
        let doc_file = temp.path().join("spec.md");
        std::fs::write(
            &doc_file,
            "# Design Spec\n\n## Shapes\n\nButtons use a 4px corner radius for a crisp engineered look.\n",
        )
        .expect("write doc");
        doc::add(temp.path(), &doc_file, None, "cli:user").expect("ingest doc");

        // Default scope: no doc hits, but availability is signalled.
        let default = recall(
            temp.path(),
            RecallOptions {
                query: "corner radius for buttons".to_string(),
                mode: Some(RetrievalMode::Fts),
                max_results: 10,
                source_types: vec![],
                include_stale: None,
                accepted_only: None,
                use_reranker: None,
                min_rerank_score: None,
                log_metrics: false,
            },
        )
        .expect("default recall");
        assert!(
            default.results.iter().all(|h| h.source_type != "doc_chunk"),
            "docs must not appear in the default bundle"
        );
        assert!(
            default.available_docs >= 1,
            "available_docs must flag ingested-but-unsearched docs, got {}",
            default.available_docs
        );

        // Opt-in scope: the chunk surfaces and the signal zeroes out.
        let scoped = recall(
            temp.path(),
            RecallOptions {
                query: "corner radius for buttons".to_string(),
                mode: Some(RetrievalMode::Fts),
                max_results: 10,
                source_types: vec![SourceType::DocChunk],
                include_stale: None,
                accepted_only: None,
                use_reranker: None,
                min_rerank_score: None,
                log_metrics: false,
            },
        )
        .expect("doc-scoped recall");
        assert!(
            scoped.results.iter().any(|h| h.source_type == "doc_chunk"),
            "doc-scoped recall must return the ingested chunk"
        );
        assert_eq!(
            scoped.available_docs, 0,
            "available_docs is 0 when the caller already scoped to docs"
        );
    }

    /// Two ingested docs (a code style guide and a UI style guide).
    /// A code-flavored query must surface the code doc and the doc
    /// floor must keep the off-topic UI doc out of the default bundle;
    /// the inverse query flips it. This is the user's own
    /// "depends on the task at hand" example, and it calibrates
    /// `DEFAULT_DOC_MIN_RERANK_SCORE` — if the constant is mis-tuned,
    /// one of these assertions fails with the offending rerank scores.
    #[test]
    fn doc_default_recall_floor_routes_by_task_relevance() {
        let temp = tempdir().expect("tempdir");
        seed(temp.path());

        // Doc chunks embed only in hybrid mode; the cross-encoder must
        // run for the doc floor to apply at all.
        let cfg_path = temp.path().join(".memhub/config.toml");
        let mut cfg = ProjectConfig::load(&cfg_path).expect("load cfg");
        cfg.retrieval.mode = RetrievalMode::Hybrid;
        cfg.save(&cfg_path).expect("save cfg");

        let code_doc = temp.path().join("code-style-guide.md");
        std::fs::write(
            &code_doc,
            "# Rust Code Style Guide\n\n\
             ## Error Handling\n\n\
             New fallible functions return `crate::Result<T>`. Never call \
             `unwrap()` outside tests. Convert an IO failure with `map_err` \
             into `MemhubError::InvalidInput` and propagate it upward with \
             the `?` operator so the caller decides how to recover.\n\n\
             ## Naming\n\n\
             Functions are snake_case verbs; modules are nouns. Avoid \
             abbreviations in any public API signature.\n",
        )
        .expect("write code doc");
        doc::add(temp.path(), &code_doc, None, "cli:user").expect("ingest code doc");

        let ui_doc = temp.path().join("ui-style-guide.md");
        std::fs::write(
            &ui_doc,
            "# UI Style Guide\n\n\
             ## Color Palette\n\n\
             The primary accent is teal #1F8A8A painted on a near-black \
             #0B0B0C canvas. Never use pure black for the background.\n\n\
             ## Spacing And Typography\n\n\
             Lay everything out on an 8px base grid. Buttons take 12px \
             vertical and 20px horizontal padding. Headings use a humanist \
             sans on a 1.25 modular scale; body copy is 16px at 1.5 line \
             height.\n",
        )
        .expect("write ui doc");
        doc::add(temp.path(), &ui_doc, None, "cli:user").expect("ingest ui doc");

        let is_ui_chunk = |b: &str| {
            b.contains("#1F8A8A") || b.contains("8px base grid") || b.contains("modular scale")
        };
        let is_code_chunk =
            |b: &str| b.contains("map_err") || b.contains("snake_case") || b.contains("Result<T>");

        // Code-flavored query: code doc in, UI doc out.
        let code_q = recall(
            temp.path(),
            RecallOptions {
                query: "convention for returning and propagating errors from a new function"
                    .to_string(),
                mode: Some(RetrievalMode::Hybrid),
                max_results: 6,
                source_types: vec![],
                include_stale: None,
                accepted_only: None,
                use_reranker: None,
                min_rerank_score: None,
                log_metrics: false,
            },
        )
        .expect("code-flavored recall");
        let doc_hits = |r: &RecallResponse| -> Vec<(String, Option<f32>)> {
            r.results
                .iter()
                .filter(|h| h.source_type == "doc_chunk")
                .map(|h| (h.body.clone(), h.rerank_score))
                .collect()
        };
        assert!(
            code_q
                .results
                .iter()
                .any(|h| h.source_type == "doc_chunk" && is_code_chunk(&h.body)),
            "code query must surface the code style guide; doc hits = {:?}",
            doc_hits(&code_q),
        );
        assert!(
            !code_q
                .results
                .iter()
                .any(|h| h.source_type == "doc_chunk" && is_ui_chunk(&h.body)),
            "off-topic UI doc must be filtered by the doc floor on a code query; \
             doc hits = {:?}",
            doc_hits(&code_q),
        );

        // Inverse: a UI-flavored query surfaces the UI doc, not the code one.
        let ui_q = recall(
            temp.path(),
            RecallOptions {
                query: "primary accent color and button padding for the interface".to_string(),
                mode: Some(RetrievalMode::Hybrid),
                max_results: 6,
                source_types: vec![],
                include_stale: None,
                accepted_only: None,
                use_reranker: None,
                min_rerank_score: None,
                log_metrics: false,
            },
        )
        .expect("ui-flavored recall");
        assert!(
            ui_q.results
                .iter()
                .any(|h| h.source_type == "doc_chunk" && is_ui_chunk(&h.body)),
            "ui query must surface the UI style guide; doc hits = {:?}",
            doc_hits(&ui_q),
        );
        assert!(
            !ui_q
                .results
                .iter()
                .any(|h| h.source_type == "doc_chunk" && is_code_chunk(&h.body)),
            "off-topic code doc must be filtered on a UI query; doc hits = {:?}",
            doc_hits(&ui_q),
        );

        // Flag off: even in hybrid + reranked, no doc may surface.
        let mut off = ProjectConfig::load(&cfg_path).expect("reload cfg");
        off.retrieval.include_docs_in_default = false;
        off.save(&cfg_path).expect("save cfg off");
        let gated = recall(
            temp.path(),
            RecallOptions {
                query: "convention for returning and propagating errors from a new function"
                    .to_string(),
                mode: Some(RetrievalMode::Hybrid),
                max_results: 6,
                source_types: vec![],
                include_stale: None,
                accepted_only: None,
                use_reranker: None,
                min_rerank_score: None,
                log_metrics: false,
            },
        )
        .expect("flag-off recall");
        assert!(
            gated.results.iter().all(|h| h.source_type != "doc_chunk"),
            "with include_docs_in_default=false no doc may enter the default \
             bundle; got {:?}",
            doc_hits(&gated),
        );
        assert!(
            gated.available_docs >= 1,
            "flag-off recall still advertises available docs, got {}",
            gated.available_docs,
        );
    }

    /// Only the *first* doc in a repo auto-enables default doc recall.
    /// Once a user sets the flag false, neither a re-add nor a second
    /// new doc may silently re-flip it — that escape hatch is promised
    /// in CLAUDE.md / AGENTS.md, so it gets a regression guard.
    #[test]
    fn first_doc_auto_enables_then_user_opt_out_sticks() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let cfg_path = temp.path().join(".memhub/config.toml");

        let d1 = temp.path().join("one.md");
        std::fs::write(&d1, "# One\n\nFirst doc body.\n").expect("write d1");
        let out1 = doc::add(temp.path(), &d1, None, "cli:user").expect("add d1");
        assert!(
            out1.enabled_default_recall,
            "first doc must auto-enable default recall"
        );
        assert!(
            ProjectConfig::load(&cfg_path)
                .expect("load")
                .retrieval
                .include_docs_in_default,
            "config must persist the auto-enable"
        );

        // User deliberately opts back out.
        let mut off = ProjectConfig::load(&cfg_path).expect("load");
        off.retrieval.include_docs_in_default = false;
        off.save(&cfg_path).expect("save off");

        // A second, brand-new doc must NOT re-flip it.
        let d2 = temp.path().join("two.md");
        std::fs::write(&d2, "# Two\n\nSecond doc body.\n").expect("write d2");
        let out2 = doc::add(temp.path(), &d2, None, "cli:user").expect("add d2");
        assert!(
            !out2.enabled_default_recall,
            "a second new doc must not re-enable after explicit opt-out"
        );
        assert!(
            !ProjectConfig::load(&cfg_path)
                .expect("load")
                .retrieval
                .include_docs_in_default,
            "user opt-out must survive a second doc add"
        );

        // Neither may a re-add of the first doc (unchanged).
        let out1b = doc::add(temp.path(), &d1, None, "cli:user").expect("re-add d1");
        assert!(!out1b.enabled_default_recall);
        assert!(
            !ProjectConfig::load(&cfg_path)
                .expect("load")
                .retrieval
                .include_docs_in_default,
            "user opt-out must survive an unchanged re-add"
        );
    }

    #[test]
    fn metrics_disabled_writes_no_rows() {
        // Default config ships `metrics.enabled = false`, so even when
        // the caller asks for logging the proxy must stay silent.
        // Guards against accidentally enabling the master switch on
        // every install — the regression would silently flood every
        // unrelated repo's DB with recall_metrics rows.
        let temp = tempdir().expect("tempdir");
        seed(temp.path());

        let response = recall(
            temp.path(),
            RecallOptions {
                query: "agent originated writes review".to_string(),
                mode: Some(RetrievalMode::Fts),
                max_results: 5,
                source_types: vec![],
                include_stale: None,
                accepted_only: None,
                use_reranker: None,
                min_rerank_score: None,
                log_metrics: true,
            },
        )
        .expect("recall");

        assert!(!response.results.is_empty());
        assert_eq!(count_recall_metrics(temp.path()), 0);
    }

    #[test]
    fn metrics_enabled_writes_one_row_per_recall() {
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let cfg_path = temp.path().join(".memhub/config.toml");
        let mut cfg = ProjectConfig::load(&cfg_path).expect("load");
        cfg.metrics.enabled = true;
        cfg.metrics.recall_proxy = true;
        cfg.save(&cfg_path).expect("save");

        seed(temp.path());

        let response = recall(
            temp.path(),
            RecallOptions {
                query: "agent originated writes review".to_string(),
                mode: Some(RetrievalMode::Fts),
                max_results: 5,
                source_types: vec![],
                include_stale: None,
                accepted_only: None,
                use_reranker: None,
                min_rerank_score: None,
                log_metrics: true,
            },
        )
        .expect("recall");
        assert!(!response.results.is_empty());

        let ctx = crate::db::open_project(temp.path()).expect("open");
        let mut stmt = ctx
            .conn
            .prepare(
                "SELECT query_hash, bundle_tokens, ledger_tokens, rerank_used, result_count \
                 FROM recall_metrics",
            )
            .expect("prepare");
        let rows: Vec<(String, i64, i64, i64, i64)> = stmt
            .query_map(params![], |r| {
                Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?, r.get(4)?))
            })
            .expect("query")
            .collect::<std::result::Result<Vec<_>, _>>()
            .expect("collect");

        assert_eq!(rows.len(), 1, "exactly one row per recall");
        let (query_hash, bundle_tokens, ledger_tokens, rerank_used, result_count) = &rows[0];
        assert_eq!(query_hash.len(), 64);
        assert!(
            *bundle_tokens > 0,
            "bundle_tokens must reflect returned hits"
        );
        assert_eq!(
            *ledger_tokens, 0,
            "no rendered ledger in this tempdir, so ledger_tokens = 0"
        );
        assert_eq!(*rerank_used, 0, "fts mode never invokes the re-ranker");
        assert_eq!(*result_count, response.results.len() as i64);
    }

    #[test]
    fn metrics_log_opt_out_skips_insert_even_when_enabled() {
        // Eval and dashboard set log_metrics = false. Pin that
        // behavior so a future refactor can't silently start logging
        // calibration sweeps to the dashboard.
        let temp = tempdir().expect("tempdir");
        init::run(temp.path()).expect("init");
        let cfg_path = temp.path().join(".memhub/config.toml");
        let mut cfg = ProjectConfig::load(&cfg_path).expect("load");
        cfg.metrics.enabled = true;
        cfg.metrics.recall_proxy = true;
        cfg.save(&cfg_path).expect("save");

        seed(temp.path());

        recall(
            temp.path(),
            RecallOptions {
                query: "agent originated writes review".to_string(),
                mode: Some(RetrievalMode::Fts),
                max_results: 5,
                source_types: vec![],
                include_stale: None,
                accepted_only: None,
                use_reranker: None,
                min_rerank_score: None,
                log_metrics: false,
            },
        )
        .expect("recall");

        assert_eq!(count_recall_metrics(temp.path()), 0);
    }
}

//! ms-marco-MiniLM-L-6-v2 cross-encoder re-ranker.
//!
//! The ONNX model and tokenizer files are bundled into the memhub binary
//! at build time by `build.rs`. The first call to [`rerank`] constructs
//! the fastembed [`TextRerank`] handle (~1–2 s ONNX session init); all
//! subsequent calls reuse it.
//!
//! Selected over BGE-reranker-v2-m3 in the cross-encoder bake-off
//! (decisions 68–70): +17.7pp Recall@1 over baseline, ~15× faster, no
//! keyword-query regressions. Bundled unconditionally; the `[retrieval]
//! use_reranker` config knob gates whether `recall::run` actually calls
//! into this module.

use std::sync::{Mutex, OnceLock};

use fastembed::{
    OnnxSource, RerankInitOptionsUserDefined, TextRerank, TokenizerFiles, UserDefinedRerankingModel,
};

use crate::{MemhubError, Result};

pub const RERANKER_MODEL_NAME: &str = "ms-marco-MiniLM-L-6-v2";

const MODEL_ONNX: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/ms-marco-MiniLM-L-6-v2/model.onnx"
));
const TOKENIZER_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/ms-marco-MiniLM-L-6-v2/tokenizer.json"
));
const CONFIG_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/ms-marco-MiniLM-L-6-v2/config.json"
));
const SPECIAL_TOKENS_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/ms-marco-MiniLM-L-6-v2/special_tokens_map.json"
));
const TOKENIZER_CONFIG_JSON: &[u8] = include_bytes!(concat!(
    env!("OUT_DIR"),
    "/ms-marco-MiniLM-L-6-v2/tokenizer_config.json"
));

static MODEL: OnceLock<Mutex<TextRerank>> = OnceLock::new();

fn shared() -> Result<&'static Mutex<TextRerank>> {
    if let Some(m) = MODEL.get() {
        return Ok(m);
    }
    let tokenizer_files = TokenizerFiles {
        tokenizer_file: TOKENIZER_JSON.to_vec(),
        config_file: CONFIG_JSON.to_vec(),
        special_tokens_map_file: SPECIAL_TOKENS_JSON.to_vec(),
        tokenizer_config_file: TOKENIZER_CONFIG_JSON.to_vec(),
    };
    let user_model =
        UserDefinedRerankingModel::new(OnnxSource::Memory(MODEL_ONNX.to_vec()), tokenizer_files);
    let model =
        TextRerank::try_new_from_user_defined(user_model, RerankInitOptionsUserDefined::default())
            .map_err(|e| {
                MemhubError::Rerank(format!("failed to load {RERANKER_MODEL_NAME}: {e}"))
            })?;
    Ok(MODEL.get_or_init(|| Mutex::new(model)))
}

/// Score (query, doc) pairs with the bundled cross-encoder and return
/// `(input_index, score)` pairs sorted by descending relevance.
///
/// `docs[i]` is the document originally at input position `i`. The
/// returned `input_index` tells the caller how to reorder them; the
/// `score` is the cross-encoder relevance logit (positive = relevant,
/// negative = irrelevant — see decision 70 follow-up on rerank-score-
/// based nonsense rejection). Empty input returns an empty Vec without
/// loading the model.
pub fn rerank(query: &str, docs: &[String]) -> Result<Vec<(usize, f32)>> {
    if docs.is_empty() {
        return Ok(Vec::new());
    }
    let cell = shared()?;
    let mut model = cell
        .lock()
        .map_err(|e| MemhubError::Rerank(format!("rerank mutex poisoned: {e}")))?;
    let doc_refs: Vec<&str> = docs.iter().map(String::as_str).collect();
    let results = model
        .rerank(query, &doc_refs, false, None)
        .map_err(|e| MemhubError::Rerank(format!("rerank failed: {e}")))?;
    Ok(results.into_iter().map(|r| (r.index, r.score)).collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rerank_empty_input_returns_empty_without_loading_model() {
        // Important: this must not trigger MODEL init. If it did, the test
        // would pay ~1–2 s of ONNX session setup. The early-return for
        // empty docs guards that.
        let out = rerank("anything", &[]).expect("empty rerank");
        assert!(out.is_empty());
    }

    #[test]
    fn rerank_returns_permutation_of_input_indices() {
        let docs = vec![
            "Rust is a systems programming language with strong memory safety".to_string(),
            "Cats are domesticated felines kept as household pets".to_string(),
            "The borrow checker enforces ownership rules at compile time".to_string(),
        ];
        let scored = rerank("how does rust prevent memory bugs", &docs).expect("rerank");
        assert_eq!(scored.len(), docs.len());
        let mut indices: Vec<usize> = scored.iter().map(|(i, _)| *i).collect();
        indices.sort();
        assert_eq!(indices, vec![0, 1, 2], "must be a permutation");
        // The cat doc (index 1) is clearly unrelated; it should not rank #1.
        assert_ne!(scored[0].0, 1, "off-topic doc should not be top-ranked");
        // Scores must be sorted descending — the top is the highest-relevance.
        for w in scored.windows(2) {
            assert!(w[0].1 >= w[1].1, "rerank scores must be descending");
        }
    }
}

use std::fs;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

use rusqlite::{Connection, OptionalExtension};

use crate::db;
use crate::models::MarkdownSyncResult;
use crate::{MemhubError, Result};

const AGENTS_FILENAME: &str = "AGENTS.md";
const CLAUDE_FILENAME: &str = "CLAUDE.md";
const RENDERED_SUBDIR: &str = "rendered";

pub fn sync_project(start: &Path) -> Result<MarkdownSyncResult> {
    let ctx = db::open_project(start)?;
    let body = render_managed_body(&ctx.conn)?;
    let output_dir = ctx.paths.memhub_dir.join(RENDERED_SUBDIR);
    fs::create_dir_all(&output_dir)?;
    let backup_dir = ctx.paths.memhub_dir.join("backups").join("markdown");

    let mut updated_files = Vec::new();
    let mut backup_files = Vec::new();

    for filename in [AGENTS_FILENAME, CLAUDE_FILENAME] {
        let path = output_dir.join(filename);
        let existing = if path.exists() {
            fs::read_to_string(&path)?
        } else {
            String::new()
        };

        if existing == body {
            continue;
        }

        let backup_path = if path.exists() {
            Some(create_backup(&path, &backup_dir)?)
        } else {
            None
        };

        write_with_replace(&path, &body)?;
        updated_files.push(path);
        if let Some(bp) = backup_path {
            backup_files.push(bp);
        }
    }

    if !updated_files.is_empty() {
        db::log_write(
            &ctx.conn,
            "cli:user",
            "markdown_sync",
            None,
            "update",
            "sync-md",
        )?;
    }

    Ok(MarkdownSyncResult {
        updated_files,
        backup_files,
    })
}

pub fn sync_if_enabled(start: &Path) -> Result<()> {
    let ctx = db::open_project(start)?;
    if ctx.config.auto_sync_md {
        let _ = sync_project(start)?;
    }

    Ok(())
}

fn render_managed_body(conn: &Connection) -> Result<String> {
    let build = load_command_summary(conn, "build")?;
    let test = load_command_summary(conn, "test")?;
    let (open_tasks, blocked_tasks) = load_task_counts(conn)?;
    let decisions = load_active_decisions(conn)?;
    let quirks = load_known_quirks(conn)?;

    let mut lines = vec![
        "# Project state (machine-local, generated by memhub)".to_string(),
        String::new(),
        "This file is regenerated from the local memhub DB on every sync.".to_string(),
        "It is never committed to git. Each machine maintains its own copy.".to_string(),
        String::new(),
        format!("**Build:** {}", format_command_summary(build.as_ref())),
        format!("**Test:** {}", format_command_summary(test.as_ref())),
        format!(
            "**Active tasks:** {} open, {} blocked - see `memhub task list --status open`",
            open_tasks, blocked_tasks
        ),
        String::new(),
        "## Durable decisions".to_string(),
    ];

    if decisions.is_empty() {
        lines.push("- None recorded.".to_string());
    } else {
        for (title, decided_at) in decisions {
            lines.push(format!("- {} ({})", title, decided_at));
        }
    }

    lines.push(String::new());
    lines.push("## Known quirks".to_string());
    if quirks.is_empty() {
        lines.push("- None recorded.".to_string());
    } else {
        for quirk in quirks {
            lines.push(format!("- {}", quirk));
        }
    }

    lines.push(String::new());

    Ok(lines.join("\n"))
}

pub(crate) fn create_backup(path: &Path, backup_dir: &Path) -> Result<PathBuf> {
    fs::create_dir_all(backup_dir)?;

    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| {
            MemhubError::InvalidInput(format!("invalid markdown filename: {}", path.display()))
        })?;
    let stamp = backup_stamp()?;

    for attempt in 0..1000 {
        let suffix = if attempt == 0 {
            String::new()
        } else {
            format!("-{attempt}")
        };
        let backup_path = backup_dir.join(format!("{stamp}{suffix}-{file_name}.bak"));
        if !backup_path.exists() {
            let _ = fs::copy(path, &backup_path)?;
            return Ok(backup_path);
        }
    }

    Err(MemhubError::InvalidInput(format!(
        "failed to allocate a backup path for {}",
        path.display()
    )))
}

pub(crate) fn backup_stamp() -> Result<String> {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|err| {
            MemhubError::InvalidInput(format!("system clock is before unix epoch: {err}"))
        })?;
    Ok(format!("{}-{:09}", now.as_secs(), now.subsec_nanos()))
}

pub(crate) fn write_with_replace(path: &Path, updated_content: &str) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }

    let temp_path = temp_path_for(path)?;
    fs::write(&temp_path, updated_content)?;

    // `fs::rename` atomically replaces an existing regular file on both Unix
    // (rename(2)) and Windows (MoveFileExW + MOVEFILE_REPLACE_EXISTING). No
    // pre-remove step is needed, and removing creates a window where the
    // destination temporarily does not exist.
    if let Err(err) = fs::rename(&temp_path, path) {
        let _ = fs::remove_file(&temp_path);
        return Err(err.into());
    }

    Ok(())
}

pub(crate) fn temp_path_for(path: &Path) -> Result<PathBuf> {
    let file_name = path
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| {
            MemhubError::InvalidInput(format!("invalid markdown filename: {}", path.display()))
        })?;
    let stamp = backup_stamp()?;
    Ok(path.with_file_name(format!(".{file_name}.{stamp}.tmp")))
}

fn load_command_summary(conn: &Connection, kind: &str) -> Result<Option<(String, String)>> {
    conn.query_row(
        "SELECT cmdline, last_run_at
         FROM commands
         WHERE project_id = 1
           AND kind = ?1
           AND last_exit_code = 0
           AND last_run_at IS NOT NULL
         ORDER BY last_run_at DESC
         LIMIT 1",
        [kind],
        |row| Ok((row.get(0)?, row.get(1)?)),
    )
    .optional()
    .map_err(Into::into)
}

fn format_command_summary(summary: Option<&(String, String)>) -> String {
    match summary {
        Some((cmdline, last_run_at)) => {
            format!("`{}` (last verified: {})", cmdline, last_run_at)
        }
        None => "`n/a`".to_string(),
    }
}

fn load_task_counts(conn: &Connection) -> Result<(i64, i64)> {
    let open: i64 = conn.query_row(
        "SELECT COUNT(*)
         FROM tasks
         WHERE project_id = 1 AND status = 'open'",
        [],
        |row| row.get(0),
    )?;
    let blocked: i64 = conn.query_row(
        "SELECT COUNT(*)
         FROM tasks
         WHERE project_id = 1 AND status = 'blocked'",
        [],
        |row| row.get(0),
    )?;

    Ok((open, blocked))
}

fn load_active_decisions(conn: &Connection) -> Result<Vec<(String, String)>> {
    let mut stmt = conn.prepare(
        "SELECT title, decided_at
         FROM decisions
         WHERE project_id = 1 AND status = 'active'
         ORDER BY decided_at DESC, id DESC
         LIMIT 5",
    )?;

    let rows = stmt.query_map([], |row| Ok((row.get(0)?, row.get(1)?)))?;
    rows.collect::<std::result::Result<Vec<_>, _>>()
        .map_err(Into::into)
}

fn load_known_quirks(conn: &Connection) -> Result<Vec<String>> {
    let mut stmt = conn.prepare(
        "SELECT key, value
         FROM facts
         WHERE project_id = 1
           AND (
             key LIKE 'quirk.%'
             OR key LIKE 'quirk:%'
             OR key = 'quirk'
             OR key LIKE 'known-quirk%'
             OR key LIKE 'known_quirk%'
           )
         ORDER BY key ASC",
    )?;

    let rows = stmt.query_map([], |row| {
        let key: String = row.get(0)?;
        let value: String = row.get(1)?;
        Ok(match key.as_str() {
            "quirk" => value,
            _ => format!("{key}: {value}"),
        })
    })?;

    rows.collect::<std::result::Result<Vec<_>, _>>()
        .map_err(Into::into)
}

use std::fs;
use std::path::Path;
use std::process::Command;

use memhub::commands::init;
use memhub::db;
use rusqlite::params;
use serde_json::Value;
use tempfile::tempdir;

fn memhub_bin() -> &'static str {
    env!("CARGO_BIN_EXE_memhub")
}

fn run_cli(repo: &Path, args: &[&str]) -> std::process::Output {
    Command::new(memhub_bin())
        .args(args)
        .current_dir(repo)
        .env("MEMHUB_LOG", "off")
        .output()
        .expect("spawn memhub binary")
}

fn write_agent_docs(repo: &Path, decisions: &str, backlog: &str) {
    let dir = repo.join("agent_docs");
    fs::create_dir_all(&dir).expect("create agent_docs");
    fs::write(dir.join("project_state.md"), "# state\n").expect("write state marker");
    if !decisions.is_empty() {
        fs::write(dir.join("project_decisions.md"), decisions).expect("write decisions");
    }
    if !backlog.is_empty() {
        fs::write(dir.join("project_backlog.md"), backlog).expect("write backlog");
    }
}

fn count(repo: &Path, sql: &str) -> i64 {
    let ctx = db::open_project(repo).expect("open project");
    ctx.conn
        .query_row(sql, params![], |row| row.get::<_, i64>(0))
        .expect("count")
}

