    ]);
    let root = temp.path();
    set_hybrid(root);

    let response = locate(
        root,
        LocateOptions {
            query: "compute checksum".to_string(),
            limit: 5,
            use_reranker: false,
        },
    )
    .expect("locate");

    assert_eq!(response.mode, RetrievalMode::Hybrid);
    assert!(!response.results.is_empty());
    let top = &response.results[0];
