#[test]
fn status_reports_counts_without_creating_the_index() {
    let temp = repo_with_files(&[("src/a.rs", "pub fn alpha() {}\n")]);
    let root = temp.path();

    // Before any index op, status reports not-built and does NOT create it.
    let before = code_index::status(root).expect("status");
    assert!(!before.exists);
    assert_eq!(before.files_total, 0);
    assert!(
        !code_index_db_path(root).exists(),
        "status must not create DB"
    );

    code_index::refresh(root).expect("refresh");
    let after = code_index::status(root).expect("status");
    assert!(after.exists);
    assert!(after.files_total >= 1);
    assert!(after.chunks_total >= 1);
    assert!(after.schema_version.is_some());
    // Freshly indexed against HEAD: not stale.
    assert!(!after.head_stale());
}

#[test]
fn remove_index_wipes_the_disposable_db() {
    let temp = repo_with_files(&[("src/a.rs", "pub fn alpha() {}\n")]);
    let root = temp.path();
    code_index::refresh(root).expect("refresh");
    assert!(code_index_db_path(root).exists());

    let outcome = code_index::remove_index(root).expect("remove");
    assert!(outcome.removed);
    assert!(!code_index_db_path(root).exists());

    // Removing again is a clean no-op.
    let again = code_index::remove_index(root).expect("remove again");
    assert!(!again.removed);
}

//! Eager-embed write-path tests for M8 PR3.
//!
//! Verifies that fact/decision/task writers populate the embeddings table
//! when [retrieval] mode = "hybrid" and skip it entirely when mode = "fts"
//! (the default).

use std::fs;

use memhub::commands::{decision, fact, init, review, task};
use memhub::config::ProjectConfig;
use memhub::db;
use rusqlite::params;
use tempfile::tempdir;

fn switch_to_hybrid(repo_root: &std::path::Path) {
    let config_path = repo_root.join(".memhub").join("config.toml");
    let mut cfg = ProjectConfig::load(&config_path).expect("load config");
    cfg.retrieval.mode = memhub::config::RetrievalMode::Hybrid;
    cfg.save(&config_path).expect("save config");
    // Sanity: rewriting via TOML round-trip should preserve hybrid mode.
    let reloaded = ProjectConfig::load(&config_path).expect("reload");
    assert_eq!(
        reloaded.retrieval.mode,
        memhub::config::RetrievalMode::Hybrid
    );
}

fn embedding_count(conn: &rusqlite::Connection, source_type: &str, source_id: i64) -> i64 {
    conn.query_row(
        "SELECT COUNT(*) FROM embeddings WHERE source_type = ?1 AND source_id = ?2",
        params![source_type, source_id],
        |r| r.get(0),
    )
    .expect("count embeddings")
}

fn embedding_metadata(
    conn: &rusqlite::Connection,
    source_type: &str,
    source_id: i64,
) -> (i64, String, Vec<u8>) {
    conn.query_row(
        "SELECT dimension, content_hash, vector
         FROM embeddings
         WHERE source_type = ?1 AND source_id = ?2",
        params![source_type, source_id],
        |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
    )
    .expect("fetch embedding metadata")
}

