#[test]
fn shipped_golden_file_parses_cleanly() {
    // Guards against accidental schema drift in the checked-in starter set.
    let repo_root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let path = repo_root.join(DEFAULT_GOLDEN_PATH);
    let bytes = std::fs::read(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    let parsed: memhub::commands::eval::GoldenFile =
        serde_json::from_slice(&bytes).unwrap_or_else(|e| panic!("parse {}: {e}", path.display()));
    assert_eq!(parsed.version, 1);
    // Addendum §9 fixed a 12-query baseline (11 keyword match + 1 safety).
    // Decision 69 expanded the set with `semantic-` prefixed
    // natural-language queries so the cross-encoder bake-off (task #20)
    // had headroom above the keyword baseline. The new contract: keep
    // the original 12 *and* preserve both query styles.
    assert!(
        parsed.queries.len() >= 12,
        "starter golden set must keep its 12-query baseline per addendum §9; got {}",
        parsed.queries.len(),
    );
    let empties = parsed
        .queries
        .iter()
        .filter(|q| q.kind == GoldenKind::Empty)
        .count();
    assert!(
        empties >= 1,
        "starter golden set must include at least one safety (empty) probe",
    );
    let semantic = parsed
        .queries
        .iter()
        .filter(|q| q.id.starts_with("semantic-"))
        .count();
    assert!(
        semantic >= 1,
        "starter golden set must include at least one `semantic-` prefixed query per decision 69",
    );
    let keyword = parsed
        .queries
        .iter()
        .filter(|q| !q.id.starts_with("semantic-") && q.kind == GoldenKind::Match)
        .count();
    assert!(
        keyword >= 11,
        "starter golden set must keep the 11 keyword-style match queries per addendum §9; got {keyword}",
    );
}

//! Schema tests for migration 0009 (M8 PR2).
//!
//! Exercises the new contentless FTS5 tables, their sync triggers, and the
//! shape / constraints of the embeddings table. PR3 will add the writer
//! path that populates embeddings; here we drive it via raw SQL.

use memhub::commands::{decision, fact, init, task};
use memhub::db;
use rusqlite::params;
use tempfile::tempdir;

fn fts_hit(conn: &rusqlite::Connection, table: &str, query: &str) -> bool {
    // FTS5 treats bare hyphens as the NOT operator and bare colons as
    // column scopes. Wrapping in double quotes turns the input into a
    // single phrase token that matches the literal characters.
    let sql = format!("SELECT EXISTS(SELECT 1 FROM {table} WHERE {table} MATCH ?1)");
    let phrase = format!("\"{query}\"");
    conn.query_row(&sql, params![phrase], |r| r.get(0))
        .expect("fts match query")
}

