    for name in ["facts_fts", "decisions_fts", "tasks_fts", "embeddings"] {
        let count: i64 = ctx
            .conn
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master WHERE name = ?1",
                params![name],
                |r| r.get(0),
            )
            .expect("query sqlite_master");
        assert_eq!(count, 1, "{name} should exist after migration");
    }
}

