    let ctx = db::open_project(path).expect("open project");
    ctx.conn
        .execute(
            "UPDATE writes_log SET at = datetime('now', ?1) WHERE table_name = ?2",
            params![format!("-{days_ago} days"), table],
        )
        .expect("backdate writes_log");
}

