fn markdown_backup_files(repo_root: &Path) -> Vec<PathBuf> {
    let backup_dir = repo_root.join(".memhub").join("backups").join("markdown");
    if !backup_dir.exists() {
        return Vec::new();
    }

    let mut entries = fs::read_dir(backup_dir)
        .expect("read backup dir")
        .map(|entry| entry.expect("dir entry").path())
        .collect::<Vec<_>>();
    entries.sort();
    entries
}

fn find_backup_for<'a>(paths: &'a [PathBuf], file_name: &str) -> &'a Path {
    paths
        .iter()
        .find(|path| {
            path.file_name()
                .and_then(|name| name.to_str())
                .map(|name| name.contains(file_name))
                .unwrap_or(false)
        })
        .map(PathBuf::as_path)
        .expect("backup for file")
}

//! Machine-wide upgrade registry (decision 96 / task 49).
//!
//! Two guarantees are load-bearing and tested here:
//!
//! 1. The registry is self-maintaining, gated on the global store
//!    already existing, and debounced — it never creates the store and
//!    an immediate re-open does not rewrite the row.
//! 2. The **eval-regression guarantee**: a populated `known_projects`
//!    must not change recall output one bit while the repo has
//!    `[global] enabled = false`. Registry membership is not M9 opt-in.
//!
//! All assertions live in ONE test so the `HOME` override (which
//! redirects `~/.memhub/global.sqlite` into a tempdir) cannot race
//! other tests in this binary.

use memhub::commands::{fact, global, init};
use memhub::config::RetrievalMode;
use memhub::db;
use memhub::retrieval::{RecallOptions, RecallResponse, recall};
use tempfile::tempdir;

fn fts_recall(path: &std::path::Path, query: &str) -> RecallResponse {
    recall(
        path,
        RecallOptions {
            query: query.to_string(),
            mode: Some(RetrievalMode::Fts),
            max_results: 10,
            source_types: vec![],
            include_stale: None,
            accepted_only: None,
            use_reranker: None,
            min_rerank_score: None,
            log_metrics: false,
        },
    )
    .expect("recall")
}

/// Compare everything that recall promises to be stable. `elapsed_ms`
/// lives on the response and varies run to run, so it is deliberately
/// excluded — the guarantee is "byte-identical modulo wall-clock".
fn assert_recall_identical(a: &RecallResponse, b: &RecallResponse) {
    assert_eq!(
        format!("{:?}", a.results),
        format!("{:?}", b.results),
        "recall results changed when known_projects was populated \
         while [global] disabled — eval-regression guarantee violated"
    );
    assert_eq!(a.candidate_count, b.candidate_count);
    assert_eq!(a.returned_count, b.returned_count);
    assert_eq!(a.available_docs, b.available_docs);
    assert_eq!(a.mode, b.mode);
}

#[test]
fn registry_and_eval_regression_guarantee() {
    let home = tempdir().expect("home tempdir");
    // SAFETY: single-test binary; no other thread reads these vars
    // concurrently. The TMP_OK seam lets the registry accept the
    // tempdir repos this test necessarily uses; production excludes
    // OS-temp paths (covered by the registry unit test).
    unsafe {
        std::env::set_var("HOME", home.path());
        std::env::remove_var("USERPROFILE");
        std::env::set_var("MEMHUB_REGISTRY_TMP_OK", "1");
    }

    let repo = tempdir().expect("repo");
    init::run(repo.path()).expect("init");
    fact::add(
        repo.path(),
        "registry-probe",
        "alpha-value",
        "user",
        "cli:user",
    )
    .expect("seed fact");

    // --- baseline recall with NO global store ------------------------
    assert!(
        !db::global_store_exists().expect("exists check"),
        "no global store should exist yet"
    );
    let baseline = fts_recall(repo.path(), "registry-probe");
    assert!(
        !baseline.results.is_empty(),
        "seed fact must be recallable so the comparison is meaningful"
    );

    // --- no global store => registry is inert, store NOT created -----
    assert!(
        db::registry::list_known().expect("list").is_empty(),
        "registry must be empty with no global store"
    );
    let _ = db::open_project(repo.path()).expect("open with no global store");
    assert!(
        !db::global_store_exists().expect("exists check"),
        "opening a project must NOT create the global store"
    );
    assert!(
        db::registry::list_known().expect("list").is_empty(),
        "still empty — record-on-open is gated on the store existing"
    );

    // --- create the store via enable, then opt the repo back OUT ----
    global::enable(repo.path()).expect("enable");
    global::disable(repo.path()).expect("disable");
    assert!(
        db::global_store_exists().expect("exists check"),
        "enable creates the store; disable keeps it on disk"
    );

    // Opening the project now self-registers it (store exists).
    let _ = db::open_project(repo.path()).expect("open with store present");
    let known = db::registry::list_known().expect("list");
    assert_eq!(known.len(), 1, "repo should self-register exactly once");
    assert_eq!(
        known[0].last_schema.as_deref(),
        Some(db::latest_schema_version()),
        "registry records the head schema the repo was brought to"
    );

    // --- debounce: an immediate re-open does not rewrite the row ----
    let seen_before = known[0].last_seen.clone();
    let _ = db::open_project(repo.path()).expect("re-open");
    let known2 = db::registry::list_known().expect("list2");
    assert_eq!(known2.len(), 1, "no duplicate row");
    assert_eq!(
        known2[0].last_seen, seen_before,
        "debounce: last_seen unchanged within the hour window"
    );

    // --- explicit register() adds an --also-style path --------------
    let other = tempdir().expect("other repo");
    let added =
        db::registry::register(other.path(), db::latest_schema_version()).expect("register");
    assert!(added, "register persists when the global store exists");
    assert_eq!(
        db::registry::list_known().expect("list3").len(),
        2,
        "explicit register adds a second known root"
    );

    // --- self-heal: a vanished repo is pruned, not left as junk -----
    let ghost = tempdir().expect("ghost repo");
    init::run(ghost.path()).expect("init ghost");
    let _ = db::open_project(ghost.path()).expect("open ghost");
    assert_eq!(
        db::registry::list_known().expect("list4").len(),
        3,
        "ghost repo registered (repo + other + ghost)"
    );
    let ghost_path = ghost.path().to_path_buf();
    drop(ghost); // tempdir deleted on disk; registry row now dead
    let dead = db::registry::dead_roots().expect("dead_roots");
    assert!(
        dead.iter().any(|p| p == &ghost_path
            || p.canonicalize().ok() == ghost_path.canonicalize().ok()
            || p.to_string_lossy()
                .contains(ghost_path.file_name().unwrap().to_str().unwrap())),
        "the deleted ghost repo must be detected as a dead root"
    );
    let removed = db::registry::prune_dead().expect("prune");
    assert!(removed >= 1, "prune removes at least the ghost row");
    assert!(
        !db::registry::list_known()
            .expect("list5")
            .iter()
            .any(|kp| kp
                .root_path
                .to_string_lossy()
                .contains(ghost_path.file_name().unwrap().to_str().unwrap())),
        "ghost row is gone after prune"
    );

    // --- THE GUARANTEE: populated registry + [global] disabled ------
    // Recall must be byte-identical to the pre-store baseline.
    let after = fts_recall(repo.path(), "registry-probe");
    assert_recall_identical(&baseline, &after);

    unsafe { std::env::remove_var("MEMHUB_REGISTRY_TMP_OK") };
}

//! `memhub upgrade` installed-skill resync (decision 97 / task 50).
//!
//! Guarantees that are load-bearing and tested here:
//!
//! 1. An agent dir that does **not** exist is skipped, never created
//!    (mirrors `upgrade`'s "only act on what exists" posture).
//! 2. A present agent dir is additively synced from the repo's
//!    `templates/skills/`; the copy is real and idempotent.
//! 3. `--dry-run` counts but mutates nothing.
//! 4. A path that exists but is not a directory is skipped, not
//!    clobbered.
//!
//! All assertions live in ONE test so the `HOME` override cannot race
//! other tests in this binary.

use std::path::Path;

use memhub::commands::upgrade::{SkillSync, SkillSyncStatus, sync_skills};
use tempfile::tempdir;

fn find(reports: &[SkillSync], agent: &str) -> SkillSync {
    reports
        .iter()
        .find(|r| r.agent == agent)
        .unwrap_or_else(|| panic!("no report for agent {agent}"))
        .clone()
}

fn count_claude_templates(repo: &Path) -> usize {
    std::fs::read_dir(repo.join("templates").join("skills").join("claude"))
        .expect("claude templates dir")
        .flatten()
        .filter(|e| e.path().extension().and_then(|x| x.to_str()) == Some("md"))
        .count()
}

fn count_codex_templates(repo: &Path) -> usize {
    std::fs::read_dir(repo.join("templates").join("skills").join("codex"))
        .expect("codex templates dir")
        .flatten()
        .filter(|e| e.path().is_dir())
        .count()
}

fn count_opencode_skill_templates(repo: &Path) -> usize {
    std::fs::read_dir(repo.join("templates").join("skills").join("opencode"))
        .expect("opencode skill templates dir")
        .flatten()
        .filter(|e| e.path().is_dir())
        .count()
}

fn count_opencode_command_templates(repo: &Path) -> usize {
    std::fs::read_dir(repo.join("templates").join("commands").join("opencode"))
        .expect("opencode command templates dir")
        .flatten()
        .filter(|e| e.path().extension().and_then(|x| x.to_str()) == Some("md"))
        .count()
}

#[test]
fn skill_resync_additive_idempotent_and_conservative() {
    let repo = Path::new(env!("CARGO_MANIFEST_DIR"));
    let expect_claude = count_claude_templates(repo);
    let expect_codex = count_codex_templates(repo);
    let expect_opencode_skills = count_opencode_skill_templates(repo);
    let expect_opencode_commands = count_opencode_command_templates(repo);
    assert!(
        expect_claude > 0
            && expect_codex > 0
            && expect_opencode_skills > 0
            && expect_opencode_commands > 0,
        "fixture sanity: the source repo must ship skill templates"
    );

    let home = tempdir().expect("home tempdir");
    // SAFETY: single-test binary; no other thread reads HOME concurrently.
    unsafe {
        std::env::set_var("HOME", home.path());
        std::env::remove_var("USERPROFILE");
    }

    // --- 1. Neither agent dir exists => skipped, NOT created ----------
    let reports = sync_skills(repo, false);
    let claude = find(&reports, "claude");
    let codex = find(&reports, "codex");
    let opencode_skills = find(&reports, "opencode-skills");
    let opencode_commands = find(&reports, "opencode-commands");
    assert_eq!(claude.status, SkillSyncStatus::Skipped);
    assert_eq!(codex.status, SkillSyncStatus::Skipped);
    assert_eq!(opencode_skills.status, SkillSyncStatus::Skipped);
    assert_eq!(opencode_commands.status, SkillSyncStatus::Skipped);
    assert_eq!(claude.synced, 0);
    assert!(
        !home.path().join(".claude").join("commands").exists(),
        "absent Claude dir must NOT be created by a resync"
    );
    assert!(
        !home.path().join(".codex").join("skills").exists(),
        "absent Codex dir must NOT be created by a resync"
    );
    assert!(
        !home
            .path()
            .join(".config")
            .join("opencode")
            .join("skills")
            .exists(),
        "absent OpenCode skills dir must NOT be created by a resync"
    );
    assert!(
        !home
            .path()
            .join(".config")
            .join("opencode")
            .join("commands")
            .exists(),
        "absent OpenCode commands dir must NOT be created by a resync"
    );

    // --- 2. Create the agent dirs => additive real copy --------------
    let claude_dir = home.path().join(".claude").join("commands");
    let codex_dir = home.path().join(".codex").join("skills");
    let opencode_skills_dir = home.path().join(".config").join("opencode").join("skills");
    let opencode_commands_dir = home
        .path()
        .join(".config")
        .join("opencode")
        .join("commands");
    std::fs::create_dir_all(&claude_dir).expect("mk claude dir");
    std::fs::create_dir_all(&codex_dir).expect("mk codex dir");
    std::fs::create_dir_all(&opencode_skills_dir).expect("mk opencode skills dir");
    std::fs::create_dir_all(&opencode_commands_dir).expect("mk opencode commands dir");
    // A user's own skill in the shared dir must survive (additive only).
    std::fs::write(claude_dir.join("user-own.md"), b"keep me").expect("seed user skill");

    let reports = sync_skills(repo, false);
    let claude = find(&reports, "claude");
    let codex = find(&reports, "codex");
    let opencode_skills = find(&reports, "opencode-skills");
    let opencode_commands = find(&reports, "opencode-commands");
    assert_eq!(claude.status, SkillSyncStatus::Synced, "{claude:?}");
    assert_eq!(codex.status, SkillSyncStatus::Synced, "{codex:?}");
    assert_eq!(
        opencode_skills.status,
        SkillSyncStatus::Synced,
        "{opencode_skills:?}"
    );
    assert_eq!(
        opencode_commands.status,
        SkillSyncStatus::Synced,
        "{opencode_commands:?}"
    );
    assert_eq!(claude.synced, expect_claude);
    assert_eq!(codex.synced, expect_codex);
    assert_eq!(opencode_skills.synced, expect_opencode_skills);
    assert_eq!(opencode_commands.synced, expect_opencode_commands);
    // The copy is real, not just a count.
    assert!(
        claude_dir.join("recall.md").is_file(),
        "a known Claude skill template must land on disk"
    );
    assert!(
        codex_dir.join("recall").join("SKILL.md").is_file(),
        "a known Codex skill dir (with SKILL.md) must land on disk"
    );
    assert!(
        opencode_skills_dir
            .join("recall")
            .join("SKILL.md")
            .is_file(),
        "a known OpenCode skill dir (with SKILL.md) must land on disk"
    );
    assert!(
        opencode_commands_dir.join("recall.md").is_file(),
        "a known OpenCode command wrapper must land on disk"
    );
    // Additive: the user's unrelated skill is untouched.
    assert_eq!(
        std::fs::read(claude_dir.join("user-own.md")).expect("user skill"),
        b"keep me",
        "additive resync must not disturb a user's own skill"
    );

    // --- 3. Idempotent re-run: same result, no error -----------------
    let reports = sync_skills(repo, false);
    assert_eq!(find(&reports, "claude").status, SkillSyncStatus::Synced);
    assert_eq!(find(&reports, "claude").synced, expect_claude);
    assert_eq!(find(&reports, "codex").synced, expect_codex);
    assert_eq!(
        find(&reports, "opencode-skills").synced,
        expect_opencode_skills
    );
    assert_eq!(
        find(&reports, "opencode-commands").synced,
        expect_opencode_commands
    );

    // --- 4. Dry-run counts but mutates nothing -----------------------
    let probe = claude_dir.join("__dry_probe__.md");
    assert!(!probe.exists());
    let before = std::fs::read_dir(&claude_dir).unwrap().count();
    let reports = sync_skills(repo, true);
    assert_eq!(find(&reports, "claude").status, SkillSyncStatus::Synced);
    assert_eq!(find(&reports, "claude").synced, expect_claude);
    assert_eq!(
        std::fs::read_dir(&claude_dir).unwrap().count(),
        before,
        "dry-run must not add or remove any installed skill"
    );

    // --- 5. Path exists but is not a directory => skipped ------------
    let other = tempdir().expect("home2");
    unsafe { std::env::set_var("HOME", other.path()) };
    std::fs::create_dir_all(other.path().join(".codex")).expect("mk .codex");
    std::fs::write(other.path().join(".codex").join("skills"), b"not a dir")
        .expect("file where dir expected");
    let reports = sync_skills(repo, false);
    let codex = find(&reports, "codex");
    assert_eq!(codex.status, SkillSyncStatus::Skipped);
    assert!(
        codex.detail.unwrap_or_default().contains("not a directory"),
        "a non-dir at the agent path must be reported, not clobbered"
    );
    assert_eq!(
        std::fs::read(other.path().join(".codex").join("skills")).unwrap(),
        b"not a dir",
        "the offending file must be left exactly as-is"
    );

    unsafe { std::env::remove_var("HOME") };
}
